function _mh_toast_type(text, color)
    local t = tostring(text or '')
    if t:find('[MH ARB]', 1, true) then
        return 'arbitrage'
    elseif t:find('{6acfff}', 1, true) then
        return 'watch'
    elseif t:find('% рынка)', 1, true) then
        return 'favorite'
    elseif t:find('[MH] [+] Продажа', 1, true) then
        return 'sale'
    elseif t:find('[MH] [-] Покупка', 1, true) then
        return 'purchase'
    elseif t:find('{ff4444}', 1, true) or t:find('{ff6666}', 1, true)
        or t:find('{ff6644}', 1, true) or color == 0xFF4444 then
        return 'error'
    elseif t:find('{aaffaa}', 1, true) or t:find('{00cc00}', 1, true)
        or t:find('{00cc88}', 1, true) or color == 0x88FF88 then
        return 'success'
    elseif t:find('{ffaa00}', 1, true) or t:find('{ff8800}', 1, true)
        or t:find('{ff9966}', 1, true) or t:find('{FFD700}', 1, true) then
        return 'warning'
    elseif t:find('[MH TIMER]', 1, true) then
        return 'reminder'
    else
        return 'info'
    end
end
function _mh_toast_clean(text)
    local t = tostring(text or '')
    t = t:gsub('%[MH[^%]]-%]%s*', '')
    t = t:gsub('{%x%x%x%x%x%x}', '')
    if _to_utf8 then
        local ok, u = pcall(_to_utf8, t)
        if ok and u and u ~= '' then t = u end
    end
    return t
end
function _mh_notify_category(text)
    local t = tostring(text or '')
    if t:find('%[MH \xc0\xe2\xf2\xee%]') and t:find(' @ %$') then
        return 'sell_item'
    end
    if t:find('%[MH \xc0\xe2\xf2\xee%]') and (t:find('\xd1\xea\xf3\xef:') or t:find('\xd1\xea\xf3\xef \xf8\xf2')) then
        return 'buy_item'
    end
    if t:find('%[MH \xc0\xe2\xf2\xee%]') or t:find('%[FH \xc0\xe2\xf2\xee%]') then
        if t:find(' @ %$') then return 'sell_item' end
        if t:find('\xd1\xea\xf3\xef') then return 'buy_item' end
        if t:find('\xc2\xfb\xea\xeb\xe0\xe4\xea') or t:find('\xf1\xf2\xe0\xea\xee\xe2') or t:find('\xdf\xf7\xe5\xe5\xea') then
            return 'sell_status'
        end
        if t:find('\xef\xee\xea\xf3\xef') or t:find('\xef\xee\xe7\xe8\xf6\xe8') then
            return 'buy_status'
        end
        return 'sell_status'
    end
    return 'other'
end
_G.mh_notify_log = _G.mh_notify_log or {}
local function _mh_notify_should_toast(category)
    local nf = settings and settings.notify_filters
    if not nf then return true end
    if category == 'sell_item'   then return nf.sell_item   ~= false end
    if category == 'buy_item'    then return nf.buy_item    ~= false end
    if category == 'sell_status' then return nf.sell_status ~= false end
    if category == 'buy_status'  then return nf.buy_status  ~= false end
    if category == 'watch'       then return nf.watch       ~= false end
    if category == 'fav'         then return nf.fav         ~= false end
    if category == 'arb'         then return nf.arb         ~= false end
    if category == 'reminder'    then return nf.reminder    ~= false end
    return nf.other ~= false
end
function mh_notify(text, color, forced_category)
    sampAddChatMessage(text, color)
    local _cat = forced_category or _mh_notify_category(text)
    local _clean = _mh_toast_clean(text)
    table.insert(_G.mh_notify_log, {
        time     = os.date('%H:%M:%S'),
        ts       = os.time(),
        text     = _clean,
        raw      = tostring(text or ''),
        color    = color,
        category = _cat,
    })
    local _max_hist = (settings and settings.notify_history_max) or 500
    while #_G.mh_notify_log > _max_hist do
        table.remove(_G.mh_notify_log, 1)
    end
    if MH_Notify and _mh_notify_should_toast(_cat) then
        pcall(function()
            MH_Notify.add(_clean, _mh_toast_type(text, color), MH_TOAST_DURATION)
        end)
        _mh_play_alert_sound()
    end
end
function mh_notify_local(text, color, forced_category)
    local _cat = forced_category or _mh_notify_category(text)
    local _clean = _mh_toast_clean(text)
    table.insert(_G.mh_notify_log, {
        time = os.date('%H:%M:%S'),
        ts = os.time(),
        text = _clean,
        raw = tostring(text or ''),
        color = color,
        category = _cat,
    })
    local _max_hist = (settings and settings.notify_history_max) or 500
    while #_G.mh_notify_log > _max_hist do table.remove(_G.mh_notify_log, 1) end
    if MH_Notify and _mh_notify_should_toast(_cat) then
        pcall(function() MH_Notify.add(_clean, _mh_toast_type(text, color), MH_TOAST_DURATION) end)
        _mh_play_alert_sound()
    end
end
function _mh_ensure_dir(dir)
    local ok, lfs = pcall(require, 'lfs')
    if ok and lfs then
        if not lfs.attributes(dir) then pcall(lfs.mkdir, dir) end
    else
        pcall(os.execute, 'mkdir "' .. dir:gsub('/', '\\') .. '" 2>nul')
    end
end
