function _G._mh_sound_download_async()
    if _G._mh_sound_dl_busy then return end
    _G._mh_sound_dl_busy = true
    lua_thread.create(function()
        local _thr = effil.thread(function(_u)
            local requests = require('requests')
            local ok, resp = pcall(requests.request, 'GET', _u, nil)
            if not ok or not resp then return false, 'connect error' end
            if resp.status_code ~= 200 then return false, 'HTTP '..tostring(resp.status_code) end
            local data = resp.content or resp.text or ''
            if #data < 100 then return false, 'too small: '..tostring(#data)..'b' end
            return true, data
        end)(_vbr7n .. '/sound.mp3')
        local _elapsed = 0
        while _elapsed < 30000 do
            wait(300); _elapsed = _elapsed + 300
            local _st, _er = _thr:status()
            if not _st or _er then _G._mh_sound_dl_busy = false; return end
            if _st == 'completed' or _st == 'canceled' then
                local _ok2, _result = _thr:get()
                if _ok2 and _result then
                    _mh_ensure_dir(getWorkingDirectory():gsub('\\','/'):gsub('/$','') .. '/MarketHelper')
                    local _f = io.open(_G._mh_sound_path, 'wb')
                    if _f then _f:write(_result); _f:close() end
                end
                _G._mh_sound_dl_busy = false
                return
            end
        end
        _G._mh_sound_dl_busy = false
    end)
end
function _G._mh_load_sound()
    local _f = io.open(_G._mh_sound_path, 'rb')
    if not _f then
        _G._mh_sound_download_async()
        return false
    end
    _f:close()
    local ok, handle = pcall(loadAudioStream, _G._mh_sound_path)
    if ok and handle ~= nil and handle ~= false and handle ~= 0 then
        _G._mh_sound_handle = handle
        return true
    end
    _G._mh_sound_handle = nil
    return false
end
function _mh_play_alert_sound()
    if not _G.MH_SOUND_ENABLED then return end
    if not _G._mh_sound_handle then
        if not _G._mh_load_sound() then return end
    end
    pcall(setAudioStreamState, _G._mh_sound_handle, 1)
end
