local _mh_script_size_cache = nil
local function _mh_script_size()
    if _mh_script_size_cache then return _mh_script_size_cache end
    local f = io.open(_mh_script_path(), 'rb')
    if not f then return 0 end
    local sz = f:seek('end') or 0; f:close()
    _mh_script_size_cache = sz
    return sz
end
local _mh_script_hash_cache = nil
do
local function _mh_script_hash()
    if _mh_script_hash_cache then return _mh_script_hash_cache end
    local f = io.open(_mh_script_path(), 'rb')
    if not f then return '' end
    local data = f:read('*a')
    f:close()
    local h = 0
    for i = 1, #data do
        h = (h * 31 + data:byte(i)) % 4294967296
    end
    _mh_script_hash_cache = string.format('%08x', h)
    return _mh_script_hash_cache
end
end
