local function _getReliableNick(maxWait)
    local deadline = os.clock() + (maxWait or 20)
    local apiEnd = os.clock() + 5
    while os.clock() < apiEnd do
        local nick = ""
        pcall(function() nick = (settings.premium and settings.premium.nick) or "" end)
        if nick == "" or nick:find("^Player_%x+$") then
            pcall(function()
                local ok, pid = sampGetPlayerIdByCharHandle(PLAYER_PED)
                if ok then nick = sampGetPlayerNickname(pid) or "" end
            end)
        end
        if nick == "" or nick:find("^Player_%x+$") then
            pcall(function() nick = sampGetCurrentPlayerName() or "" end)
        end
        if nick == "" or nick:find("^Player_%x+$") then
            pcall(function() nick = sampGetPlayerNickname(0) or "" end)
        end
        if nick ~= "" and not nick:find("^Player_%x+$") then return nick end
        wait(500)
    end
    _statsNickResult = nil
    _statsNickDone = false
    if sampev then
        _origOnShowDialog = sampev.onShowDialog
        sampev.onShowDialog = function(id, style, title, btn1, btn2, text)
            if _statsNickResult == nil and title then
                local tl = tostring(title):lower()
                if tl:find("stat") or tostring(title):find("\xf1\xf2\xe0\xf2\xe8\xf1\xf2\xe8\xea\xe0") then
                    local cleaned = tostring(text or ""):gsub("{%x%x%x%x%x%x}", "")
                    local nm = cleaned:match("([A-Za-z0-9_]+_[A-Za-z0-9_]+)")
                    if nm and not nm:find("^Player_%x+$") then
                        _statsNickResult = nm:gsub("%s+", "")
                        _statsNickDone = true
                        return false
                    end
                end
            end
            if _origOnShowDialog then return _origOnShowDialog(id, style, title, btn1, btn2, text) end
        end
    end
    pcall(sampSendChat, "/stats")
    while os.clock() < deadline and not _statsNickDone do wait(200) end
    if sampev and _origOnShowDialog then sampev.onShowDialog = _origOnShowDialog end
    if _statsNickResult then return _statsNickResult end
    local nick = ""
    pcall(function() nick = (settings.premium and settings.premium.nick) or "" end)
    if nick == "" then
        pcall(function()
            local ok, pid = sampGetPlayerIdByCharHandle(PLAYER_PED)
            if ok then nick = sampGetPlayerNickname(pid) or "" end
        end)
    end
    if nick == "" then pcall(function() nick = sampGetCurrentPlayerName() or "" end) end
    return nick
end
