_G._mh_update_sell_price = function(name, price)
    if not name or name == '' or not price or price <= 0 then return end
    local key = name:lower()
    if not _G._mh_sell_db[key] or price < _G._mh_sell_db[key] then
        _G._mh_sell_db[key] = price
        _G._mh_sell_db[key .. '_name'] = name
        _G._mh_sell_db[key .. '_time'] = os.time()
        _G._mh_save_db()
    end
end
_G._mh_get_sell_price = function(name)
    if not name or name == '' then return nil end
    local key = name:lower()
    local price = _G._mh_sell_db[key]
    if price and price > 0 then
        local t = _G._mh_sell_db[key .. '_time'] or 0
        if os.time() - t < 7 * 86400 then return price end
    end
    return nil
end
_G._mh_manual_save_prices = function()
    local saved = 0
    local _id_to_name = nil
    local function _lookup_name_by_key(key)
        if not mh_arz_items_db then return key end
        if not _id_to_name then
            _id_to_name = {}
            for _, nm in pairs(mh_arz_items_db) do
                _id_to_name[nm:lower()] = nm
            end
        end
        return _id_to_name[key] or key
    end
    if _G._lv_shops_cache then
        for key, data in pairs(_G._lv_shops_cache) do
            if data.sell and data.sell > 0 then
                local name = _lookup_name_by_key(key)
                _G._mh_update_sell_price(name, data.sell)
                saved = saved + 1
            end
        end
    end
    if fh_other_shops then
        for _, sh in pairs(fh_other_shops) do
            if sh.sell_items then
                for _, item in ipairs(sh.sell_items) do
                    if item.name and item.price and item.price > 0 then
                        _G._mh_update_sell_price(item.name, item.price)
                        saved = saved + 1
                    end
                end
            end
        end
    end
    if mh_arz_data then
        for _, lv in ipairs(mh_arz_data) do
            if type(lv) == 'table' and lv.items_sell and lv.price_sell then
                for ii, iid in ipairs(lv.items_sell) do
                    local bid = _G._bqs3v and _G._bqs3v(iid) or iid
                    local nm = mh_arz_items_db and mh_arz_items_db[bid]
                    if nm and nm ~= '' then
                        local price = lv.price_sell[ii] or 0
                        if price > 0 then
                            _G._mh_update_sell_price(nm, price)
                            saved = saved + 1
                        end
                    end
                end
            end
        end
    end
    _G._mh_save_db()
    mh_notify('[MH] Сохранено цен продажи: ' .. saved, 0x88FF88)
    return saved
end
