-- The game can reveal a new number after relisting the same shop.
-- Keep the runtime value, relog value and own-shop snapshots in sync immediately.
function _mh_sync_current_own_shop_num(_num)
    local _n = tonumber(_num)
    if not _n or _n < 1 then return nil end
    mh_own_shop_num = _n
    if settings.general then
        settings.general.own_shop_num_saved = _n
    end
    if type(settings.my_shop_snapshot) == 'table' then
        settings.my_shop_snapshot.shop_num = _n
    end
    if type(_G._mh_own_shop_live_snapshot) == 'table' then
        _G._mh_own_shop_live_snapshot.shop_num = _n
    end
    _G._mh_own_shop_capture_num = _n
    pcall(_wfn7p)
    return _n
end

-- Read the number shown by the game for the shop currently next to the player.
-- This is deliberately checked before the relog snapshot, because after relisting
-- the saved number may belong to the previous shop.
function _mh_detect_current_shop_num_nearby()
    local _best_d, _best_n = 12.0, nil
    local _px, _py = nil, nil
    pcall(function() _px, _py = getCharCoordinates(PLAYER_PED) end)
    if not _px or not _py then return nil end
    for _tid = 0, 2047 do
        local _ok, _tt, _, _tpx, _tpy = pcall(sampGet3dTextInfoById, _tid)
        if _ok and _tt and _tpx and _tpy then
            local _txt = tostring(_tt)
            local _n = _txt:match('Лавка%s*[#№Nn]?%s*(%d+)')
            if not _n then _n = _txt:match('лавка%s*[#№Nn]?%s*(%d+)') end
            if _n then
                local _num = tonumber(_n)
                if _num and _num >= 1 and _num <= 9999 then
                    local _d = math.sqrt((_tpx-_px)^2 + (_tpy-_py)^2)
                    if _d < _best_d then
                        _best_d, _best_n = _d, _num
                    end
                end
            end
        end
    end
    return _best_n
end
function _kby5v(_method, _url, _tok, _nick, _sess)
    local requests = require('requests')
    local _sess_hdr = _sess or ''
    local _hdrs = (_sess_hdr ~= '') and { ['X-MH-Session'] = _sess_hdr } or {}
    if _nick and _nick ~= '' then
        _hdrs['X-MH-Nick'] = _nick
    end
    if _tok and _tok ~= '' then
        _hdrs['X-MH-Token'] = _tok
    end
    if next(_hdrs) == nil then _hdrs = nil end
    local function do_get(url)
        local ok, resp = pcall(requests.request, _method, url, _hdrs and {headers=_hdrs} or nil)
        if not ok or not resp then return nil end
        resp.json = nil; resp.xml = nil
        return resp
    end
    local resp = do_get(_url)
    if resp and (resp.status_code == 301 or resp.status_code == 302 or
                 resp.status_code == 303 or resp.status_code == 307) then
        local loc = (resp.headers and (resp.headers['Location'] or resp.headers['location'])) or nil
        if loc and loc ~= '' then
            local resp2 = do_get(loc)
            if resp2 then return true, resp2 end
        end
    end
    if resp then return true, resp end
    local fallback = _url:gsub('^https://', 'http://')
    if fallback ~= _url then
        local resp3 = do_get(fallback)
        if resp3 then
            if resp3.status_code == 301 or resp3.status_code == 302 or
               resp3.status_code == 303 or resp3.status_code == 307 then
                local loc = (resp3.headers and (resp3.headers['Location'] or resp3.headers['location'])) or nil
                if loc and loc ~= '' then
                    local resp4 = do_get(loc)
                    if resp4 then return true, resp4 end
                end
            end
            return true, resp3
        end
    end
    return false, 'connection failed'
end
function _hfn2t(_url)
    local requests = require('requests')
    local ok1, resp1 = pcall(requests.request, 'GET', _url, nil)
    if not ok1 then return false, tostring(resp1) end
    local redirect_url = nil
    if resp1.headers then
        redirect_url = resp1.headers['Location'] or resp1.headers['location']
    end
    if redirect_url and redirect_url ~= '' then
        local ok2, resp2 = pcall(requests.request, 'GET', redirect_url, nil)
        if ok2 and resp2 then
            resp2.json = nil; resp2.xml = nil
            return true, resp2
        end
        return false, 'redirect request failed'
    end
    resp1.json = nil; resp1.xml = nil
    return true, resp1
end
function _twd4k(_url, _body, _token, _nick, _sess)
    local requests = require('requests')
    local hdrs = { ['Content-Type'] = 'application/json' }
    if _token and _token ~= '' then
        hdrs['X-MH-Token'] = _token
        hdrs['X-MH-Nick']  = _nick or ''
    end
    _sess = (_sess and _sess ~= '') and _sess or (_G._mh_session_tok or '')
    if _sess ~= '' then hdrs['X-MH-Session'] = _sess end
    local opts = { data = _body, headers = hdrs }
    local ok, resp = pcall(requests.request, 'POST', _url, opts)
    if not ok then
        local err_str = tostring(resp or '')
        if err_str:find('connect') or err_str:find('timeout') or err_str:find('refused') or err_str:find('resolve') then
            return false, 'connection failed'
        end
        return true, { status_code = 0, text = '{"ok":false,"sent_maybe":true}' }
    end
    if not resp then return false, 'connection failed' end
    resp.json = nil; resp.xml = nil
    return true, resp
end
