_mh_fn.sync_post_auth = function(url, body_json)
    local ok_ssl, https = pcall(require, 'ssl.https')
    local ok_ltn, ltn12 = pcall(require, 'ltn12')
    if not ok_ssl or not ok_ltn then
        local ok_r, requests = pcall(require, 'requests')
        if not ok_r then return nil, 'no http lib' end
        local hdrs = { ['Content-Type'] = 'application/json' }
        local _sess = _G._mh_session_tok or ''
        if _sess ~= '' then hdrs['X-MH-Session'] = _sess end
        local _tok = (settings.premium and settings.premium.tok) or ''
        local _nck = (settings.premium and settings.premium.nick) or ''
        if _tok ~= '' then hdrs['X-MH-Token'] = _tok; hdrs['X-MH-Nick'] = _nck end
        local ok, resp = pcall(requests.request, 'POST', url, { data = body_json, headers = hdrs })
        if not ok or not resp then return nil, tostring(resp) end
        return resp.status_code, (resp.text or ''):sub(1, 100)
    end
    local _sess = _G._mh_session_tok or ''
    local _tok  = (settings.premium and settings.premium.tok) or ''
    local _nck  = (settings.premium and settings.premium.nick) or ''
    local resp_body = {}
    local req_hdrs = {
        ['Content-Type']   = 'application/json',
        ['Content-Length'] = tostring(#body_json),
    }
    if _sess ~= '' then req_hdrs['X-MH-Session'] = _sess end
    if _tok  ~= '' then req_hdrs['X-MH-Token']   = _tok; req_hdrs['X-MH-Nick'] = _nck end
    local ok, code, resp_h = pcall(https.request, {
        url     = url,
        method  = 'POST',
        headers = req_hdrs,
        source  = ltn12.source.string(body_json),
        sink    = ltn12.sink.table(resp_body),
    })
    if not ok then return nil, tostring(code) end
    return tonumber(code), table.concat(resp_body):sub(1, 100)
end
