local function _fwm2c(url, _f_tok, _f_nick, callback)
    if _G._fwm2c_active >= 5 then
        lua_thread.create(function()
            local _w = 0
            while _G._fwm2c_active >= 5 and _w < 80 do wait(250); _w = _w + 1 end
            _fwm2c(url, _f_tok, _f_nick, callback)
        end)
        return
    end
    _G._fwm2c_active = _G._fwm2c_active + 1
    local _f_sess = _G._mh_session_tok or ''
    if _f_tok == '' then _f_tok = _f_sess end
    local thread = effil.thread(_kby5v)('GET', url, _f_tok or '', _f_nick or '', _f_sess)
    lua_thread.create(function()
        local _deadline = os.clock() + 60
        while true do
            wait(30)
            if os.clock() > _deadline then
                _G._fwm2c_active = math.max(0, _G._fwm2c_active - 1)
                pcall(function() thread:cancel() end)
                return callback(nil, nil, 'timeout')
            end
            local status, err = thread:status()
            if not status or err then
                _G._fwm2c_active = math.max(0, _G._fwm2c_active - 1)
                return callback(nil, nil, tostring(err or 'thread error'))
            end
            if status == 'completed' or status == 'canceled' then
                _G._fwm2c_active = math.max(0, _G._fwm2c_active - 1)
                local ok2, resp = thread:get()
                if not ok2 then
                    return callback(nil, nil, tostring(resp))
                end
                local text = resp and resp.text or nil
                if text and #text > 0 then
                    local ok3, dec = pcall(require('encoding').UTF8.decode, require('encoding').UTF8, text)
                    if ok3 then text = dec end
                end
                return callback(resp and resp.status_code, text, nil)
            end
        end
    end)
end
local function _jmx9s(url, body_json, callback)
    local _tok  = (settings.premium and settings.premium.tok) or ''
    if _tok == '' then _tok = _G._mh_session_tok or '' end
    local _nck  = (settings.premium and settings.premium.nick) or ''
    local _sess = _G._mh_session_tok or ''
    local thread = effil.thread(_twd4k)(url, body_json, _tok, _nck, _sess)
    lua_thread.create(function()
        local _deadline = os.clock() + 30
        while true do
            wait(30)
            if os.clock() > _deadline then
                pcall(function() thread:cancel() end)
                return callback(0, nil, 'timeout')
            end
            local status, err = thread:status()
            if not status or err then
                return callback(nil, nil, tostring(err or 'thread error'))
            end
            if status == 'completed' or status == 'canceled' then
                local ok2, resp = thread:get()
                if not ok2 then
                    return callback(0, nil, tostring(resp or 'effil serialize error'))
                end
                return callback(resp and resp.status_code, resp and resp.text or nil, nil)
            end
        end
    end)
end
