        elseif _df == 1 then _res={}; for _,_a in ipairs(_arb_raw) do if _a.dir=='buy'       then table.insert(_res,_a) end end
        elseif _df == 2 then _res={}; for _,_a in ipairs(_arb_raw) do if _a.dir=='sell'      then table.insert(_res,_a) end end
        elseif _df == 3 then _res={}; for _,_a in ipairs(_arb_raw) do if _a.dir=='shop2shop' then table.insert(_res,_a) end end
        end
        _G.arb_raw_list  = _arb_raw
