function mh_dlg_cp(s)
    if type(s) ~= 'string' or s == '' then return s or '' end
    if not s:find('[\128-\255]') then return s end
    local rest = s:gsub('[\194-\223][\128-\191]', '')
                  :gsub('[\224-\239][\128-\191][\128-\191]', '')
                  :gsub('[\240-\244][\128-\191][\128-\191][\128-\191]', '')
    if rest:find('[\128-\255]') then return s end                                     
    return (s:gsub('[\194-\244][\128-\191]*', function(c)
        local n = #c
        if n == 2 then
            local a, b = c:byte(1, 2)
            if a == 208 or a == 209 then
                local cp = (a - 192) * 64 + (b - 128)
                if cp >= 1040 and cp <= 1103 then return string.char(cp - 1040 + 192) end
                if cp == 1025 then return '\168' end
                if cp == 1105 then return '\184' end
            elseif c == '\194\160' then return ' '
            elseif c == '\194\171' then return '\171'
            elseif c == '\194\187' then return '\187' end
        elseif c == '\226\132\150' then return '\185'
        elseif c == '\226\128\147' or c == '\226\128\148' then return '-' end
        return '?'
    end))
end
