function _pkt_fmt_json(s)
    if not s or s == '' then return '(empty)' end
    local ok, t = pcall(decodeJson, s)
    if not ok or type(t) ~= 'table' then
        return s:sub(1, 500)
    end
    local function _fmt(v, depth)
        local d = string.rep('  ', depth)
        if type(v) == 'table' then
            local is_arr = (#v > 0)
            if is_arr then
                local parts = {}
                for _, iv in ipairs(v) do
                    table.insert(parts, d .. '  ' .. _fmt(iv, depth+1))
                end
                if #parts > 8 then
                    parts[9] = d .. '  ...(' .. #v .. ' total)'
                    while #parts > 9 do table.remove(parts) end
                end
                return '[\n' .. table.concat(parts, ',\n') .. '\n' .. d .. ']'
            else
                local parts = {}
                for k, iv in pairs(v) do
                    table.insert(parts, d .. '  "' .. tostring(k) .. '": ' .. _fmt(iv, depth+1))
                end
                table.sort(parts)
                return '{\n' .. table.concat(parts, ',\n') .. '\n' .. d .. '}'
            end
        elseif type(v) == 'string' then
            return '"' .. v:sub(1,120) .. '"'
        else
            return tostring(v)
        end
    end
    return _fmt(t, 0)
end
