function mh_tg_send(tcp, silent)
    local c = settings and settings.telegram
    if not c or not c.enabled then return end
    local tok = c.bot_token or ''
    local cid = c.chat_id   or ''
    if tok == '' or cid == '' then return end
    local msg = tcp
    local ok_u, utf_msg = pcall(function()
        return require('encoding').UTF8:encode(require('encoding').CP1251:decode(msg))
    end)
    if ok_u and utf_msg then msg = utf_msg end
    local encoded = _mh_tg_url_encode(msg)
    local _use_proxy = settings.telegram and settings.telegram.use_proxy
    local _tg_base = _use_proxy
        and 'https://va-ta.com/tg_proxy/%s/sendMessage?chat_id=%s&text=%s'
        or  'https://api.telegram.org/bot%s/sendMessage?chat_id=%s&text=%s'
    local url = _tg_base:format(tok, cid, encoded)
    if mh_debug_enabled then
        local _safe_url = url:gsub(tok, '***TOKEN***')
        mh_notify('[MH TG DBG] proxy='..tostring(_use_proxy)..' url='.._safe_url:sub(1,180), 0x8888FF)
    end
    local ok_ch = pcall(function() _mh_tg_ch:push(url, 0) end)
    if not ok_ch then
        lua_thread.create(function()
            local ok_r, req = pcall(require, 'requests')
            if ok_r and req then pcall(req.request, 'GET', url, nil) end
        end)
    end
    if mh_debug_enabled and not silent then
        _jmx9s(url, '', function(code, text, err)
            local _t = tostring(text or ''):sub(1, 150)
            if code == 200 then
                mh_notify('[MH TG DBG] код=200 OK', 0x88FF88)
            else
                mh_notify('[MH TG DBG] код='..tostring(code)..' err='..tostring(err or '-')..' body='.._t, 0xFF6666)
            end
        end)
    end
    if not silent then
        mh_notify('[MH TG] отправлено...', 0xFFFFFF)
    end
end
