        end)
    end
end
_G._mh_tg_day_sell = 0
_G._mh_tg_day_buy  = 0
_G._mh_tg_day_date = ''
mh_tg_on_trade = function(le)
    if not settings.telegram or not settings.telegram.notify_trades then return end
    local _op = ((le.op or ''):upper())
    local is_my_sell = (le.own == true and _op == 'SELL') or
                       (le.own == false and _op == 'BUY') or
                       (le.own == nil and _op == 'SELL')
    local total   = (le.price or 0) * (le.qty or 1)
    local partner = le.partner or ''
    local today   = os.date('%d.%m')
    if _G._mh_tg_day_date ~= today then
        _G._mh_tg_day_sell = 0
        _G._mh_tg_day_buy  = 0
        _G._mh_tg_day_date = today
    end
    if is_my_sell then
        _G._mh_tg_day_sell = (_G._mh_tg_day_sell or 0) + total
    else
        _G._mh_tg_day_buy  = (_G._mh_tg_day_buy  or 0) + total
    end
    local sell_sum = _G._mh_tg_day_sell
    local buy_sum  = _G._mh_tg_day_buy
    local op_icon, op_name, who_name
    if is_my_sell then
        op_icon  = '[+]'
        op_name  = 'Продажа'
        who_name = 'Купил'
    else
        op_icon  = '[-]'
        op_name  = 'Покупка'
        who_name = 'Продал'
    end
    local own_lbl
    if le.own == true then
        own_lbl = ' (ваша лавка)'
    else
        own_lbl = ' (чужая лавка)'
    end
    local item_cp = le.item or '?'
    local part_cp = partner ~= '' and partner or 'Неизв.'
    local _tr_col = is_my_sell and 0x55DD55 or 0xFF8844
    mh_notify('[MH] ' .. op_icon .. ' ' .. op_name .. ' {ffffff}' .. tostring(item_cp)
        .. ' {aaaaaa}x' .. tostring(le.qty or 1)
        .. ' {ffffff}$' .. _kcr3y(total)
        .. ' {aaaaaa}(' .. who_name .. ': ' .. tostring(part_cp) .. ')', _tr_col)
    local msg = op_icon .. ' ' .. op_name .. own_lbl .. '\n'
        .. '--------------------\n'
        .. 'Предмет: ' .. item_cp .. '\n'
        .. 'Сумма: $' .. _kcr3y(total)
        .. '  x' .. tostring(le.qty or 1)
        .. ' шт. ($' .. _kcr3y(le.price or 0) .. '/шт.)' .. '\n'
        .. who_name .. ': ' .. part_cp .. '\n'
        .. '--------------------\n'
        .. 'Итоги за ' .. today .. ':\n'
        .. '  [+] Продажи: $' .. _kcr3y(sell_sum) .. '\n'
        .. '  [-] Покупки: $' .. _kcr3y(buy_sum) .. '\n'
        .. '--------------------\n'
        .. os.date('%H:%M  %d.%m.%Y')
    mh_tg_send(msg, true)
end
_G._mh_payday_buf      = nil                                                                  
_G._mh_payday_collecting = false
function _mh_payday_flush()
    local p = _G._mh_payday_buf
    _G._mh_payday_buf = nil
    _G._mh_payday_collecting = false
    if not p then return end
    if not settings.telegram or not settings.telegram.notify_payday then return end
    local now_s = os.date('%H:%M  %d.%m.%Y')
    local function money(v) return '$' .. _kcr3y(v or 0) end
    local function gain(v)
        v = v or 0
        if v == 0 then return '' end
        return ' ({aaffaa}+' .. _kcr3y(v) .. '{ffffff})'
    end
    local function gain_utf(v)
        v = v or 0
        if v == 0 then return '' end
        return ' (+' .. _kcr3y(v) .. ')'
    end
    local _az_part = ''
    if p.donate_total then
        local function gain_az(v)
            v = v or 0
            if v == 0 then return '' end
            return ' ({aaffaa}+' .. _kcr3y(v) .. '{ffffff})'
        end
        _az_part = '  {aaaaaa}AZ: {ffffff}' .. _kcr3y(p.donate_total) .. gain_az(p.donate_gain)
    end
    mh_notify('[MH] {ffcc00}PayDay {ffffff}Банк: ' .. money(p.bank_total) .. gain(p.bank_gain)
        .. '  {aaaaaa}Депозит: {ffffff}' .. money(p.dep_total) .. gain(p.dep_gain) .. _az_part, 0xFFCC44)
    local msg = '[PAYDAY] Зарплата\n'
        .. '--------------------\n'
        .. 'Банк: ' .. money(p.bank_total) .. gain_utf(p.bank_gain) .. '\n'
        .. 'Депозит: ' .. money(p.dep_total) .. gain_utf(p.dep_gain)
    if p.family_fee and p.family_fee > 0 then
        msg = msg .. '\n  -> в бюджет семьи: ' .. money(p.family_fee)
    end
    msg = msg .. '\n'
        .. 'Зарплата: ' .. money(p.salary) .. '\n'
    if p.bonus_sum and p.bonus_sum > 0 then
        msg = msg .. 'Доп. доход (' .. (p.bonus_name or 'бонус') .. '): ' .. money(p.bonus_sum) .. '\n'
    end
    msg = msg .. '--------------------\n'
    if p.level then
        msg = msg .. 'Уровень: ' .. p.level
        if p.resp_cur and p.resp_max then
            msg = msg .. '  (' .. p.resp_cur .. '/' .. p.resp_max .. ' респектов)'
        end
        if p.exp_gain and p.exp_gain > 0 then
            msg = msg .. gain_utf(p.exp_gain) .. ' EXP'
        end
        msg = msg .. '\n'
    end
    if p.donate_total then
        msg = msg .. 'Донат-счёт: ' .. p.donate_total .. ' AZ' .. gain_utf(p.donate_gain) .. '\n'
    end
    local total_income = (p.bank_gain or 0) + (p.dep_gain or 0) + (p.bonus_sum or 0)
    if total_income > 0 then
        msg = msg .. '--------------------\n'
        msg = msg .. 'Итого за PayDay: ' .. money(total_income) .. '\n'
    end
    msg = msg .. '--------------------\n' .. now_s
    mh_tg_send(msg, true)
end
function _mh_payday_on_line(clean)
    if clean:find('БАНКОВСКИЙ ЧЕК') then
        _G._mh_payday_buf = {}
        _G._mh_payday_collecting = true
        return true
    end
    if not _G._mh_payday_collecting then return false end
    local p = _G._mh_payday_buf
    local bt, bg = clean:match('[Тт]екущая сумма в банке:%s*%$?([%d%s,%.]+)%s*%(%+%$?([%d%s,%.]+)%)')
    if bt then
        p.bank_total = tonumber((bt:gsub('[%s,%.]', '')))
        p.bank_gain  = tonumber((bg:gsub('[%s,%.]', '')))
        return true
    end
    local lvl, rc, rm = clean:match('(%d+)%-й уровень и (%d+)/(%d+) респект')
    if lvl then
        p.level = tonumber(lvl); p.resp_cur = tonumber(rc); p.resp_max = tonumber(rm)
        local eg = clean:match('%(%+(%d+)%s*EXP%)')
        if eg then p.exp_gain = tonumber(eg) end
        return true
    end
    local dt, dg = clean:match('[Тт]екущая сумма на депозите:%s*%$?([%d%s,%.]+)%s*%(%+%$?([%d%s,%.]+)%)')
    if dt then
        p.dep_total = tonumber((dt:gsub('[%s,%.]', '')))
        p.dep_gain  = tonumber((dg:gsub('[%s,%.]', '')))
        local ff = clean:match('бюджет семьи:%s*%$?([%d%s,%.]+)')
        if ff then p.family_fee = tonumber((ff:gsub('[%s,%.]', ''))) end
        return true
    end
    local sal = clean:match('[Оо]бщая заработная плата:%s*%$?([%d%s,%.]+)')
    if sal then
        p.salary = tonumber((sal:gsub('[%s,%.]', '')))
        return true
    end
    local don, dgn = clean:match('[Бб]аланс на донат%-сче[тё]т:%s*([%d%s,%.]+)%s*AZ%s*%(%+([%d%s,%.]+)%s*AZ%)')
    if don then
        p.donate_total = tonumber((don:gsub('[%s,%.]', '')))
        p.donate_gain  = tonumber((dgn:gsub('[%s,%.]', '')))
        return true
    end
    if not don then
        local don2 = clean:match('[Бб]аланс на донат%-сче[тё]т:%s*([%d%s,%.]+)%s*AZ')
        if don2 then p.donate_total = tonumber((don2:gsub('[%s,%.]', ''))); return true end
    end
    local bsum, bname = clean:match('[Вв]ы получили%s*%+%$?([%d%s,%.]+)%s*за%s*"?([^"\n]+)"?')
    if bsum then
        p.bonus_sum  = (p.bonus_sum or 0) + (tonumber((bsum:gsub('[%s,%.]', ''))) or 0)
        p.bonus_name = bname:match('^%s*(.-)%s*$')
        return true
    end
    return false
end
function _to_utf8(s)
    if not s then return '' end
    local ok, r = pcall(function() return require('encoding').UTF8:encode(tostring(s)) end)
    return ok and r or tostring(s)
end
function mh_tg_on_arb(nm,margin,shop,mkt,owner,owner2,uid,uid2)
    if not settings.telegram or not settings.telegram.notify_arb then return end
    if (margin or 0)<(settings.telegram.arb_threshold or 0) then return end
    local pct = (shop and shop > 0) and math.floor(((margin or 0)/shop)*100) or 0
    local _uid_s  = uid  and (' #'..tostring(uid))  or ''
    local _uid2_s = uid2 and (' #'..tostring(uid2)) or ''
    local function _s(v) return _to_utf8(v or '?') end
    local _arb_label  = _to_utf8('[>] Арбитраж')
    local _sep        = '--------------------'
    local _pre_nm     = _to_utf8('Предмет: ')
    local _pre_profit = _to_utf8('Прибыль: $')
    local _pre_sell   = _to_utf8('Продаёт: $')
    local _pre_buy    = _to_utf8('Скупает: $')
    local msg_utf8 = _arb_label .. '\n'
        .. _sep .. '\n'
        .. _pre_nm     .. _s(nm) .. '\n'
        .. _pre_profit .. _kcr3y(margin or 0) .. ' (' .. pct .. '%)\n'
        .. _pre_sell   .. _kcr3y(shop or 0) .. (owner and ('  ' .. _s(owner) .. _uid_s) or '') .. '\n'
        .. _pre_buy    .. _kcr3y(mkt or 0) .. (owner2 and ('  ' .. _s(owner2) .. _uid2_s) or '') .. '\n'
        .. _sep .. '\n'
        .. os.date('%H:%M  %d.%m.%Y')
    local c = settings and settings.telegram
    if not c or not c.enabled then return end
    local tok = c.bot_token or ''; local cid = c.chat_id or ''
    if tok == '' or cid == '' then return end
    local encoded = _mh_tg_url_encode(msg_utf8)
    local _use_proxy = c.use_proxy
    local _tg_base = _use_proxy
        and 'https://va-ta.com/tg_proxy/%s/sendMessage?chat_id=%s&text=%s'
        or  'https://api.telegram.org/bot%s/sendMessage?chat_id=%s&text=%s'
    local url = _tg_base:format(tok, cid, encoded)
    local ok_ch = pcall(function() _mh_tg_ch:push(url, 0) end)
    if not ok_ch then
        lua_thread.create(function()
            local ok_r, req = pcall(require, 'requests')
            if ok_r and req then pcall(req.request, 'GET', url, nil) end
        end)
    end
end
