                if ok and parsed and parsed.ok and parsed.nonce then
                    ch_body = parsed
                end
            end
        end)
        local wait_t = 0
        while ch_body == nil and wait_t < 5000 do
            wait(100)
            wait_t = wait_t + 100
        end
        if not ch_body then return nil end
        local f = io.open(_mh_script_path(), 'rb')
        if not f then return nil end
        local script_data = f:read('*a')
        f:close()
        local hashes = {}
        for _, seg in ipairs(ch_body.segments or {}) do
            local pos = seg.pos or 0
            local size = seg.size or 256
            local idx = seg.index or 0
            local chunk = script_data:sub(pos + 1, pos + size)
            local h = 5381
            for i = 1, #chunk do
                h = ((h * 33) + chunk:byte(i)) % 0x100000000
            end
            local hash_str = string.format('%08x', h)
            table.insert(hashes, {index = idx, hash = hash_str})
        end
        local requests_ok, requests = pcall(require, 'requests')
        if not requests_ok then return nil end
        local verify_body = encodeJson({
            nick = _nick,
            nonce = ch_body.nonce,
            hashes = hashes
        })
        local ok, resp = pcall(requests.request, 'POST', _vbr7n .. '/verify', {
            data = verify_body,
            headers = {['Content-Type'] = 'application/json'}
        })
        if ok and resp and resp.status_code == 200 then
            local ok2, parsed = pcall(decodeJson, resp.text or resp.body or '')
            if ok2 and parsed and parsed.valid and parsed.session_token then
                if parsed.outdated then
                    _G._mh_upd_latest = parsed.latest or _G._mh_upd_latest
                    return parsed.session_token, true, false
                end
                return parsed.session_token, false, false
            end
            if ok2 and parsed and parsed.valid == false then
                return nil, false, true
            end
        end
        return nil, false, false
    end
