    local function _finish(nick_result)
        if done then return end
        done = true
        if sampev then pcall(function() sampev.onShowDialog = prev_hook end) end
        if on_done then pcall(on_done, nick_result) end
    end
    if sampev then
        sampev.onShowDialog = function(id, style, title, btn1, btn2, text)
            if not done then
                local tl = tostring(title or ''):lower()
