                    or tostring(title or ''):find('\xf1\xf2\xe0\xf2\xe8\xf1\xf2\xe8\xea\xe0')
                if _is_stats_dialog then
                    local raw = tostring(text or '')
                    local nm = raw:match('[%s|]?[Ии]мя:%s*{?%x*}?%s*([A-Za-z0-9_]+)')
                    if nm and not nm:find('^Player_%x+$') then
                        found_nick = nm
                        if prev_hook then pcall(prev_hook, id, style, title, btn1, btn2, text) end
                        _finish(found_nick)
                        return false
                    elseif mh_debug_enabled then
                        mh_notify('[MH DEBUG] /stats recheck: нет совпадения ника, текст: ' .. raw:sub(1, 200), 0xFFAA00)
                    end
                end
            end
            if prev_hook then return prev_hook(id, style, title, btn1, btn2, text) end
        end
    end
    pcall(sampSendChat, '/stats')
    lua_thread.create(function()
        local deadline = os.clock() + (timeout_sec or 8)
        while os.clock() < deadline and not done do wait(200) end
        _finish(nil)
    end)
end
