function _mh_transliterate(s)
    s = tostring(s or '')
    local out = {}
    for i = 1, #s do
        local ch = s:sub(i, i)
        out[#out+1] = _mh_translit_map[ch] or ch
    end
    return table.concat(out)
end
function _mh_safe_filename(s)
    s = _mh_transliterate(tostring(s or ''))
    s = s:gsub('[^%w%-_%.]', '_')
    s = s:gsub('%s+', '_')
    s = s:gsub('_+', '_')
    s = s:gsub('^_+', ''):gsub('_+$', '')
    if s == '' then s = 'preset' end
    if #s > 60 then s = s:sub(1, 60) end
    return s
end
function _mh_preset_dir()
    local dir = getWorkingDirectory():gsub('\\', '/'):gsub('/$', '') .. '/MarketHelper/Preset'
    _mh_ensure_dir(getWorkingDirectory():gsub('\\', '/'):gsub('/$', '') .. '/MarketHelper')
    _mh_ensure_dir(dir)
    return dir
end
function _mh_export_preset(kind, preset_name, items)
    local prefix = (kind == 'buy') and 'buy' or 'sell'
    local date_part = os.date('%d_%m')
    local fname = prefix .. '_' .. date_part .. '_' .. _mh_safe_filename(preset_name) .. '.json'
    local dir = _mh_preset_dir()
    local path = dir .. '/' .. fname
    local payload = {
        kind    = prefix,
        name    = preset_name,
        created = os.date('%d.%m.%Y %H:%M'),
        items   = items,
    }
    local ok, j = pcall(encodeJson, payload)
    if not ok or not j then return false, 'encode_failed' end
    local f = io.open(path, 'w')
    if not f then return false, 'open_failed: '..tostring(path) end
    f:write(j)
    f:close()
    return true, path
end
function _mh_list_presets(kind)
    local prefix = (kind == 'buy') and 'buy_' or 'sell_'
    local dir = _mh_preset_dir()
    local out = {}
    local lfs_ok, lfs = pcall(require, 'lfs')
    if not lfs_ok or type(lfs) ~= 'table' or not lfs.dir then
        mh_notify('[MH] {ff6666}Импорт: модуль lfs недоступен ('..tostring(lfs)..'). Папка: '..tostring(dir), 0xFFFFFF)
        return out
    end
    local iter_ok, iter_err = pcall(function()
        local total_files, matched = 0, 0
        for fname in lfs.dir(dir) do
            if fname ~= '.' and fname ~= '..' then
                total_files = total_files + 1
                if fname:sub(1, #prefix) == prefix and fname:match('%.json$') then
                    matched = matched + 1
                    local path = dir .. '/' .. fname
                    local f = io.open(path, 'r')
                    if f then
                        local raw = f:read('*a')
                        f:close()
                        local ok, data = pcall(decodeJson, raw)
                        if ok and type(data) == 'table' then
                            table.insert(out, {
                                fname   = fname,
                                path    = path,
                                name    = data.name or fname,
                                created = data.created or '',
                                count   = (type(data.items) == 'table') and #data.items or 0,
                                items   = data.items,
                            })
                        else
                            mh_notify('[MH] {ff6666}Импорт: не смог разобрать JSON в файле '..fname, 0xFFFFFF)
                        end
                    else
                        mh_notify('[MH] {ff6666}Импорт: не смог открыть файл '..fname, 0xFFFFFF)
                    end
                end
            end
        end
        if #out == 0 then
            mh_notify('[MH] {ffaa55}Импорт: в папке '..tostring(dir)..' всего файлов: '..tostring(total_files)..', подходящих под "'..prefix..'*.json": '..tostring(matched), 0xFFFFFF)
        end
    end)
    if not iter_ok then
        mh_notify('[MH] {ff6666}Импорт: ошибка чтения папки '..tostring(dir)..' — '..tostring(iter_err), 0xFFFFFF)
    end
    table.sort(out, function(a, b) return a.fname > b.fname end)
    return out
end
function _mh_import_preset_file(path)
    local f = io.open(path, 'r')
    if not f then return false, 'open_failed' end
    local raw = f:read('*a')
    f:close()
    local ok, data = pcall(decodeJson, raw)
    if not ok or type(data) ~= 'table' or type(data.items) ~= 'table' then
        return false, 'decode_failed'
    end
    return true, (data.name or 'Импорт'), data.items
end
function _mh_url_encode(s)
    s = tostring(s or '')
    s = s:gsub('([^%w%-%.%_%~])', function(c) return string.format('%%%02X', string.byte(c)) end)
    return s
end
