        return
    end
    mh_notify('[MH Cloud] {aaddff}Публикую пресет "'.._pname..'" ('..#_items..' тов.)...', 0xFFFFFF)
    local function _do_push(is_retry)
        _jmx9s(_vbr7n .. '/cloud-presets/create', j, function(code, body, err)
            if code == 200 and body then
                local ok2, parsed = pcall(decodeJson, body)
                if ok2 and type(parsed) == 'table' and parsed.ok then
                    if parsed.updated then
                        mh_notify('[MH Cloud] {aaffaa}Пресет "'.._pname..'" обновлён в облаке.', 0xFFFFFF)
                    else
                        mh_notify('[MH Cloud] {aaffaa}Пресет "'.._pname..'" опубликован в облаке.', 0xFFFFFF)
                    end
                    _G._mh_cloud_loaded_once = false                                                
                    return
                end
            end
            if not is_retry then
                lua_thread.create(function() wait(1200); _do_push(true) end)
                return
            end
            mh_notify('[MH Cloud] {ff6666}Не удалось опубликовать пресет ('..tostring(err or code)..').', 0xFFFFFF)
        end)
    end
    _do_push(false)
end
function _mh_cloud_fetch_list(page)
    page = page or _G._mh_cloud_page or 1
    if _G._mh_cloud_loading then return end
    _G._mh_cloud_loading = true
    _G._mh_cloud_error = nil
    local _sid = _mh_cloud_current_server_id()
    local _url = _vbr7n .. '/cloud-presets/list'
        .. '?server_id=' .. tostring(_sid)
        .. '&budget_max=' .. tostring(_G._mh_cloud_budget_max or 0)
        .. '&sort=' .. tostring(_G._mh_cloud_sort or 'downloads')
        .. '&page=' .. tostring(page)
    local _srch = _G._mh_cloud_search or ''
    if _srch ~= '' then
        local _ok_enc, _enc = pcall(function() return require('encoding').UTF8:decode(_srch) end)
        _url = _url .. '&search=' .. _mh_url_encode(_ok_enc and _enc or _srch)
    end
    if _G._mh_cloud_mine_only then
        local _mnick = _mh_get_live_nick()
        if not _mh_is_fake_nick(_mnick) then
            _url = _url .. '&mine_nick=' .. _mh_url_encode(_to_utf8(_mnick))
        end
    end
    _fwm2c(_url, '', _mh_get_live_nick(), function(code, body, err)
        _G._mh_cloud_loading = false
        if err or code ~= 200 or not body then
            _G._mh_cloud_error = tostring(err or code or 'connection failed')
            return
        end
        local ok2, parsed = pcall(decodeJson, body)
        if not ok2 or type(parsed) ~= 'table' or not parsed.ok then
            _G._mh_cloud_error = 'bad_response'
            return
        end
        _G._mh_cloud_list  = parsed.presets or {}
        _G._mh_cloud_total = parsed.total or 0
        _G._mh_cloud_page  = page
    end)
end
