        if req_id ~= nil then
            local resp = {kind = 'cloud_vote_result', req_id = tonumber(req_id) or 0, id = cp.id}
            if _ok then
                resp.my_vote  = _G._mh_cloud_my_votes[cp.id]
                resp.likes    = cp.likes
                resp.dislikes = cp.dislikes
            else
                resp.error = tostring(err or code or 'bad_response')
            end
            local ok_j2, j2 = pcall(encodeJson, resp)
            if ok_j2 then
                local ok_b64, b64 = pcall(function() return require('basexx').to_base64(j2) end)
                if ok_b64 and b64 then
                    pcall(function()
                        if _mh_web_jar and _mh_buy.state.created and _mh_buy.state.loaded then
                            _mh_web_jar.executeJS(_mh_buy.bid, "window.mhReceiveState && window.mhReceiveState('" .. b64 .. "');")
                        end
                    end)
                end
            end
        end
    end)
end
function _mh_cloud_delete_preset(cp)
    if not cp or not cp.id then return end
    local _dnick = _mh_get_live_nick()
    if _mh_is_fake_nick(_dnick) then
        mh_notify('[MH Cloud] {ff6666}Не удалось определить ник для удаления.', 0xFFFFFF)
        return
    end
    local ok_j, j = pcall(encodeJson, {preset_id = cp.id, nick = _to_utf8(_dnick)})
    if not ok_j then return end
    _jmx9s(_vbr7n .. '/cloud-presets/delete', j, function(code, body, err)
        if code == 200 and body then
            local ok2, parsed = pcall(decodeJson, body)
            if ok2 and type(parsed) == 'table' and parsed.ok then
                mh_notify('[MH Cloud] {aaffaa}Пресет "'..tostring(cp.title or '?')..'" удалён из облака.', 0xFFFFFF)
                for i, it in ipairs(_G._mh_cloud_list or {}) do
                    if it.id == cp.id then table.remove(_G._mh_cloud_list, i); break end
                end
                _G._mh_cloud_total = math.max(0, (_G._mh_cloud_total or 1) - 1)
                return
            end
            if ok2 and parsed.error == 'not_owner' then
                mh_notify('[MH Cloud] {ff6666}Можно удалять только свои пресеты.', 0xFFFFFF)
                return
            end
        end
        mh_notify('[MH Cloud] {ff6666}Не удалось удалить пресет ('..tostring(err or code)..').', 0xFFFFFF)
    end)
end
function _mh_mkt_log_index_by_name()
    local _ver = _G._mh_mkt_log_ver or 0
    if _G._mh_mkt_log_idx and _G._mh_mkt_log_idx_ver == _ver then
        return _G._mh_mkt_log_idx
    end
    local idx = {}
    for i = 1, #fh_mkt_log do
        local le = fh_mkt_log[i]
        if le and le.item then
            local bucket = idx[le.item]
            if not bucket then bucket = {}; idx[le.item] = bucket end
            bucket[#bucket + 1] = le
        end
    end
    _G._mh_mkt_log_idx = idx
    _G._mh_mkt_log_idx_ver = _ver
    return idx
end
function _mh_other_shops_sell_index()
    if _G._mh_other_shops_idx_built then
        return _G._mh_other_shops_idx or {}
    end
    local idx = {}
    for _, _sh in pairs(fh_other_shops or {}) do
        if type(_sh) == 'table' then
            for _, _si in ipairs(_sh.sell_items or {}) do
                local _sn_lo = (_si.name or ''):lower()
                if _sn_lo ~= '' and (_si.price or 0) > 0 then
                    local bucket = idx[_sn_lo]
                    if not bucket then bucket = {}; idx[_sn_lo] = bucket end
                    bucket[#bucket + 1] = _si.price
                end
            end
        end
    end
    _G._mh_other_shops_idx = idx
    _G._mh_other_shops_idx_built = true
    return idx
end
function _mh_shop_idx_remove(shop)
    if not shop or type(shop) ~= 'table' then return end
    local idx = _mh_other_shops_sell_index()
    for _, _si in ipairs(shop.sell_items or {}) do
        local _sn_lo = (_si.name or ''):lower()
        local _pr = _si.price or 0
        if _sn_lo ~= '' and _pr > 0 then
            local bucket = idx[_sn_lo]
            if bucket then
                for i = #bucket, 1, -1 do
                    if bucket[i] == _pr then
                        table.remove(bucket, i)
                        break                                                                                                                                                                     
                    end
                end
                if #bucket == 0 then idx[_sn_lo] = nil end
            end
        end
    end
end
function _mh_shop_idx_add(shop)
    if not shop or type(shop) ~= 'table' then return end
    local idx = _mh_other_shops_sell_index()
    for _, _si in ipairs(shop.sell_items or {}) do
        local _sn_lo = (_si.name or ''):lower()
        local _pr = _si.price or 0
        if _sn_lo ~= '' and _pr > 0 then
            local bucket = idx[_sn_lo]
            if not bucket then bucket = {}; idx[_sn_lo] = bucket end
            bucket[#bucket + 1] = _pr
        end
    end
end
local function _mh_get_mkt_price(nm)
    if not nm or nm == '' then return nil end
    local _cur_ver    = _G._mh_db_ver          or 0
    local _shop_ver   = _G._mh_shop_ver         or 0
    local _deals_ver  = _G._mh_deals_cache_ver  or 0
    local _daily_ver  = _G._mh_daily_cache_ver  or 0
    local _avg_cache_ver = tostring(_cur_ver)..'|'..tostring(_shop_ver)..'|'..tostring(_deals_ver)..'|'..tostring(_daily_ver)
    if not _G._mkt_price_gcache or _G._mkt_price_gcache_ver ~= _avg_cache_ver then
        _G._mkt_price_gcache      = {}
        _G._mkt_price_gcache_ver  = _avg_cache_ver
        _G._mkt_today_gcache      = {}
        _G._mkt_today_gcache_ver  = _shop_ver
    end
    if not _G._mkt_today_gcache or _G._mkt_today_gcache_ver ~= _shop_ver then
        _G._mkt_today_gcache     = {}
