function _mh_dialog_has_qty_price(text)
    text = tostring(text or ''):lower()
    if text == '' then return false end
    local has_qty_word = text:find('колич', 1, true) ~= nil
        or text:find('кол-во', 1, true) ~= nil
        or text:find('кол во', 1, true) ~= nil
        or text:find('quantity', 1, true) ~= nil
    local has_price_word = text:find('цен', 1, true) ~= nil
        or text:find('price', 1, true) ~= nil
    if has_qty_word and has_price_word then return true end
    if text:find('%d+%s*,%s*%d+') then return true end
    return false
end
