local function safe_call(fn, ...)
    if type(fn) ~= 'function' then return nil end
    local ok, a, b = pcall(fn, ...)
    if ok then return a, b end
    return nil
end
local function pack_color(r, g, b, a)
    a = a == nil and 1 or a
    if imgui.ColorConvertFloat4ToU32 then
        local ok, packed = pcall(imgui.ColorConvertFloat4ToU32, imgui.ImVec4(r, g, b, a))
        if ok and packed then return packed end
    end
    local function to_byte(v) return math.floor((v < 0 and 0 or (v > 1 and 1 or v)) * 255 + 0.5) end
    local rr, gg, bb, aa = to_byte(r), to_byte(g), to_byte(b), to_byte(a)
    return (aa * 0x1000000) + (bb * 0x10000) + (gg * 0x100) + rr
end
