local STATE = {
    APPEARING    = 'appearing',
    SHOWING      = 'showing',
    DISAPPEARING = 'disappearing',
    DEAD         = 'dead',
}
local function clamp01(v)
    if v < 0 then return 0 elseif v > 1 then return 1 else return v end
end
local function lerp(a, b, t)
    return a + (b - a) * t
end
local function lerp_dt(current, target, speed, dt)
    local t = 1 - math.exp(-speed * math.max(dt, 0))
    return lerp(current, target, clamp01(t))
end
local Notification = {}
Notification.__index = Notification
local _id_seq = 0
local function next_id()
    _id_seq = _id_seq + 1
    return _id_seq
end
function Notification.new(text, ntype, duration, cfg)
    local self = setmetatable({}, Notification)
    self.id       = next_id()
    self.text     = tostring(text or '')
    self.ntype    = NOTIFICATION_TYPES[ntype] and ntype or 'info'
    self.duration = tonumber(duration) or cfg.duration
    self.cfg      = cfg                                                                    
    self.state    = STATE.APPEARING
    self.timer    = 0                                                                         
    self.alpha    = 0                                                    
    self.y        = 0                                                       
    self.target_y = 0                                                           
    self.offset   = 0                                                                                  
    self.height   = nil                                                                    
    self.spawned  = false                                                                      
    return self
end
function Notification:calc_height()
    if self.height then return self.height end
    local cfg = self.cfg
    local fscale = cfg.font_scale or 1.0
    local wrap_w = (cfg.width - cfg.padding_x * 2 - cfg.accent_width - 8) / fscale
    local text_h = 16
    local sz = safe_call(imgui.CalcTextSize, self.text, false, wrap_w)
    if sz then text_h = sz.y * fscale end
    local def = NOTIFICATION_TYPES[self.ntype]
    local title_h = 18 * fscale
    if def then
        local title_str = string.format('%s  %s', def.icon, def.label)
        local tsz = safe_call(imgui.CalcTextSize, title_str, false, wrap_w)
        if tsz then title_h = tsz.y * fscale end
    end
    local line_h = 16 * fscale
    local approx_lines = math.max(1, math.ceil((text_h + title_h) / line_h))
    local safety_margin = 8 + approx_lines * 3
    local breathing_room = 6
    self.height = cfg.padding_y * 2 + title_h + text_h + 12 + safety_margin + breathing_room
    return self.height
end
function Notification:dismiss()
    if self.state ~= STATE.DISAPPEARING and self.state ~= STATE.DEAD then
        self.state = STATE.DISAPPEARING
        self.timer = 0
    end
end
function Notification:is_dead()
    return self.state == STATE.DEAD
end
function Notification:update(dt, target_y, off_screen_y)
    self.target_y = target_y
    local cfg = self.cfg
    if self.state == STATE.APPEARING then
        if not self.spawned then
            self.y = off_screen_y
            self.spawned = true
        end
        self.y     = lerp_dt(self.y, self.target_y, cfg.anim_speed, dt)
        self.alpha = lerp_dt(self.alpha, 1, cfg.anim_speed, dt)
        if math.abs(self.y - self.target_y) < 0.75 and self.alpha > 0.97 then
            self.state = STATE.SHOWING
            self.timer = 0
        end
    elseif self.state == STATE.SHOWING then
        self.y     = lerp_dt(self.y, self.target_y, cfg.anim_speed, dt)
        self.alpha = lerp_dt(self.alpha, 1, cfg.anim_speed, dt)
        self.timer = self.timer + dt
        if self.timer >= self.duration then
            self:dismiss()
        end
    elseif self.state == STATE.DISAPPEARING then
        self.y     = lerp_dt(self.y, off_screen_y, cfg.anim_speed, dt)
        self.alpha = lerp_dt(self.alpha, 0, cfg.anim_speed, dt)
        self.timer = self.timer + dt
        if self.alpha < 0.02 or self.timer > 2.5 then
            self.state = STATE.DEAD
        end
    end
end
local NotificationManager = {}
NotificationManager.__index = NotificationManager
NotificationManager.config  = {}
for k, v in pairs(DEFAULT_CONFIG) do
    NotificationManager.config[k] = v
end
NotificationManager.active   = {}                                                                                   
NotificationManager.pending  = {}                                                   
NotificationManager.enabled  = true
NotificationManager._registered = false
function NotificationManager.configure(opts)
    if type(opts) ~= 'table' then return NotificationManager end
    for k, v in pairs(opts) do
        NotificationManager.config[k] = v
    end
    return NotificationManager
end
function NotificationManager.set_position(pos)
    NotificationManager.config.position = pos
    return NotificationManager
end
function NotificationManager.set_enabled(flag)
    NotificationManager.enabled = flag and true or false
    return NotificationManager
end
function NotificationManager.add(text, ntype, duration)
    if not text or text == '' then return nil end
    local notif = Notification.new(text, ntype, duration, NotificationManager.config)
    if #NotificationManager.active < NotificationManager.config.max_visible then
        table.insert(NotificationManager.active, notif)
    else
        table.insert(NotificationManager.pending, notif)
    end
    NotificationManager:_ensure_registered()
    return notif.id
end
function NotificationManager.info(text, duration)    return NotificationManager.add(text, 'info', duration) end
function NotificationManager.success(text, duration) return NotificationManager.add(text, 'success', duration) end
function NotificationManager.warning(text, duration) return NotificationManager.add(text, 'warning', duration) end
function NotificationManager.error(text, duration)   return NotificationManager.add(text, 'error', duration) end
function NotificationManager.dismiss(id)
    for _, n in ipairs(NotificationManager.active) do
        if n.id == id then n:dismiss(); return true end
    end
    for i, n in ipairs(NotificationManager.pending) do
        if n.id == id then table.remove(NotificationManager.pending, i); return true end
    end
    return false
end
function NotificationManager.clear()
    NotificationManager.active  = {}
    NotificationManager.pending = {}
end
function NotificationManager.count()
    return #NotificationManager.active + #NotificationManager.pending
end
function NotificationManager:_layout_params(sw, sh)
    local cfg = self.config
    local pos = cfg.position or 'bottom_right'
    local x
    if pos:find('right') then
        x = sw - cfg.margin_x - cfg.width
    elseif pos:find('left') then
        x = cfg.margin_x
    else            
        x = (sw - cfg.width) / 2
    end
    if x < 0 then x = 0 end
    if x + cfg.width > sw then x = sw - cfg.width end
    local _d = tonumber(settings.general and settings.general.custom_dpi) or 1
    local min_margin_y = 28 * _d
    local mgy = cfg.margin_y
    if mgy < min_margin_y then mgy = min_margin_y end
    local from_top = pos:find('^top')
    if from_top then
        return x, mgy, false                                        
    else
        return x, sh - mgy, true                                                               
    end
end
function NotificationManager:_update(dt)
    local cfg = self.config
    while #self.active < cfg.max_visible and #self.pending > 0 do
        table.insert(self.active, table.remove(self.pending, 1))
    end
    if #self.active == 0 then return end
    local io = imgui.GetIO()
    local sw, sh = io.DisplaySize.x, io.DisplaySize.y
    local anchor_x, anchor_y, grows_up = self:_layout_params(sw, sh)
    local off_screen_y
    if grows_up then
        off_screen_y = sh + 40
    else
        off_screen_y = -40
    end
    local acc = 0
    for i = #self.active, 1, -1 do
        local n = self.active[i]
        n:calc_height()
        n.offset = acc
        acc = acc + n.height + cfg.spacing
        local target_y
        if grows_up then
            target_y = anchor_y - n.height - n.offset
        else
            target_y = anchor_y + n.offset
        end
        n:update(dt, target_y, grows_up and (off_screen_y) or (off_screen_y - n.height))
    end
    self._anchor_x = anchor_x
    for i = #self.active, 1, -1 do
        if self.active[i]:is_dead() then
            table.remove(self.active, i)
        end
    end
end
local TOAST_WINDOW_FLAGS =
    imgui.WindowFlags.NoTitleBar +
    imgui.WindowFlags.NoResize +
    imgui.WindowFlags.NoMove +
    imgui.WindowFlags.NoScrollbar +
    imgui.WindowFlags.NoScrollWithMouse +
    imgui.WindowFlags.NoCollapse +
    imgui.WindowFlags.NoSavedSettings +
    imgui.WindowFlags.NoFocusOnAppearing +
    imgui.WindowFlags.NoNav +
    imgui.WindowFlags.NoBackground
function NotificationManager:_draw_toast(n)
    local cfg  = self.config
    local def  = NOTIFICATION_TYPES[n.ntype]
    local a    = clamp01(n.alpha)
    if a <= 0.01 then return end
    imgui.SetNextWindowPos(imgui.ImVec2(self._anchor_x, n.y), imgui.Cond.Always)
    imgui.SetNextWindowSize(imgui.ImVec2(cfg.width, n.height), imgui.Cond.Always)
    imgui.SetNextWindowBgAlpha(0)
    imgui.PushStyleColor(imgui.Col.Border, imgui.ImVec4(0, 0, 0, 0))
    local win_name = '##mh_toast_' .. tostring(n.id)
    local dummy_open = imgui.new.bool(true)
    if imgui.Begin(win_name, dummy_open, TOAST_WINDOW_FLAGS) then
        safe_call(imgui.SetWindowFontScale, cfg.font_scale or 1.0)
        local _hovered = safe_call(imgui.IsWindowHovered, imgui.HoveredFlags and imgui.HoveredFlags.AllowWhenBlockedByPopup or nil)
        if _hovered and safe_call(imgui.IsMouseClicked, 0) then
            n:dismiss()
        end
        local dl = imgui.GetWindowDrawList()
        local p_min = imgui.GetWindowPos()
        local p_max = imgui.ImVec2(p_min.x + cfg.width, p_min.y + n.height)
        local bg = cfg.bg_color
        dl:AddRectFilled(p_min, p_max, pack_color(bg[1], bg[2], bg[3], bg[4] * a), cfg.corner_radius)
        if cfg.border_enabled and (cfg.border_size or 0) > 0 then
            local bc = cfg.border_color or {1, 1, 1, 0.25}
            safe_call(dl.AddRect, dl, p_min, p_max,
                pack_color(bc[1], bc[2], bc[3], (bc[4] or 1) * a),
                cfg.corner_radius, 0, cfg.border_size)
        end
        local c = def.color
        local stripe_min = imgui.ImVec2(p_min.x + 3, p_min.y + 4)
        local stripe_max = imgui.ImVec2(p_min.x + 3 + cfg.accent_width, p_max.y - 4)
        dl:AddRectFilled(stripe_min, stripe_max, pack_color(c[1], c[2], c[3], a), cfg.accent_width / 2)
        imgui.SetCursorPosX(cfg.padding_x + cfg.accent_width + 6)
        imgui.SetCursorPosY(cfg.padding_y)
        imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(c[1], c[2], c[3], a))
        imgui.PushTextWrapPos(cfg.width - cfg.padding_x)
        imgui.TextWrapped(string.format('%s  %s', def.icon, def.label))
        imgui.PopTextWrapPos()
        imgui.PopStyleColor()
        imgui.SetCursorPosX(cfg.padding_x + cfg.accent_width + 6)
        imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(cfg.text_color[1], cfg.text_color[2], cfg.text_color[3], cfg.text_color[4] * a))
        imgui.PushTextWrapPos(cfg.width - cfg.padding_x)
        imgui.TextWrapped(n.text)
        imgui.PopTextWrapPos()
        imgui.PopStyleColor()
        local _measured_y = safe_call(imgui.GetCursorPosY)
        if _measured_y then
            local _real_h = _measured_y + cfg.padding_y
            if _real_h > n.height then
                n.height = _real_h
            elseif math.abs(_real_h - n.height) > 1 then
                n.height = _real_h
            end
        end
    end
    imgui.End()
    imgui.PopStyleColor()          
end
function NotificationManager:_render()
    if not self.enabled then return end
    self:_update(safe_call(function() return imgui.GetIO().DeltaTime end) or 0)
    if #self.active == 0 then return end
    for _, n in ipairs(self.active) do
        self:_draw_toast(n)
    end
end
function NotificationManager:_ensure_registered()
    if self._registered then return end
    self._registered = true
    imgui.OnFrame(
        function() return NotificationManager.enabled end,
        function() NotificationManager:_render() end
    )
end
NotificationManager:_ensure_registered()
local function _mh_toast_cfg_from_settings()
    local s = settings.toast or {}
    local d = tonumber(settings.general and settings.general.custom_dpi) or 1
    return {
        width         = (s.width or 320) * d,
        padding_x     = (s.padding_x or 14) * d,
        padding_y     = (s.padding_y or 10) * d,
        accent_width  = (s.accent_width or 4) * d,
        corner_radius = (s.corner_radius or 8) * d,
        spacing       = (s.spacing or 8) * d,
        margin_x      = (s.margin_x or 18) * d,
        margin_y      = (s.margin_y or 18) * d,
        duration      = s.duration,
        anim_speed    = s.anim_speed,
        max_visible   = s.max_visible,
        position      = (s.pos_v or 'bottom') .. '_' .. (s.pos_h or 'right'),
        bg_color      = {s.bg_r, s.bg_g, s.bg_b, s.bg_a},
        text_color    = {s.text_r, s.text_g, s.text_b, s.text_a},
        title_color   = {s.title_r, s.title_g, s.title_b, s.title_a},
        border_enabled= s.border_enabled,
        border_color  = {s.border_r, s.border_g, s.border_b, s.border_a},
        border_size   = s.border_size,
        font_scale    = s.font_scale,
    }
end
function _mh_apply_toast_settings()
    NotificationManager.configure(_mh_toast_cfg_from_settings())
    NotificationManager.set_enabled(settings.toast == nil or settings.toast.enabled ~= false)
end
_mh_apply_toast_settings()
function _mh_toast_test(kind)
    local samples = {
        info    = u8('Пример информационного уведомления MH.'),
        success = u8('Операция прошла успешно.'),
        warning = u8('Внимание: проверьте настройки.'),
        error   = u8('Пример ошибки — что-то пошло не так.'),
    }
    if kind == 'all' then
        for _, k in ipairs({'info', 'success', 'warning', 'error'}) do
            NotificationManager.add(samples[k], k, NotificationManager.config.duration)
        end
        return
    end
    if not samples[kind] then kind = 'info' end
    NotificationManager.add(samples[kind], kind, NotificationManager.config.duration)
end
    MH_Notify = NotificationManager
end
