function _mh_apply_theme(t)
    settings.interface.accent_r = t.accent[1]
    settings.interface.accent_g = t.accent[2]
    settings.interface.accent_b = t.accent[3]
    settings.interface.bg_r = t.bg[1]
    settings.interface.bg_g = t.bg[2]
    settings.interface.bg_b = t.bg[3]
    settings.interface.bg_brightness = t.bg[1]
    settings.interface.text_r = t.text[1]
    settings.interface.text_g = t.text[2]
    settings.interface.text_b = t.text[3]
    local ar,ag,ab = t.accent[1],t.accent[2],t.accent[3]
    local bm = t.border_mul or 0.70
    settings.interface.border_r = ar * bm
    settings.interface.border_g = ag * bm
    settings.interface.border_b = ab * bm
    settings.interface.rounding = t.rounding
    settings.interface.border_size = t.border_size
    if t.btn then
        settings.interface.btn_r = t.btn[1]
        settings.interface.btn_g = t.btn[2]
        settings.interface.btn_b = t.btn[3]
    else
        settings.interface.btn_r = nil
        settings.interface.btn_g = nil
        settings.interface.btn_b = nil
    end
    if t.sell_btn then
        settings.interface.sell_btn_r = t.sell_btn[1]
        settings.interface.sell_btn_g = t.sell_btn[2]
        settings.interface.sell_btn_b = t.sell_btn[3]
    end
    if t.buy_btn then
        settings.interface.buy_btn_r = t.buy_btn[1]
        settings.interface.buy_btn_g = t.buy_btn[2]
        settings.interface.buy_btn_b = t.buy_btn[3]
    end
    accent_color[0] = ar; accent_color[1] = ag; accent_color[2] = ab
    _G.sl_rounding = nil; _G.sl_border = nil
    _G.vid_text_col = nil; _G.vid_bg_col = nil; _G.vid_border_col = nil
    _G.vid_sell_col = nil; _G.vid_buy_col = nil
    _G.vid_sell_btn_col = nil; _G.vid_buy_btn_col = nil
    _G.vid_btn_col = nil; _G.sl_btn_bri = nil
    _wfn7p(); _fwb3h()
end
