fh_mkt_prices     = {}
fh_mkt_lavka      = {}
fh_mkt_log        = {}
fh_mkt_lavka_log  = {}
fh_trade_log      = {}
_XP_SELL_DIV = 1000000
_XP_BUY_DIV  = 2000000
_XP_LV_BASE  = 100
_G._xp_db      = {}
_G._xp_db_path = nil
function _xp_level(xp)
    return math.floor(math.sqrt((xp or 0) / _XP_LV_BASE))
end
function _xp_for_level(lv)
    return lv * lv * _XP_LV_BASE
end
function _xp_from_virtu(sv, bv, tsv, tbv)
    return math.floor((sv or 0) / _XP_SELL_DIV) + math.floor((bv or 0) / _XP_BUY_DIV)
         + math.floor((tsv or 0) / _XP_SELL_DIV) + math.floor((tbv or 0) / _XP_BUY_DIV)
end
function _xp_load()
    if not _G._xp_db_path then _G._xp_db_path = _zdb1r('player_xp.json') end
    local f = io.open(_G._xp_db_path, 'r')
    if f then
        local ok, d = pcall(decodeJson, f:read('*a')); f:close()
        if ok and type(d) == 'table' then _G._xp_db = d end
    end
end
function _xp_save()
    if not _G._xp_db_path then _G._xp_db_path = _zdb1r('player_xp.json') end
    local ok, j = pcall(encodeJson, _G._xp_db)
    if ok then local f = io.open(_G._xp_db_path, 'w'); if f then f:write(j); f:close() end end
end
function _xp_add(nick, amount, item_name, op)
    if not nick or nick == '' or amount <= 0 then return end
    nick = nick:lower(); op = (op or 'sell'):lower()
    if not _G._xp_db[nick] then
        _G._xp_db[nick]={xp=0,level=0,sales_count=0,last_sale='',display_nick=nick,
            sales_virtu=0,buy_virtu=0,buy_count=0,trade_sell_virtu=0,trade_buy_virtu=0}
    end
    local p = _G._xp_db[nick]
    p.last_sale = os.date('%d.%m %H:%M')
    if op == 'buy' then
        p.buy_virtu  = (p.buy_virtu  or 0) + amount
        p.buy_count  = (p.buy_count  or 0) + 1
    else
        p.sales_virtu = (p.sales_virtu or 0) + amount
        p.sales_count = (p.sales_count or 0) + 1
    end
    p.xp    = _xp_from_virtu(p.sales_virtu, p.buy_virtu, p.trade_sell_virtu, p.trade_buy_virtu)
    p.level = _xp_level(p.xp)
end
function _xp_add_trade(my_nick, get_money, give_money)
    if not my_nick or my_nick == '' then return end
    my_nick = my_nick:lower()
    if not _G._xp_db[my_nick] then
        _G._xp_db[my_nick]={xp=0,level=0,sales_count=0,last_sale='',display_nick=my_nick,
            sales_virtu=0,buy_virtu=0,buy_count=0,trade_sell_virtu=0,trade_buy_virtu=0}
    end
    local p = _G._xp_db[my_nick]
    if (get_money or 0) > 0 then
        p.trade_sell_virtu = (p.trade_sell_virtu or 0) + get_money
    end
    if (give_money or 0) > 0 then
        p.trade_buy_virtu  = (p.trade_buy_virtu  or 0) + give_money
    end
    p.xp    = _xp_from_virtu(p.sales_virtu, p.buy_virtu, p.trade_sell_virtu, p.trade_buy_virtu)
    p.level = _xp_level(p.xp)
    _G._xp_rank_cache = nil
end
function _xp_recalc_from_log()
    lua_thread.create(function()
        local nick = ''
        pcall(function()
            local _pid = select(2, sampGetPlayerIdByCharHandle(PLAYER_PED))
            nick = sampGetPlayerNickname(_pid) or ''
        end)
        if nick == '' then pcall(function() nick = sampGetCurrentPlayerName() or '' end) end
        if nick == '' then nick = (settings.premium and settings.premium.nick) or '' end
        local nl = nick:lower()
        if nl == '' then
            mh_notify('[MH] {ff8800}XP: ник не определён (войдите на сервер)', 0xFFFFFF); return
        end
        local tv_sell, cnt_sell, tv_buy, cnt_buy, last = 0, 0, 0, 0, ''
        local lfs_ok2, lfs2 = pcall(require, 'lfs')
        local _wd = getWorkingDirectory():gsub('\\', '/')
        local _seen_deals = {}
        if lfs_ok2 and lfs2 then
            local _deals_files = {}
            local _ok_ls, _err_ls = pcall(function()
                for _fn in lfs2.dir(_wd) do _deals_files[#_deals_files+1] = _fn end
            end)
            if _ok_ls then
                for _, _fn in ipairs(_deals_files) do
                    if _fn:match('^deals_srv%d+%.json$') then
                        local _fp = _wd .. '/' .. _fn
                        local _ff = io.open(_fp, 'r')
                        if _ff then
                            local _ok_d, _dd = pcall(decodeJson, _ff:read('*a')); _ff:close()
                            if _ok_d and type(_dd) == 'table' then
                                for _date, _day_arr in pairs(_dd) do
                                    if type(_day_arr) == 'table' then
                                        for _, _de in ipairs(_day_arr) do
                                            local _dop  = (_de.op or ''):lower()
                                            local _damt = (_de.price or 0) * (_de.qty or 1)
                                            local _dkey = tostring(_date)..(_de.item or '')..(_de.partner or '')..tostring(_de.qty or 0)..tostring(_de.price or 0)
                                            if not _seen_deals[_dkey] then
                                                _seen_deals[_dkey] = true
                                                if _dop == 'sell' then
                                                    tv_sell = tv_sell + _damt; cnt_sell = cnt_sell + 1
                                                    if _de.t and _de.t ~= '' then last = _de.t end
                                                elseif _dop == 'buy' then
                                                    tv_buy = tv_buy + _damt; cnt_buy = cnt_buy + 1
                                                    if _de.t and _de.t ~= '' then last = _de.t end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                            wait(0)
                        end
                    end
                end
            end
        end
        local batch = 0
        for _, le in ipairs(fh_mkt_log) do
            local _lop = (le.op or ''):upper()
            local _amt = (le.price or 0) * (le.qty or 1)
            local _is_sell = (le.own == true  and _lop == 'SELL') or
                             (le.own == false and _lop == 'BUY')  or
                             (le.own == nil   and _lop == 'SELL')
            local _is_buy  = (le.own == true  and _lop == 'BUY')  or
                             (le.own == false and _lop == 'SELL') or
                             (le.own == nil   and _lop == 'BUY')
            local _lkey = (le.dt and le.dt:sub(1,10) or '')
                        ..(le.item or '')..(le.partner or '')
                        ..tostring(le.qty or 0)..tostring(le.price or 0)
            if not _seen_deals[_lkey] then
                if _is_sell then
                    tv_sell = tv_sell + _amt; cnt_sell = cnt_sell + 1
                    if le.dt and le.dt ~= '' then last = le.dt end
                elseif _is_buy then
                    tv_buy = tv_buy + _amt; cnt_buy = cnt_buy + 1
                    if le.dt and le.dt ~= '' then last = le.dt end
                end
            end
            batch=batch+1; if batch%200==0 then wait(0) end
        end
        local tv_trade_sell, tv_trade_buy = 0, 0
        for _, _trd in ipairs(fh_trade_log or {}) do
            tv_trade_sell = tv_trade_sell + (_trd.get_money  or 0)
            tv_trade_buy  = tv_trade_buy  + (_trd.give_money or 0)
            wait(0)
        end
        local xp_from_log = _xp_from_virtu(tv_sell, tv_buy, tv_trade_sell, tv_trade_buy)
        if not _G._xp_db[nl] then _G._xp_db[nl]={display_nick=nick} end
        local p = _G._xp_db[nl]
        p.display_nick = nick
        p.sales_virtu      = tv_sell
        p.buy_virtu        = tv_buy
        p.trade_sell_virtu = tv_trade_sell
        p.trade_buy_virtu  = tv_trade_buy
        local xp = xp_from_log
        p.xp=xp; p.level=_xp_level(xp)
        if tv_sell > 0 then p.sales_count=cnt_sell end
        if tv_buy  > 0 then p.buy_count=cnt_buy   end
        if last ~= '' then p.last_sale=last end
        p.is_premium=_mh_is_premium()
        _G._xp_rank_cache=nil
        _xp_save(); _xp_push_self()
        mh_notify('[MH] {aaffaa}XP: Lv.'..p.level..' | '..math.floor(xp)..' XP'
            ..' | прод: $'..math.floor((tv_sell+tv_trade_sell)/1e6)..'M'
            ..' | пок: $'..math.floor(((p.buy_virtu or 0)+tv_trade_buy)/1e6)..'M'
            ..' | трейд+: $'..math.floor(tv_trade_sell/1e6)..'M'
            ..' | трейд-: $'..math.floor(tv_trade_buy/1e6)..'M', 0xFFFFFF)
    end)
end
function _mh_tx_fingerprint()
    return nil
end
function _xp_push_self()
    local nick = ''
    pcall(function()
        local _pid = select(2, sampGetPlayerIdByCharHandle(PLAYER_PED))
        nick = sampGetPlayerNickname(_pid) or ''
    end)
    if nick == '' then pcall(function() nick = sampGetCurrentPlayerName() or '' end) end
    if nick == '' then nick = (settings.premium and settings.premium.nick) or '' end
    if nick == '' then return end
    if nick:lower():match('^player_[%x%d]+$') then return end
    local _now_ps = os.time()
    if _G._xp_push_last_ts and (_now_ps - _G._xp_push_last_ts) < 60 then
        return
    end
    local nick_lo = nick:lower()
    if not _G._xp_db[nick_lo] then _G._xp_db[nick_lo] = {} end
    _G._xp_db[nick_lo].display_nick = nick
    local p = _G._xp_db[nick_lo] or {}
    local _live_idx = _mpf7d()
    local _sel_idx  = _G.arz_srv_sel and (_G.arz_srv_sel[0] + 1)
