        _srv_idx = _sel_idx
    end
    local srv = (_srv_idx and (ARZ_SERVERS[_srv_idx] or {}).id) or -1
    if srv == -1 then
        local _cached_srv = _G._xp_db[nick_lo] and _G._xp_db[nick_lo].server
        if _cached_srv and _cached_srv ~= -1 then srv = _cached_srv end
    end
    if srv ~= -1 then
        _G._xp_db[nick_lo].server = srv
    end
    local body = encodeJson({
        nick               = _to_utf8(nick),
        server             = srv,
        xp                 = math.floor(p.xp or 0),
        level              = math.floor(p.level or 0),
        sales_virtu        = math.floor(p.sales_virtu or 0),
        sales_count        = math.floor(p.sales_count or 0),
        buy_virtu          = math.floor(p.buy_virtu or 0),
        buy_count          = math.floor(p.buy_count or 0),
        trade_sell_virtu   = math.floor(p.trade_sell_virtu or 0),
        trade_buy_virtu    = math.floor(p.trade_buy_virtu  or 0),
        premium            = _mh_is_premium(),
    })
    local _hash_key = tostring(nick) .. '|' ..
        tostring(math.floor(p.xp or 0)) .. '|' ..
        tostring(math.floor(p.sales_virtu or 0)) .. '|' ..
        tostring(math.floor(p.sales_count or 0)) .. '|' ..
        tostring(math.floor(p.buy_virtu or 0)) .. '|' ..
        tostring(math.floor(p.trade_sell_virtu or 0)) .. '|' ..
        tostring(math.floor(p.trade_buy_virtu or 0)) .. '|' ..
        tostring(srv)
    if _G._xp_push_last_hash == _hash_key then return end
    _G._xp_push_last_hash = _hash_key
    _G._xp_push_last_ts   = _now_ps
    _jmx9s(_vbr7n..'/rating/push', body, function() end)
end
