    if (_now - _lvn7s_last) < 30 then return end
    _lvn7s_pending = true
    local _snap = fh_session_chat
    lua_thread.create(function()
        wait(0)
        local ok, j = pcall(encodeJson, _snap)
        if ok then
            _mh_ensure_dir(getWorkingDirectory():gsub('\\', '/'):gsub('/$', '') .. '/MarketHelper')
            wait(0)
            local f = io.open(_mh_chat_persist_path, 'w')
            if f then f:write(j); f:close() end
        end
        _lvn7s_pending = false
        _lvn7s_last    = os.time()
    end)
end
