function _mh_capture_own_shop_from_pending(owner, shop_num)
    if not owner or owner == '' or not shop_num then return false end
    local my_nick = ''
    pcall(function()
        local _ok_id, _pid = sampGetPlayerIdByCharHandle(PLAYER_PED)
        if _ok_id then my_nick = sampGetPlayerNickname(_pid) or '' end
    end)
    if my_nick == '' or owner:lower() ~= my_nick:lower() then return false end
    local snap = {owner=my_nick, shop_num=tonumber(shop_num) or shop_num,
        server_id=(type(_mh_cloud_current_server_id)=='function' and _mh_cloud_current_server_id()) or -1,
        ts=os.time(), sell_active=false, buy_active=false, sell_items={}, buy_items={}}
    local by_side = { [13] = {}, [28] = {} }
    local side_order = { [13] = {}, [28] = {} }
    local no_slot_groups = { [13] = {}, [28] = {} }
    local no_slot_order = { [13] = {}, [28] = {} }
    local saw_sell, saw_buy = false, false
    local capture_buf = mh_own_shop_capture_buf or {}
    for _, batch in ipairs(capture_buf) do
        local pkt = tonumber(batch.pkt_type)
        if pkt == 13 or pkt == 28 then
            if pkt == 13 then saw_sell = true else saw_buy = true end
            if type(batch.items) == 'table' then
                for _, it in ipairs(batch.items) do
                    local iid = tonumber(it.item_id)
                    local price = tonumber(it.price) or 0
                    local slot = tonumber(it.slot_idx) or 0
                    if iid and price > 0 then
                        local nm = _G._rgn9z(iid)
                        nm = tostring(nm or ''):gsub('{[^}]+}',''):match('^%s*(.-)%s*$') or ''
                        if nm ~= '' then
                            local rec = {name=nm, price=price, qty=1, item_id=iid, slot_idx=slot, ench=tonumber(it.ench) or 0}
                            if slot > 0 then
                                local key = tostring(slot)
                                if by_side[pkt][key] then
                                    by_side[pkt][key] = rec
                                else
                                    by_side[pkt][key] = rec
                                    side_order[pkt][#side_order[pkt] + 1] = key
                                end
                            else
                                local key = tostring(iid)..'|'..tostring(price)..'|'..tostring(tonumber(it.ench) or 0)
                                if no_slot_groups[pkt][key] then
                                    no_slot_groups[pkt][key].qty = no_slot_groups[pkt][key].qty + 1
                                else
                                    no_slot_groups[pkt][key] = rec
                                    no_slot_order[pkt][#no_slot_order[pkt] + 1] = key
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    local function append_side(pkt, dst)
        if pkt ~= 13 and pkt ~= 28 then return end
        local keys = side_order[pkt]
        table.sort(keys, function(a,b) return (tonumber(a) or 0) < (tonumber(b) or 0) end)
        for _, key in ipairs(keys) do dst[#dst + 1] = by_side[pkt][key] end
        for _, key in ipairs(no_slot_order[pkt]) do dst[#dst + 1] = no_slot_groups[pkt][key] end
    end
    append_side(13, snap.sell_items)
    append_side(28, snap.buy_items)
    snap.sell_active=saw_sell; snap.buy_active=saw_buy
    _G._mh_own_shop_live_snapshot=snap
    _G._mh_own_shop_live_snapshot_mono=os.clock()
    _G._mh_own_shop_live_snapshot_gen=(_G._mh_own_shop_live_snapshot_gen or 0) + 1
    _G._mh_own_shop_live_snapshot_fresh=true
    settings.my_shop_snapshot=snap
    _mh_sync_current_own_shop_num(snap.shop_num)
    if mh_debug_enabled then mh_notify('[MH] own live shop: sell='..#snap.sell_items..' buy='..#snap.buy_items..' num='..tostring(snap.shop_num),0x88FF88) end
    return true
end
