local _fhd_migrated = false
local function _fhd_migrate_stray(real_dir)
    if _fhd_migrated then return end
    _fhd_migrated = true
    local lfs_ok, lfs = pcall(require, 'lfs')
    if not lfs_ok then return end
    local stray_dir = getWorkingDirectory():gsub('\\\\','/') .. '/MarketHelper/FH_daily_prices'
    if not lfs.attributes(stray_dir) then return end
    for fname in lfs.dir(stray_dir) do
        if fname:match('^%d%d%d%d%-%d%d%-%d%d%.json$') then
            local src = stray_dir .. '/' .. fname
            local dst = real_dir  .. '/' .. fname
            local src_attr = lfs.attributes(src)
            local dst_attr = lfs.attributes(dst)
            local should_move = true
            if dst_attr and src_attr and dst_attr.size >= src_attr.size then
                should_move = false
            end
            if should_move then
                local f = io.open(src, 'r')
                if f then
                    local data = f:read('*a'); f:close()
                    local fw = io.open(dst, 'w')
                    if fw then fw:write(data); fw:close() end
                end
            end
            os.remove(src)
        end
    end
    pcall(lfs.rmdir, stray_dir)
end
local function _nvw9k()
