_G._mh_daily_push_last = 0
local function _mh_upload_daily_prices()
    local now = os.time()
    if now - (_G._mh_daily_push_last or 0) < 3600 then return end
    local srv_id = (function()
        local _sel  = _G.arz_srv_sel and (_G.arz_srv_sel[0] + 1) or 0
        local _live = (type(_mpf7d) == 'function') and _mpf7d() or 0
        local _boot = _G.mh_boot_srv_idx and (_G.mh_boot_srv_idx > 0) and (_G.mh_boot_srv_idx + 1) or 0
        local _idx
        if _sel > 1 then _idx = _sel
        elseif _live > 0 then _idx = _live + 1
        elseif _boot > 0 then _idx = _boot end
        return _idx and (ARZ_SERVERS[_idx] or {}).id or -1
    end)()
    if srv_id == -1 then return end
    local today = os.date('%Y-%m-%d')
    local path = _gfr3j(today)
    local f = io.open(path, 'r')
    if not f then return end
    local ok, data = pcall(decodeJson, f:read('*a')); f:close()
    if not ok or type(data) ~= 'table' then return end
    local _merged = {}
    for nm, rec in pairs(data) do
        if type(nm) == 'string' and type(rec) == 'table' then
            local canon = _mh_norm_nm(nm)
            if not _merged[canon] then
                _merged[canon] = {s_totalP=0,s_totalC=0,b_totalP=0,b_totalC=0,b_max=0}
            end
            local m = _merged[canon]
            m.s_totalP = m.s_totalP + (rec.s_totalP or 0)
            m.s_totalC = m.s_totalC + (rec.s_totalC or 0)
            m.b_totalP = m.b_totalP + (rec.b_totalP or 0)
            m.b_totalC = m.b_totalC + (rec.b_totalC or 0)
            m.b_max    = math.max(m.b_max, rec.b_max or 0)
            if rec.s_min and rec.s_min > 0 then
                m.s_min = m.s_min and math.min(m.s_min, rec.s_min) or rec.s_min
            end
            if rec.s_max and rec.s_max > 0 then
                m.s_max = m.s_max and math.max(m.s_max, rec.s_max) or rec.s_max
            end
            if rec.b_min and rec.b_min > 0 then
                m.b_min = m.b_min and math.min(m.b_min, rec.b_min) or rec.b_min
            end
        end
    end
    local _snap_path = _gfr3j(today .. '.sent')
    if not _G._mh_daily_sent_snap or _G._mh_daily_sent_date ~= today then
        local _snap_loaded = {}
        local _sf = io.open(_snap_path, 'r')
        if _sf then
            local _ok_s, _d_s = pcall(decodeJson, _sf:read('*a')); _sf:close()
            if _ok_s and type(_d_s) == 'table' then _snap_loaded = _d_s end
        end
        _G._mh_daily_sent_snap = _snap_loaded
        _G._mh_daily_sent_date = today
    end
    local _snap = _G._mh_daily_sent_snap
    local function _save_snap()
        local _ok_j, _j = pcall(encodeJson, _snap)
        if _ok_j then
            local _sf2 = io.open(_snap_path, 'w')
            if _sf2 then _sf2:write(_j); _sf2:close() end
        end
    end
    local items = {}
    local _new_snap = {}
    for nm, rec in pairs(_merged) do
        if type(nm) == 'string' and type(rec) == 'table' then
            local s_avg = rec.s_totalC > 0 and math.floor(rec.s_totalP / rec.s_totalC) or nil
            local b_avg = rec.b_totalC > 0 and math.floor(rec.b_totalP / rec.b_totalC) or nil
            if s_avg or b_avg then
                local prev = _snap[nm]
                local s_cnt = rec.s_totalC or 0
                local b_cnt = rec.b_totalC or 0
                local _changed = (not prev)
                    or (s_cnt ~= (prev.s_cnt or 0))
                    or (b_cnt ~= (prev.b_cnt or 0))
                if _changed then
                    table.insert(items, {
                        name  = nm,
                        s_avg = s_avg or 0,
                        s_cnt = s_cnt,
                        b_avg = b_avg or 0,
                        b_cnt = b_cnt,
                        b_max = rec.b_max or 0,
                        s_min = rec.s_min or 0,
                        s_max = rec.s_max or 0,
                        b_min = rec.b_min or 0,
                    })
                end
                _new_snap[nm] = {s_cnt = s_cnt, b_cnt = b_cnt}
            end
        end
    end
    if #items == 0 then
        _G._mh_daily_push_last = now
        return
    end
    _G._mh_daily_push_last = now
    if mh_debug_enabled then
        local ok_full, full_body = pcall(encodeJson, {server_id=srv_id, date=today, items=items})
        mh_notify('[MH Cloud] {8888ff}Daily: '..#items..' items, полный размер: '..
            (ok_full and (#full_body..' байт') or 'ошибка encode'), 0xFFFFFF)
    end
    local BATCH_SIZE = 25
    local batches = {}
    for i = 1, #items, BATCH_SIZE do
        local chunk = {}
        for j = i, math.min(i + BATCH_SIZE - 1, #items) do
            chunk[#chunk + 1] = items[j]
        end
        batches[#batches + 1] = chunk
    end
    local total_ok, total_err = 0, 0
    local function send_batch(idx)
        if idx > #batches then
            _save_snap()
            if mh_debug_enabled then
                if total_err == 0 then
                    mh_notify('[MH Cloud] {00cc88}Суточные: '..#items..' товаров, изменившихся с прошлой отправки ('..#batches..' парт.)', 0xFFFFFF)
                else
                    mh_notify('[MH Cloud] {ff6666}Суточные: '..total_ok..'/'..#batches..' парт. отправлено, ошибок: '..total_err, 0xFFFFFF)
                end
            end
            return
        end
        local ok_j, body = pcall(encodeJson, {server_id=srv_id, date=today, items=batches[idx]})
        if not ok_j then
            total_err = total_err + 1
            send_batch(idx + 1)
            return
        end
        if mh_debug_enabled then
            mh_notify('[MH Cloud] {8888ff}Парт. '..idx..'/'..#batches..': '..#batches[idx]..' шт., '..#body..' байт, url='.._vbr7n..'/daily/push', 0xFFFFFF)
        end
        _jmx9s(_vbr7n .. '/daily/push', body, function(code, text, err)
            if code == 200 then
                total_ok = total_ok + 1
                for _, _bit in ipairs(batches[idx]) do
                    _snap[_bit.name] = _new_snap[_bit.name] or {s_cnt = _bit.s_cnt, b_cnt = _bit.b_cnt}
                end
            else
                total_err = total_err + 1
                if mh_debug_enabled then
                    local _txt_s = tostring(text or ''):sub(1, 150)
                    mh_notify('[MH Cloud] {ff6666}Парт. '..idx..' код='..tostring(code)..' err='..tostring(err or '-')..' body='.._txt_s, 0xFFFFFF)
                end
            end
            send_batch(idx + 1)
        end)
    end
    send_batch(1)
end
