                    table.insert(days, {date=y..'-'..m..'-'..d2, s_avg=s_avg, s_min=s_min, s_prices_avg=s_prices_avg,
                        b_avg=b_avg, b_max=b_max, s_prices=s_prices, b_prices=b_prices})
