            local clean = raw:gsub("{%x+}", "")
            local price_raw2
            name, price_raw2 = clean:match('^(.-)%s*    (.+)$')
            if not name then name, price_raw2 = clean:match('^(.-)%s%s+(.+)$') end
            name = name and name:match("^%s*(.-)%s*$") or ""
            name = name:gsub('##%a%d+$','')
            local price = _parse_mkt_price(price_raw2 or '')
            if name ~= "" and price and price > 1000 then
                name = _mh_norm_nm(name)
                local e = fh_mkt_auto[name] or {}
                if not e.cp_st or (os.time() - (e.cp_st or 0)) > 60 then
                    e.cp_st = os.time(); e.cp_sp = nil
                    e.s_totalP = nil; e.s_totalC = nil
                    e.s_min = nil; e.s_max = nil
                end
                if e.cp_sp then
                    e.s_min = e.s_min and math.min(e.s_min, price) or math.min(e.cp_sp, price)
                    e.s_max = e.s_max and math.max(e.s_max, price) or math.max(e.cp_sp, price)
                else e.cp_sp = price end
                e.s_totalP = (e.s_totalP or 0) + price
                e.s_totalC = (e.s_totalC or 0) + 1
                e.s_avg = math.floor(e.s_totalP / e.s_totalC)
                e.s_min = e.s_min or price; e.s_max = e.s_max or price
                if not e.hist then e.hist = {} end
                local dt_now = os.date("%d.%m")
                if not e.hist[1] or e.hist[1].dt ~= dt_now then
                    table.insert(e.hist, 1, {dt = dt_now, price = price})
                    while #e.hist > 30 do table.remove(e.hist) end
                else e.hist[1].price = price end
                e.date = os.date("%d.%m.%Y"); e._is_auto = true; e._loc_ts = os.time(); fh_mkt_auto[name] = e; count = count + 1
            end
        end
    end
    if count > 0 then fh_mkt_auto_last_upd = os.date("%d.%m %H:%M") end
    return count
end
local function fh_mkt_parse_auto_list(text)
    local items = {}
    if not text or text == '' then return items end
    text = mh_dlg_cp(text)
    local iline = 0; local list_idx = -1
    for raw in text:gmatch('[^\n]+') do
        iline = iline + 1
        if iline == 1 then
        else
            list_idx = list_idx + 1
            local clean = raw:gsub('{%x+}',''):match('^%s*(.-)%s*$') or ''
            local skip = clean == '' or
                clean:find('^Поиск по') or
                clean:find('^Следующая страница') or
                clean:find('^Предыдущая страница') or
                clean:find('Сканировать все авто') or
                clean:find('Углублённый скан')
            if not skip and clean ~= '' then
                local nm = clean:match('^(.-)%s*\t') or clean:match('^(.-)%s*%$') or clean
                nm = nm:gsub('##%a%d+$',''):match('^%s*(.-)%s*$') or ''
                if nm ~= '' and #nm > 1 then table.insert(items, {name=nm, idx=list_idx}) end
            end
        end
    end
    return items
end
local function fh_mkt_parse_auto_detail(text, title_text)
    if not text or text == '' then return nil end
    local item_name = ''
    if title_text then
        local tn = title_text:gsub('{%x+}',''):match('^%s*(.-)%s*$') or ''
        local nm = tn:match("'(.+)'") or tn:match('"(.+)"')
        if nm and nm ~= '' then item_name = nm
        elseif tn ~= '' and not tn:find('Продажа') and not tn:find('последние') then item_name = tn end
    end
    if item_name == '' then return nil end
    item_name = item_name:gsub('##%a%d+$','')
    local history = {}
    for line in text:gmatch('[^\n]+') do
        local clean = line:gsub('{%x%x%x%x%x%x}',''):match('^%s*(.-)%s*$') or ''
        if clean ~= '' then
            local dt_s, qty_s, price_s
            dt_s, qty_s, price_s = clean:match('^(%d%d%d%d%-%d%d%-%d%d)%s*\t%s*(%d+)%s*\t%s*(.+)')
            if not dt_s then dt_s, qty_s, price_s = clean:match('^(%d%d%d%d%-%d%d%-%d%d)%s+(%d+)%s+(.+)') end
            if not dt_s then dt_s, qty_s, price_s = clean:match('^(%d%d%d%d%-%d%d%-%d%d)%s*|%s*(%d+)%s*|%s*(.+)') end
            if not dt_s then
                local p2; dt_s, p2 = clean:match('^(%d%d%d%d%-%d%d%-%d%d)%s*\t%s*(.+)')
                if dt_s then qty_s = '1'; price_s = p2 end
            end
            if dt_s and price_s then
                local price = _parse_mkt_price(price_s)
                local qty = tonumber(qty_s) or 1
                if price and price > 0 then table.insert(history, {dt=dt_s, qty=qty, price=price}) end
            end
        end
    end
    return { name=item_name, history=history }
end
local function fh_mkt_save_auto_detail(item_name, history)
    if not item_name or item_name == '' or not history or #history == 0 then return end
    local dt = os.date('%d.%m %H:%M')
    local e = fh_mkt_auto[item_name] or {}
    e.cp_hist = history
    local total_pxq, total_q = 0, 0; local s_min, s_max
    for _, h in ipairs(history) do
        if h.price and h.price > 0 then
            local q = h.qty or 1
            total_pxq = total_pxq + h.price * q; total_q = total_q + q
            if not s_min or h.price < s_min then s_min = h.price end
            if not s_max or h.price > s_max then s_max = h.price end
        end
    end
    if total_q > 0 then
        e.s_avg = math.floor(total_pxq/total_q); e.s_min = s_min; e.s_max = s_max
        e.s_totalC = total_q; e.date = dt
    end
    e._loc_ts = os.time()                                                                                 
    fh_mkt_auto[item_name] = e; fh_mkt_auto_last_upd = dt
end
function _mh_deep_engine(cfg)
    local tag = cfg.tag or '[MH]'
    local stats = { done = 0, skipped = 0, resets = 0, aborted = nil }
    local scanned = {}
    local rtt_ms, rtt_n = cfg.rtt0 or 1000, 0
    local assumed = cfg.txt0                                                                                  
    local TRIES = cfg.item_tries or 3
    local PTRIES = cfg.page_tries or 3
    local LOST = cfg.lost_ms or 25000
    local function upd_rtt(ms)
        rtt_n = rtt_n + 1
        rtt_ms = math.floor((rtt_ms * math.min(rtt_n - 1, 9) + ms) / math.min(rtt_n, 10))
    end
    local function srv_to(mul)
        return math.max(cfg.to_min, math.min(rtt_ms * (mul or 1) * cfg.to_k + cfg.to_add, cfg.to_max))
    end
    local function running() return cfg.is_active() end
    local function nap(ms)
        local t = 0
        while t < ms and running() do wait(50); t = t + 50 end
    end
    local function dbg(msg, scr)
        if scr then printStyledString(scr, 1500, 6) end
        if mh_debug_enabled then mh_notify(tag .. ' {aaaaaa}' .. msg, 0xFFFFFF) end
    end
    local function list_open()
        return sampIsDialogActive() and sampGetCurrentDialogId() == cfg.list_id
    end
    local function wait_list(old_txt, ms)
        local t0 = os.clock(); local t = 0
        while t < ms and running() do
            wait(16); t = t + 16
            if list_open() then
                local ntxt = mh_dlg_text() or ''
                if not old_txt or ntxt ~= old_txt then
                    upd_rtt(math.floor((os.clock() - t0) * 1000))
                    return sampGetCurrentDialogId(), ntxt
                end
            end
        end
        return nil, nil
    end
    local function wait_detail(ms)
        local t0 = os.clock(); local t = 0
        local other = nil
        while t < ms and running() do
            wait(16); t = t + 16
            if sampIsDialogActive() then
                local cid = sampGetCurrentDialogId()
                if cid ~= cfg.list_id then
                    local title = fh_last_dlg_title or ''
                    if cfg.is_detail(title) then
                        upd_rtt(math.floor((os.clock() - t0) * 1000))
                        return cid, (mh_dlg_text() or ''), title, nil
                    end
                    other = cid
                end
            end
        end
        return nil, nil, nil, other
    end
    local function close_stray()
        if sampIsDialogActive() then
            local cid = sampGetCurrentDialogId()
            if cid ~= cfg.list_id then
                local btn = 0
                if cid ~= 26048 and cfg.is_detail(fh_last_dlg_title or '') then btn = 1 end
                sampSendDialogResponse(cid, btn, 0, '')
                return true
            end
        end
        return false
    end
    local function ensure_list(patience_ms)
        if assumed then return cfg.list_id, assumed end
        local t0 = os.clock()
        local told = false
        while running() do
            if list_open() then return cfg.list_id, (mh_dlg_text() or '') end
            close_stray()
            local d, tx = wait_list(nil, math.min(srv_to(1), 4000))
            if d then return d, tx end
            if (os.clock() - t0) * 1000 > patience_ms then return nil, nil end
            if not told then
                told = true
                dbg('Список закрыт - жду возврата (можно нажать "Назад")', '~w~MH wait list')
            end
        end
        return nil, nil
    end
    local function find_idx(txt, name)
        for _, it in ipairs(cfg.parse_list(txt)) do
            if it.name == name then return it.idx end
        end
        return nil
    end
    local function count_item()
        stats.done = stats.done + 1
        cfg.on_progress(stats.done)
    end
    local function process_item(item)
        for try = 1, TRIES do
            if not running() then return 'stop' end
            local ld, lt = ensure_list(LOST)
            if not ld then return 'lost' end
            local idx = find_idx(lt, item.name)
            if not idx then return 'moved' end
            sampSendDialogResponse(ld, 1, idx - cfg.idx_offset(lt), 0)
            assumed = nil
            local dd, dtxt, dtitle, other = wait_detail(math.floor(srv_to(1) * (1 + 0.5 * (try - 1))))
            if dd then
                local detail = cfg.parse_detail(dtxt, dtitle)
                sampSendDialogResponse(dd, 1, 0, '')
                if detail and detail.name ~= '' and #detail.history > 0 then
                    cfg.on_detail(detail)
                end
                scanned[item.name] = true
                count_item()
                wait_list(nil, srv_to(1))
                return 'ok'
            end
            if other then
                close_stray()
                scanned[item.name] = true
                count_item()
                wait_list(nil, srv_to(1))
                return 'ok'
            end
            if try < TRIES then
                dbg('Нет ответа по товару, повтор ' .. try .. '/' .. TRIES, '~w~MH retry ~y~' .. try .. '/' .. TRIES)
                nap(500 * try)
            end
        end
        scanned[item.name] = true
        stats.skipped = stats.skipped + 1
        count_item()
        close_stray()
        return 'skip'
    end
    local function press_back_recover()
        if list_open() then
            sampSendDialogResponse(cfg.list_id, 0, 0, '')
            assumed = nil
        end
        return ensure_list(LOST)
    end
    local pages, consec, back_used, loops = 0, 0, 0, 0
    while running() do
        loops = loops + 1
        if loops > 1500 then stats.aborted = 'loop_cap'; break end
        local ld, lt = ensure_list(LOST)
        if not ld then
            if running() then stats.aborted = 'list_lost' end
            break
        end
        local has_prev = fh_find_listitem(lt, 'Предыдущая страница') ~= nil
        if pages > 0 and not has_prev then
            stats.resets = stats.resets + 1
            pages = 0
            dbg('Список вернулся на 1-ю страницу, пропускаю снятое', '~w~MH page 1')
            if stats.resets > 8 then stats.aborted = 'too_many_resets'; break end
        end
        local restart = false
        for _, item in ipairs(cfg.parse_list(lt)) do
            if not running() then break end
            if not scanned[item.name] then
                local res = process_item(item)
                if res == 'ok' then
                    consec = 0
                elseif res == 'skip' then
                    consec = consec + 1
                    if consec >= 3 then
                        consec = 0
                        if back_used < 2 and running() then
                            back_used = back_used + 1
                            dbg('3 пропуска подряд - "Назад" и продолжаю', '~w~MH back')
                            local rd = press_back_recover()
                            if not rd then
                                if running() then stats.aborted = 'no_response' end
                            end
                            restart = true
                        else
                            stats.aborted = 'no_response'
                        end
                        break
                    end
                elseif res == 'moved' or res == 'lost' then
                    restart = true
                    break
                else
                    break
                end
            end
        end
        if stats.aborted or not running() then break end
        if not restart then
            local ld2, lt2 = ensure_list(LOST)
            if not ld2 then
                if running() then stats.aborted = 'list_lost' end
                break
            end
            if not fh_find_listitem(lt2, 'Следующая страница') then break end                        
            local moved = false
            for try = 1, PTRIES do
                if not running() then break end
                ld2, lt2 = ensure_list(LOST)
                if not ld2 then break end
                local nxt = fh_find_listitem(lt2, 'Следующая страница')
                if not nxt then moved = 'end'; break end
                sampSendDialogResponse(ld2, 1, nxt - cfg.idx_offset(lt2), 0)
                assumed = nil
                local nd = wait_list(lt2, srv_to(2))
                if nd then pages = pages + 1; moved = true; wait(80); break end
                dbg('Страница не открылась, повтор ' .. try .. '/' .. PTRIES, '~w~MH page retry ~y~' .. try .. '/' .. PTRIES)
                nap(800 * try)
            end
            if moved == 'end' then break end
            if not moved and running() then
                if back_used < 2 then
                    back_used = back_used + 1
                    dbg('Страница не листается - "Назад" и продолжаю', '~w~MH back')
                    if not press_back_recover() and running() then stats.aborted = 'page_stuck'; break end
                else
                    stats.aborted = 'page_stuck'
                    break
                end
            end
        end
    end
    return stats
end
function _mh_deep_abort_text(reason)
    if reason == 'list_lost' then return 'окно списка закрылось и не вернулось' end
    if reason == 'no_response' then return 'сервер не отвечает на выбор товара' end
    if reason == 'page_stuck' then return 'не удаётся перейти на следующую страницу' end
    if reason == 'too_many_resets' then return 'список слишком часто сбрасывался на 1-ю страницу' end
    return 'слишком много циклов'
end
local mh_isActiveCommand = false
local _mh_piar_vr_active = false
local function _tcz2r(text, waiting, callback)
    if mh_isActiveCommand then return end
    lua_thread.create(function()
        mh_isActiveCommand = true
        local lines = {}
        for line in text:gmatch("[^&]+") do table.insert(lines, line) end
        for i, line in ipairs(lines) do
            if i > 1 then wait((waiting or 1.5) * 1000) end
            _mh_piar_vr_active = true
            sampSendChat(line)
            wait(1500)
            _mh_piar_vr_active = false
        end
        mh_isActiveCommand = false
        if callback then callback() end
    end)
end
