        local _boot = _G.mh_boot_srv_idx and (_G.mh_boot_srv_idx > 0) and (_G.mh_boot_srv_idx + 1) or 0
        local _idx
        if _sel > 1 then _idx = _sel
        elseif _live > 0 then _idx = _live + 1
        elseif _boot > 0 then _idx = _boot end
        return _idx and (ARZ_SERVERS[_idx] or {}).id or -1
    end)()
    local items = {}
    for nm, e in pairs(fh_mkt_prices) do
        if e and (e.s_avg and e.s_avg > 0 or e.cp_sp and e.cp_sp > 0
                  or e.cp_hist and #e.cp_hist > 0) then
            local entry = { name = _to_utf8(nm) }
            if e.cp_hist and #e.cp_hist > 0 then entry.cp_hist = e.cp_hist end
            if e.cp_sp  and e.cp_sp  > 0 then entry.cp_sp  = e.cp_sp  end
            if e.s_avg  and e.s_avg  > 0 then entry.s_avg  = e.s_avg  end
            if e.s_min  and e.s_min  > 0 then entry.s_min  = e.s_min  end
            if e.s_max  and e.s_max  > 0 then entry.s_max  = e.s_max  end
            table.insert(items, entry)
        end
    end
    if #items == 0 then
        mh_notify('[MH Cloud] {ffaa00}Нет данных ЦР для отправки', 0xFFFFFF)
        return
    end
    _mh_pprices_pushing = true
    lua_thread.create(function()
        local CHUNK_SIZE = 100
        local chunks = {}
        local cur = {}
        for i = 1, #items do
            table.insert(cur, items[i])
            if #cur >= CHUNK_SIZE then table.insert(chunks, cur); cur = {} end
        end
        if #cur > 0 then table.insert(chunks, cur) end
        local total_chunks = #chunks
        local total_items  = #items
        local had_error    = false
        local _tok  = (settings.premium and settings.premium.tok)  or ''
        local _nck  = (settings.premium and settings.premium.nick) or ''
        local _sess = _G._mh_session_tok or ''
        mh_notify('[MH Cloud] {aaffaa}Отправляю '..total_items
            ..' товаров ('..total_chunks..' чанк'..(total_chunks>1 and 'ов' or '')..')...', 0xFFFFFF)
        for ci = 1, total_chunks do
            local chunk = chunks[ci]
            local ok_j, j = pcall(encodeJson, { server_id = srv_id, items = chunk })
            if not ok_j then
                mh_notify('[MH Cloud] {ff4444}Ошибка JSON чанк '..ci, 0xFFFFFF)
                had_error = true; break
            end
            local th = effil.thread(_twd4k)(_vbr7n..'/prices/push', j, _tok, _nck, _sess)
            local _deadline = os.clock() + 30
            local code = 0
            while true do
                wait(30)
                if os.clock() > _deadline then
                    pcall(function() th:cancel() end)
                    mh_notify('[MH Cloud] {ff4444}Чанк '..ci..'/'..total_chunks..': таймаут', 0xFFFFFF)
                    had_error = true; break
                end
                local st, err = th:status()
                if not st or err then
                    mh_notify('[MH Cloud] {ff4444}Чанк '..ci..'/'..total_chunks..': ошибка потока', 0xFFFFFF)
                    had_error = true; break
                end
                if st == 'completed' or st == 'canceled' then
                    local ok2, resp = th:get()
                    if ok2 and resp then
                        code = resp.status_code or 0
                        local rbody = resp.text or ''
                        if code == 200 and rbody:find('"ok":false') then code = 403 end
                    end
                    break
                end
            end
            if had_error then break end
            if code ~= 200 then
                mh_notify('[MH Cloud] {ff4444}Чанк '..ci..'/'..total_chunks..' err:'..code, 0xFFFFFF)
                had_error = true; break
            end
            if ci < total_chunks then wait(300) end
        end
        _mh_pprices_pushing = false
        if not had_error then
            mh_notify('[MH Cloud] {00cc00}ЦР отправлены ('..total_items..' товаров, '..total_chunks..' чанк'..(total_chunks>1 and 'ов' or '')..')', 0xFFFFFF)
        end
    end)
end
