function _mh_positive_shop_items(items)
    local out = {}
    for _, it in ipairs(items or {}) do
        if type(it) == "table" then
            local name = tostring(it.name or "")
            local price = tonumber(it.price) or 0
            local qty = tonumber(it.qty) or 0
            if name ~= "" and name ~= "?" and price > 0 and qty > 0 then
                local copy = {}
                for k, v in pairs(it) do copy[k] = v end
                copy.price = price
                copy.qty = qty
                table.insert(out, copy)
            end
        end
    end
    return out
end
function _crf5h(s, _on_result)
    if not s or not s.owner or s.owner == '' then return end
    if mh_debug_enabled then
        mh_notify('[MH DBG] _crf5h: '..tostring(s.owner)..' srv='..tostring(s.server_id or -1)..' sell='..#(s.sell_items or {})..' buy='..#(s.buy_items or {}), 0x66AAFF)
    end
    local _owner_u8 = _to_utf8(s.owner)
    local _clean_sell = _mh_positive_shop_items(s.sell_items)
    local _clean_buy  = _mh_positive_shop_items(s.buy_items)
    local _sell_u8, _buy_u8 = {}, {}
    for _, it in ipairs(_clean_sell) do
        table.insert(_sell_u8, { name = _to_utf8(it.name), price = it.price, qty = it.qty, item_id = it.item_id or 0, ench = ((tonumber(it.ench) or 0) > 0) and tonumber(it.ench) or nil })
    end
    for _, it in ipairs(_clean_buy) do
        table.insert(_buy_u8, { name = _to_utf8(it.name), price = it.price, qty = it.qty, item_id = it.item_id or 0, ench = ((tonumber(it.ench) or 0) > 0) and tonumber(it.ench) or nil })
    end
    local _sid = s.server_id or -1
    if _sid == -1 then
        local _auto = _mpf7d()
        if _auto and _auto > 0 then
            _sid = (ARZ_SERVERS[_auto + 1] or {}).id or -1
        end
    end
    if mh_debug_enabled and _sid == -1 then
        mh_notify('[MH Cloud] {ffaa00}Push с server_id=-1 (' .. (s.owner or '?') .. ') — сервер примет', 0xFFFFFF)
    end
    local payload = {
        server_id  = _sid,
        owner      = _owner_u8,
        shop_num   = tostring(s.shop_num or '?'),
        sell_slots = _sell_u8,
        buy_slots  = _buy_u8,
        scanned_at = os.time(),
    }
    local ok_j, j = pcall(encodeJson, payload)
    if not ok_j then
        mh_notify('[MH Cloud] {ff6644}JSON encode err', 0xFFFFFF)
        return
    end
    _jmx9s(_vbr7n .. '/shops/push', j, function(code, body, _e)
        _szb8v   = (code == 200)
        _gnl3q = os.time()
        if code == 200 then
            if mh_debug_enabled then
                mh_notify('[MH Cloud] {aaffaa}Push OK: ' .. _owner_u8, 0xFFFFFF)
            end
            if _on_result then _on_result(true, nil) end
        elseif code == nil and _e and (tostring(_e):find('connect') or tostring(_e):find('timeout') or tostring(_e):find('refused') or tostring(_e):find('resolve')) then
            mh_notify('[MH Cloud] {ff4444}Нет связи с сервером: ' .. tostring(_e), 0xFFFFFF)
            if _on_result then _on_result(false, 'no_connection') end
        elseif code == 0 then
            mh_notify('[MH Cloud] {ff4444}Лавка НЕ отправлена: запрос не дошёл до сервера (внутренняя ошибка сети). Попробуй ещё раз.', 0xFFFFFF)
            if _on_result then _on_result(false, 'code_0') end
        elseif code ~= 200 and code ~= nil then
            mh_notify('[MH Cloud] {ff6644}Push: сервер вернул ' .. tostring(code), 0xFFFFFF)
            if _on_result then _on_result(false, 'http_' .. tostring(code)) end
        else
            _szb8v = true
            if _on_result then _on_result(true, nil) end
        end
    end)
end
local function mh_push_own_preset_shop(merge_existing, from_presets)
    local my_nick = ''
    pcall(function()
        my_nick = sampGetPlayerNickname(select(2, sampGetPlayerIdByCharHandle(PLAYER_PED))) or ''
    end)
    if my_nick == '' then return end
    local _previous_snapshot_num = settings.my_shop_snapshot and tonumber(settings.my_shop_snapshot.shop_num)
    local _previous_saved_num = settings.general and tonumber(settings.general.own_shop_num_saved)
    local my_shop_num = _G._mh_own_shop_capture_num or mh_own_shop_num

    -- When the player is standing by the newly listed shop, the visible 3D label
    -- is the freshest source. Do not let a relog value from the previous shop win.
