            if _G.mh_ab_caught_dlg then
                local c = _G.mh_ab_caught_dlg
                if ids == nil then _G.mh_ab_caught_dlg = nil; return c end
                for _, id in ipairs(ids) do
                    if c == id then _G.mh_ab_caught_dlg = nil; return c end
                end
            end
            if sampIsDialogActive() then
                local c = sampGetCurrentDialogId()
                if ids == nil then return c end
                for _, id in ipairs(ids) do
                    if c == id then return c end
                end
            end
        end
        return nil
    end
    local function close_dlg()
        _G.mh_ab_caught_dlg = nil
        if sampIsDialogActive() then
            sampSendDialogResponse(sampGetCurrentDialogId(), 0, 0, '')
            local _el = 0
            while _el < 200 and sampIsDialogActive() do
                wait(25); _el = _el + 25
            end
        end
    end
    local function wait_text_settle(dlg_id, max_ms)
        local el = 0
        local prev = ''
        local stable_confirms = 0
        while el < max_ms do
            wait(25); el = el + 25
            if not sampIsDialogActive() or sampGetCurrentDialogId() ~= dlg_id then
                return sampGetDialogText() or ''
            end
            local cur = sampGetDialogText() or ''
            if cur ~= '' then
                if cur == prev then
                    stable_confirms = stable_confirms + 1
                    if stable_confirms >= 2 then return cur end
                else
                    stable_confirms = 0
                end
                prev = cur
            end
        end
        return prev
    end
