            .. '|' .. _dtl_cache_key
        local _dtl_min_interval = 60
        local _dtl_since_build  = os.time() - (_G._dtl_last_build_ts or 0)
        local _dtl_first_build  = not _G._dtl_stats
        if _G._dtl_last_data_ver == _cur_data_ver then
