    { own=false, op='SELL', pat='Вы успешно купили (.+) %((%d+) шт%.%) у ([%a_][%w_]*) за .-([КМ][К]?%s*[%d][%d%.%,]*%s*[КМ]?[К]?%s*[%d]?[%d%.%,]*)' },
    { own=false, op='SELL', pat='Вы успешно купили (.+) %((%d+) шт%.%) у ([%a_][%w_]*) за .-([%d][%d%.%,]*)' },
    { own=false, op='SELL', pat='Вы успешно купили (.+) у ([%a_][%w_]*) за .-([КМ][К]?%s*[%d][%d%.%,]*%s*[КМ]?[К]?%s*[%d]?[%d%.%,]*)' },
    { own=false, op='SELL', pat='Вы успешно купили (.+) у ([%a_][%w_]*) за .-([%d][%d%.%,]*)' },
}
local function _wsn4d(text)
    if not text then return nil end
    local _clean_for_chat_check = text:gsub('{%x+}', '')
    local _head40 = _clean_for_chat_check:sub(1, 40)
    if _head40:match('^%s*[%a_][%w_]*%[%d+%]')
    or _head40:match('^%s*%b[]%s*[%a_][%w_]*%[%d+%]') then
        return nil
    end
    local is_vc = text:find('VC$') ~= nil
    text = text:gsub('[Kk][Kk]', '\xca\xca')
    text = text:gsub('[Kk](%s+[%d%.%,])', '\xca%1')
    text = text:gsub('[Kk]([%d%.%,])', '\xca %1')
    text = text:gsub('[Mm](%s+[%d%.%,])', '\xcc%1')
    text = text:gsub('[Mm]([%d%.%,])', '\xcc %1')
    for _, p in ipairs(FH_TRADE_PATTERNS) do
        local a, b, c, d = text:match(p.pat)
        if a then
            local item, qty, partner, total
            if d then
                if p.pat:find('купил у вас') then
                    partner, item, qty, total = a, b, tonumber(c) or 1, d
                else
                    item, qty, partner, total = a, tonumber(b) or 1, c, d
                end
            else
                if p.pat:find('купил у вас') then
                    partner, item, total = a, b, c
                else
                    item, partner, total = a, b, c
                end
                qty = 1
            end
            local sum = _parse_trade_sum(total)
            local price = qty > 0 and math.ceil(sum / qty) or 0
            if item and price > 0 then
                return {
                    item    = item:match('^%s*(.-)%s*$'),
                    qty     = qty,
                    price   = price,
                    partner = partner or '',
                    op      = p.op,
                    own     = p.own,
                    is_vc   = is_vc,
                }
            end
        end
    end
    return nil
end
_G._mh_sync_own_shop_after_sale = function(_item, _qty, _price)
    local _q = tonumber(_qty) or 0
    if _q <= 0 or not _item or tostring(_item) == '' then return end
    local _nick = ''
    pcall(function()
        local _ok, _id = sampGetPlayerIdByCharHandle(PLAYER_PED)
        if _ok then _nick = sampGetPlayerNickname(_id) or '' end
    end)
    if _nick == '' then return end
    local _own_num = tonumber(mh_own_shop_num)
    if not _own_num and settings.general then
        _own_num = tonumber(settings.general.own_shop_num_saved)
    end
    if not _own_num and type(settings.my_shop_snapshot) == 'table' then
        _own_num = tonumber(settings.my_shop_snapshot.shop_num)
    end
    if not _own_num then return end
    local _name = tostring(_item):gsub('^%s+', ''):gsub('%s+$', ''):lower()
    local _sale_price = tonumber(_price) or 0
    local _changed = false
    local function _reduce_list(_list)
        if type(_list) ~= 'table' then return false end
        local _fallback = nil
        for _, _it in ipairs(_list) do
            if type(_it) == 'table' then
                local _nm = tostring(_it.name or ''):gsub('^%s+', ''):gsub('%s+$', ''):lower()
                if _nm == _name then
                    if _sale_price > 0 and tonumber(_it.price) == _sale_price then
                        local _old = tonumber(_it.qty) or 0
                        _it.qty = math.max(0, _old - _q)
                        return true
                    end
                    if not _fallback then _fallback = _it end
                end
            end
        end
        if _fallback then
            local _old = tonumber(_fallback.qty) or 0
            _fallback.qty = math.max(0, _old - _q)
            return true
        end
        return false
    end
    local _snap = settings.my_shop_snapshot
    if type(_snap) == 'table'
       and tostring(_snap.owner or ''):lower() == _nick:lower()
       and tostring(_snap.shop_num or '?') == tostring(_own_num) then
        if _reduce_list(_snap.sell_items) then
            _snap.ts = os.time()
            _changed = true
        end
    end
    for _, _sh in pairs(fh_other_shops or {}) do
        if type(_sh) == 'table'
           and tostring(_sh.owner or ''):lower() == _nick:lower()
           and tostring(_sh.shop_num or '?') == tostring(_own_num) then
            if _reduce_list(_sh.sell_items) then
                _sh.ts = os.time()
                _changed = true
            end
        end
    end
    for _, _lv in ipairs(mh_arz_data or {}) do
        if type(_lv) == 'table'
           and tostring(_lv.username or ''):lower() == _nick:lower()
           and tostring(_lv.LavkaUid or '?') == tostring(_own_num) then
            local _updated = false
            for _i, _iid in ipairs(_lv.items_sell or {}) do
                local _bid, _ench = _G._bqs3v(_iid)
                local _nm = _G._rgn9z(_bid)
                if _ench and _ench ~= '' then _nm = _nm .. ' (+' .. _ench .. ')' end
                if tostring(_nm or ''):gsub('^%s+', ''):gsub('%s+$', ''):lower() == _name then
                    local _p = tonumber((_lv.price_sell or {})[_i]) or 0
                    if _sale_price <= 0 or _p == _sale_price then
                        local _old = tonumber((_lv.count_sell or {})[_i]) or 0
                        _lv.count_sell[_i] = math.max(0, _old - _q)
                        _updated = true
                        break
                    end
                end
            end
            if _updated then
                _lv._mh_updated_at = os.time()
                _changed = true
            end
        end
    end
    if _changed then
        settings.other_shops = fh_other_shops
        _wfn7p()
    end
end
do
local function fh_merge_by_date(sell_arr, buy_arr)
    local map = {}
    for _, entry in ipairs(sell_arr or {}) do
        local d = entry.dateCreate__date or entry.date or ''
        map[d] = map[d] or {}
        map[d].sell = entry
    end
    for _, entry in ipairs(buy_arr or {}) do
        local d = entry.dateCreate__date or entry.date or ''
        map[d] = map[d] or {}
        map[d].buy = entry
    end
    local result = {}
    for date, v in pairs(map) do
        table.insert(result, {date=date, sell=v.sell, buy=v.buy})
    end
    table.sort(result, function(a, b) return a.date > b.date end)
    return result
end
end
local _pst = (function()
    local function _find(name, preset)
        for i, item in ipairs(preset) do
            if fh_lower(item.name or '') == fh_lower(name or '') then
                return item, i
            end
        end
        return nil, nil
    end
    return {
        find = _find,
        add_sell = function(name, qty, price)
            if _find(name, fh_lv_autosell_preset) then return false end
            table.insert(fh_lv_autosell_preset, {
                name  = name,
                qty   = tonumber(qty) or 1,
                price = tonumber(price) or 0,
            })
            local new_idx = #fh_lv_autosell_preset
            if _G.as_price_buf then _G.as_price_buf[new_idx] = nil end
            if _G.as_qty_buf   then _G.as_qty_buf[new_idx]   = nil end
            if _G.as_en_buf    then _G.as_en_buf[new_idx]    = nil end
            return true
        end,
        add_buy = function(name, qty, max_price)
            if _find(name, fh_lv_autobuy_preset) then return false end
            local _is_q1 = _mh_is_qty1_item(name)
            local _tq = _is_q1 and 1 or (tonumber(qty) or 1)
            table.insert(fh_lv_autobuy_preset, {
                name       = name,
                qty        = _tq,
                target_qty = _tq,
                max_price  = tonumber(max_price) or 0,
                qty_limit_1 = _is_q1 or nil,
            })
            _G.ab_price_buf = nil; _G.ab_qty_buf = nil
            return true
        end,
        remove = function(preset, idx)
            table.remove(preset, idx)
            if _G.as_price_buf then
                local nb = {}
                for i, v in pairs(_G.as_price_buf) do
                    if type(i)=='number' then
                        if i < idx then nb[i]=v elseif i > idx then nb[i-1]=v end
                    end
                end
                _G.as_price_buf = nb
            end
            if _G.as_qty_buf then
                local nb = {}
                for i, v in pairs(_G.as_qty_buf) do
                    if type(i)=='number' then
                        if i < idx then nb[i]=v elseif i > idx then nb[i-1]=v end
                    end
                end
                _G.as_qty_buf = nb
            end
            _G.ab_price_buf = nil; _G.ab_qty_buf = nil
        end,
        clear = function(preset)
            for i = #preset, 1, -1 do table.remove(preset, i) end
            _G.as_price_buf = nil; _G.as_qty_buf = nil
            _G.ab_price_buf = nil; _G.ab_qty_buf = nil
        end,
        ref_price = function(name)
            local lv = fh_mkt_lavka[name]
            if lv and (lv.s_avg or lv.b_avg) then
                return lv.s_avg or lv.b_avg
            end
            local cp = fh_mkt_prices[name]
            if cp then
                if cp.cp_hist and #cp.cp_hist > 0 then
                    local s7  = _mjg5t(cp.cp_hist, 7)
                    local s30 = _mjg5t(cp.cp_hist, 30)
                    local v7  = s7  and s7.avg  and s7.avg  > 0 and s7.avg  or nil
                    local v30 = s30 and s30.avg and s30.avg > 0 and s30.avg or nil
                    if v7 and v30 then return math.min(v7, v30)
                    elseif v7  then return v7
                    elseif v30 then return v30 end
                end
                if cp.s_avg or cp.b_avg then return cp.s_avg or cp.b_avg end
            end
            return fh_get_daily_avg_price(name)
        end,
    }
end)()
function fh_is_my_sell(e)
    local op = (e.op or ''):upper()
    local own = e.own
    if own == true  then return op == 'SELL' end
    if own == false then return op == 'BUY'  end
    return op == 'SELL'
end
