function _mh_theme.hex_to_float3(hex)
    hex = (hex or ''):gsub('#', '')
    if #hex ~= 6 then return 0, 0, 0 end
    local r = tonumber(hex:sub(1, 2), 16) or 0
    local g = tonumber(hex:sub(3, 4), 16) or 0
    local b = tonumber(hex:sub(5, 6), 16) or 0
    return r / 255, g / 255, b / 255
end
function _mh_theme.sync_imgui_accent()
    local t = settings.mh_theme
    local ar, ag, ab = _mh_theme.hex_to_float3(t.accent)
    settings.interface.accent_r, settings.interface.accent_g, settings.interface.accent_b = ar, ag, ab
    if _G.accent_color then
        accent_color[0], accent_color[1], accent_color[2] = ar, ag, ab
    end
    local tr, tg, tb = _mh_theme.hex_to_float3(t.text)
    settings.interface.text_r, settings.interface.text_g, settings.interface.text_b = tr, tg, tb
    if _G.vid_text_col then
        _G.vid_text_col[0], _G.vid_text_col[1], _G.vid_text_col[2] = tr, tg, tb
    end
    if type(_fwb3h) == 'function' then pcall(_fwb3h) end
