function _mh_theme.query_param()
    local t = settings.mh_theme
    local payload = {
        accent      = t.accent,
        accent2     = t.accent2,
        bg          = t.bg,
        panel       = t.panel,
        panel2      = t.panel2,
        text        = t.text,
        text_dim    = t.text_dim,
        line        = t.line,
        font_scale  = t.font_scale,
        panel_alpha = t.panel_alpha,
        font_family = t.font_family,
    }
    local ok_j, j = pcall(encodeJson, payload)
    if not ok_j then return '' end
    local ok_b64, b64 = pcall(function() return require('basexx').to_base64(j) end)
    if not ok_b64 or not b64 then return '' end
    return b64
end
