        imgui.SetCursorPos(imgui.ImVec2(_cp.x, _cp.y + _ph/2 + 12))
        if imgui.Button(fa.ROTATE_RIGHT .. ' ' .. u8'\xcf\xe5\xf0\xe5\xe7\xe0\xef\xf3\xf1\xf2\xe8\xf2\xfc##mh_web_retry', imgui.ImVec2(160*d, 0)) then
            _mh_web_state.created = false
        end
    elseif not _mh_web_state.loaded then
        imgui.SetCursorPos(imgui.ImVec2(_cp.x, _cp.y + _ph/2 - 10))
        local _pct = _mh_web_state.progress
        if type(_pct) == "number" and _pct > 0 and _pct < 100 then
            _mh_web_center_text(u8'\xc7\xe0\xe3\xf0\xf3\xe7\xea\xe0 \xf1\xe0\xe9\xf2\xe0... ' .. _pct .. '%%')
        else
