if _mh_web_jar then
    local _mh_web_onAction_prev = _mh_web_jar.onAction
    function _mh_web_jar.onAction(data)
        if not data then return end                                                               
        if data.browserid == _MH_SHOPS_BID then
            if data.type == "WV_STARTED" then
                _mh_shops_state.crashed = false
                _mh_shops_state.loaded = false
            elseif data.type == "WV_LOADED" then
                _mh_shops_state.loaded = true
                _mh_shops_apply_zoom()
                if _G._mh_shops_tags_push then pcall(_G._mh_shops_tags_push) end
            elseif data.type == "WV_PROGRESS" then
                local p = tonumber(data.msg)
                if p and p > _mh_shops_state.progress then _mh_shops_state.progress = p end
            elseif data.type == "WV_DIE" then
                _mh_shops_state.crashed = true
                _mh_shops_state.created = false
                pcall(function() _mh_web_jar.deleteBrowser(_MH_SHOPS_BID) end)
            elseif data.type == "WV_ANSWER" then
                local _raw_msg = tostring(data.msg or '')
                local _prefix = 'MH_BRIDGE:'
                local _idx = _raw_msg:find(_prefix, 1, true)
                if _idx then
                    local _json_part = _raw_msg:sub(_idx + #_prefix)
                    local _ok_js, _js_obj = pcall(decodeJson, _json_part)
                    if _ok_js and type(_js_obj) == 'table' and _js_obj.kind then
                        pcall(_mh_shops_handle_bridge_payload, _js_obj)
                    end
                end
            elseif data.browserid == _MH_SHOPS_BID and data.type ~= "WV_PROGRESS" then
                return
            end
            return
        end
        if _mh_web_onAction_prev then _mh_web_onAction_prev(data) end
    end
end
