function _mh_bridge_u8_to_cp(s)
    if type(s) ~= 'string' or s == '' then return s end
    local ok, r = pcall(function()
        return require('encoding').CP1251:encode(require('encoding').UTF8:decode(s))
    end)
    return (ok and r) and r or s
end
function _mh_shops_handle_bridge_payload(data)
    if type(data) ~= 'table' or not data.kind then return end
    if data.kind == 'preset' and data.items and #data.items > 0 then
        local _preset_name = _mh_bridge_u8_to_cp(data.name) or 'Скупка (сайт)'
        local _items_cp = {}
        for i = 1, #data.items do
            local it = data.items[i]
            if type(it) == 'table' then
                local _it_cp = {}
                for k, v in pairs(it) do
                    _it_cp[k] = (k == 'name') and _mh_bridge_u8_to_cp(v) or v
                end
                _items_cp[#_items_cp + 1] = _it_cp
            end
        end
        local exp_ok, path_or_err = _mh_export_preset('buy', _preset_name, _items_cp)
        if exp_ok then
            mh_notify('Пресет скупки сохранён: ' .. _preset_name, 0x66FF99)
        else
            mh_notify('Не удалось сохранить пресет скупки: ' .. tostring(path_or_err), 0xFF4F6D)
        end
    elseif data.kind == 'call' and data.owner and data.owner ~= '' then
        local _owner_nick = data.owner
        local _fid = nil
        for _pid = 0, 999 do
            local _ok, _pn = pcall(sampGetPlayerNickname, _pid)
            if _ok and _pn and _pn:lower() == _owner_nick:lower() then _fid = _pid; break end
        end
        if _fid then
            _G._mh_call_pending_nick = _owner_nick:lower()
            sampSendChat('/number ' .. _fid)
            mh_notify('[MH] {aaffaa}Звонок: ' .. _owner_nick, 0xFFFFFF)
        else
            mh_notify('[MH] {ffaa00}' .. _owner_nick .. ' не в сети', 0xFFFFFF)
        end
    elseif data.kind == 'upload_my_shop' then
        if type(mh_push_own_preset_shop) == 'function' then
            _G._mh_refresh_own_shop_and_push(false, true)
        end
    elseif data.kind == 'gps' and data.shop_num ~= nil and tostring(data.shop_num) ~= '' then
        local _shop_num = tostring(data.shop_num)
        sampSendChat('/findilavka ' .. _shop_num)
    elseif data.kind == 'set_tag' and data.item and data.item ~= '' then
        local _item_name = _mh_bridge_u8_to_cp(data.item)
        local _tag = data.tag
        if _tag == 'none' or _tag == '' or _tag == nil then _tag = nil end
        if _tag == 'watch' or _tag == 'fav' or _tag == 'skip' or _tag == nil then
            mh_set_item_tag(_item_name, _tag)
        end
    end
end
