function _mh_auto.build_spark(e)
    if not e or type(e.cp_hist) ~= 'table' or #e.cp_hist == 0 then return nil end
    local hist = e.cp_hist
    local from = math.max(1, #hist - _mh_auto.SPARK_MAX + 1)
    local spark = {}
    for i = from, #hist do
        local h = hist[i]
        if type(h) == 'table' and h.price then spark[#spark + 1] = h.price end
