function _mh_auto.get_filtered_sorted(search_u8, sort_mode)
    local search_cp = ''
    if search_u8 and search_u8 ~= '' then
        search_cp = (_mh_auto.u8_to_cp(search_u8) or ''):lower()
    end
    local ck = search_cp .. '|' .. tostring(sort_mode or 0)
    if _mh_auto.list_cache_k == ck then return _mh_auto.list_cache_l end
    local al = {}
    for nm, e in pairs(fh_mkt_auto) do
        if type(nm) == 'string' and type(e) == 'table' then
            if search_cp == '' or nm:lower():find(search_cp, 1, true) then
                if e.s_avg or e.cp_sp then table.insert(al, {nm = nm, e = e}) end
            end
        end
    end
    local sm = sort_mode or 0
    if sm == 0 then
        table.sort(al, function(a, b)
            local pa = (a.e.s_avg or a.e.cp_sp or 0); local pb = (b.e.s_avg or b.e.cp_sp or 0)
            if pa ~= pb then return pa > pb end; return tostring(a.nm) < tostring(b.nm)
        end)
    elseif sm == 1 then
        table.sort(al, function(a, b)
            local pa = (a.e.s_avg or a.e.cp_sp or 0); local pb = (b.e.s_avg or b.e.cp_sp or 0)
            if pa ~= pb then return pa < pb end; return tostring(a.nm) < tostring(b.nm)
        end)
    else
        table.sort(al, function(a, b) return tostring(a.nm) < tostring(b.nm) end)
    end
    _mh_auto.list_cache_k = ck
    _mh_auto.list_cache_l = al
    return al
end
