function _mh_auto_handle_query(data)
    if not (_mh_web_jar and _mh_auto.state.created and _mh_auto.state.loaded) then return end
    local req_id = tonumber(data.req_id) or 0
    local page = tonumber(data.page) or 1
    if page < 1 then page = 1 end
    local sort_mode = tonumber(data.sort) or 0
    local search_u8 = type(data.search) == 'string' and data.search or ''
    _mh_auto.last_q = { req_id = req_id, page = page, sort = sort_mode, search = search_u8 }
    local al = _mh_auto.get_filtered_sorted(search_u8, sort_mode)
    local total_count = #al
    local total_pages = math.max(1, math.ceil(total_count / _mh_auto.PAGE_SIZE))
    if page > total_pages then page = total_pages end
    local from = (page - 1) * _mh_auto.PAGE_SIZE + 1
    local to = math.min(page * _mh_auto.PAGE_SIZE, total_count)
    local items = {}
    for i = from, to do
        local row = al[i]
        if row then
            local e = row.e
            items[#items + 1] = {
                name  = _mh_auto.cp_to_u8(row.nm),
                price = e.s_avg or e.cp_sp,
                min   = e.s_min,
                max   = e.s_max,
                date  = e.date and _mh_auto.cp_to_u8(e.date) or nil,
                spark = _mh_auto.build_spark(e),
            }
        end
    end
    local resp = {
        req_id      = req_id,
        page        = page,
        total_pages = total_pages,
        total_count = total_count,
        items       = items,
    }
    local ok_j, j = pcall(encodeJson, resp)
    if not ok_j then return end
    local ok_b64, b64 = pcall(function() return require('basexx').to_base64(j) end)
    if not ok_b64 or not b64 then return end
    pcall(function()
        _mh_web_jar.executeJS(_mh_auto.bid, "window.mhReceiveAutoPage && window.mhReceiveAutoPage('" .. b64 .. "');")
    end)
end
function _mh_auto_respond(req_id, search_u8, sort_mode, page)
    pcall(_mh_auto_handle_query, {req_id = req_id, search = search_u8, sort = sort_mode, page = page})
end
function _mh_auto_refresh_web()
