end
if _mh_web_jar then
    local _mh_web_onAction_prev4 = _mh_web_jar.onAction
    function _mh_web_jar.onAction(data)
        if not data then return end                                                               
        if data.browserid == _mh_auto.bid then
            if data.type == "WV_STARTED" then
                _mh_auto.state.crashed = false
                _mh_auto.state.loaded = false
            elseif data.type == "WV_LOADED" then
                _mh_auto.state.loaded = true
                _mh_auto.apply_zoom()
                _mh_auto_respond(0, '', 0, 1)
            elseif data.type == "WV_PROGRESS" then
                local p = tonumber(data.msg)
                if p and p > _mh_auto.state.progress then _mh_auto.state.progress = p end
            elseif data.type == "WV_DIE" then
                _mh_auto.state.crashed = true
                _mh_auto.state.created = false
                pcall(function() _mh_web_jar.deleteBrowser(_mh_auto.bid) end)
            elseif data.type == "WV_ANSWER" then
                local _raw_msg = tostring(data.msg or '')
                local _prefix = 'MH_BRIDGE:'
                local _idx = _raw_msg:find(_prefix, 1, true)
                if _idx then
                    local _json_part = _raw_msg:sub(_idx + #_prefix)
                    local _ok_js, _js_obj = pcall(decodeJson, _json_part)
                    if _ok_js and type(_js_obj) == 'table' and _js_obj.kind then
                        if _js_obj.kind == 'auto_query' then
                            pcall(_mh_auto_handle_query, _js_obj)
                        else
                            pcall(_mh_shops_handle_bridge_payload, _js_obj)
                        end
                    end
                end
            end
            return
        end
        if _mh_web_onAction_prev4 then _mh_web_onAction_prev4(data) end
    end
end
