_mh_listings = _mh_listings or {}
function _mh_listings.my_nick()
    return _mh_get_live_nick()
end
function _mh_listings.post(path, body_tbl, callback)
    local _nck  = _mh_listings.my_nick()
    local _sess = _G._mh_session_tok or ''
    local ok_j, j = pcall(encodeJson, body_tbl or {})
    if not ok_j then
        if callback then callback(nil, 'json encode error') end
        return
    end
    if path:sub(1, 5) == '/api/' then path = path:sub(5) end
    local thread = effil.thread(_twd4k)(_vbr7n .. path, j, _nck, _nck, _sess)
    lua_thread.create(function()
        local _deadline = os.clock() + 20
        while true do
            wait(30)
            if os.clock() > _deadline then
                pcall(function() thread:cancel() end)
                if callback then callback(nil, 'timeout') end
                return
            end
            local status, err = thread:status()
            if not status or err then
                if callback then callback(nil, tostring(err or 'thread error')) end
                return
            end
            if status == 'completed' or status == 'canceled' then
                local ok2, resp = thread:get()
                if not ok2 or not resp then
                    if callback then callback(nil, tostring(resp or 'connection failed')) end
                    return
                end
                local code = resp.status_code
                local ok_d, parsed = pcall(decodeJson, resp.text or '')
                if code == 200 and ok_d and type(parsed) == 'table' then
                    if callback then callback(parsed, nil) end
                else
                    local _err
                    if ok_d and type(parsed) == 'table' and parsed.error then
                        _err = parsed.error
                    elseif code == 0 or code == nil then
                        _err = 'connection_error'
                    else
                        _err = 'http_' .. tostring(code)
                    end
                    if callback then callback(nil, tostring(_err)) end
                end
                return
            end
        end
    end)
end
