function _mh_catch_loot_record(text)
    if type(text) ~= 'string' or text == '' then return false end
    if not _G._mh_catch_ready then return false end
    local clean = text:gsub('{%x+}', '')
    local item = clean:match("Вам был добавлен предмет%s*:%s*'(.-)'%s*[%.!]?")
        or clean:match("Вам был добавлен предмет%s*'(.-)'%s*[%.!]?")
    if not item or item == '' then
        item = clean:match('Вам был добавлен предмет%s*:%s*"(.-)"%s*[%.!]?')
            or clean:match('Вам был добавлен предмет%s*"(.-)"%s*[%.!]?')
            or clean:match('Вам был добавлен предмет%s*:%s*[«](.-)[»]%s*[%.!]?')
            or clean:match('Вам был добавлен предмет%s*[«](.-)[»]%s*[%.!]?')
    end
    if not item or item == '' then return false end
    item = item:gsub('^%s+', ''):gsub('%s+$', '')
    if item == '' then return false end
    local qty = tonumber(clean:match("['\"][^'\"]+['\"]%s*[xх]%s*(%d+)"))
        or tonumber(clean:match('[xх]%s*(%d+)'))
        or tonumber(clean:match('%((%d+)%s*шт'))
        or 1
    if qty < 1 then qty = 1 end
    qty = math.floor(qty)
    local is_auto_capture = _G._ao_session_open
        or ((_G._mh_catch_loot_capture_until or 0) >= os.time())
    if is_auto_capture then
        local seq = tonumber(_G._mh_catch_open_seq) or 0
        _G._mh_catch_loot_seen = _G._mh_catch_loot_seen or {}
        _G._mh_catch_loot_seen[seq] = _G._mh_catch_loot_seen[seq] or {}
        local sig = item .. '\31' .. tostring(qty)
        if _G._mh_catch_loot_seen[seq][sig] then return false end
        _G._mh_catch_loot_seen[seq][sig] = true
    end
    if not is_auto_capture then
        _G._mh_catch_recent_loot = _G._mh_catch_recent_loot or {}
        local sig = item .. '\31' .. tostring(qty)
        local now = os.clock()
        local prev = _G._mh_catch_recent_loot[sig]
        if prev and (now - prev) < 0.8 then return false end
        _G._mh_catch_recent_loot[sig] = now
    end
    local day = os.date('%Y-%m-%d')
    local days = settings.catch_loot_log
    if type(days[day]) ~= 'table' then days[day] = {} end
    days[day][item] = (tonumber(days[day][item]) or 0) + qty
    if not is_auto_capture then
        local opens = settings.catch_open_log
        if type(opens[day]) ~= 'table' then opens[day] = {total = 0, boxes = {}} end
        opens[day].total = (tonumber(opens[day].total) or 0) + 1
    end
    pcall(_wfn7p)
    pcall(_G._mh_save_catch_now)
    pcall(_G._mh_catch_push)
    return true
end
_G._mh_catch_last_err = ''
_G._mh_catch_saves    = 0
function _G._mh_catch_dir()
    return getWorkingDirectory():gsub('\\', '/'):gsub('/$', '') .. '/MarketHelper'
end
function _G._mh_catch_path(name)
    return _G._mh_catch_dir() .. '/FH_' .. name
end
function _G._mh_catch_conv(t, fn, depth)
    if type(t) ~= 'table' or type(fn) ~= 'function' then return t end
    depth = depth or 0
    if depth > 6 then return t end
    local r = {}
    for k, v in pairs(t) do
        if type(k) == 'string' then k = fn(k) end
        if type(v) == 'table' then v = _G._mh_catch_conv(v, fn, depth + 1) end
        r[k] = v
    end
    return r
end
function _G._mh_catch_merge(a, b, depth)
    if type(a) ~= 'table' then a = {} end
    if type(b) ~= 'table' then return a end
    depth = depth or 0
    if depth > 6 then return a end
    for k, v in pairs(b) do
        local av = a[k]
        if av == nil then
            a[k] = v
        elseif type(av) == 'table' and type(v) == 'table' then
            _G._mh_catch_merge(av, v, depth + 1)
        elseif type(av) == 'number' and type(v) == 'number' and v > av then
            a[k] = v
        end
    end
    return a
end
function _G._mh_catch_pack(name, tbl)
    local is_open = name:find('open', 1, true) ~= nil
    local out = {__v = 2}
    for day, rec in pairs(tbl) do
        if type(day) == 'string' and day:match('^%d%d%d%d%-%d%d%-%d%d$') and type(rec) == 'table' then
            local o = {}
            if is_open then
                o.total = tonumber(rec.total) or 0
                o.boxes = {}
                if type(rec.boxes) == 'table' then
                    for bn, c in pairs(rec.boxes) do o.boxes['N' .. tostring(bn)] = tonumber(c) or 0 end
                end
            else
                for it, q in pairs(rec) do o['N' .. tostring(it)] = tonumber(q) or 0 end
            end
            out['D' .. day] = o
        end
    end
    return out
end
function _G._mh_catch_unpack(name, d, drop_num_keys)
    local is_open = name:find('open', 1, true) ~= nil
    local v2 = (d.__v == 2)
    local today = os.date('%Y-%m-%d')
    local out = {}
    local function nm(k)
        if type(k) == 'string' then
            if v2 then return (k:gsub('^N', '', 1)) end
            return k
        end
        return tostring(k)
    end
    for k, v in pairs(d) do
        local day
        if type(k) == 'string' then
            if v2 then day = k:match('^D(%d%d%d%d%-%d%d%-%d%d)$')
            else day = k:match('^(%d%d%d%d%-%d%d%-%d%d)$') end
        elseif type(k) == 'number' and not drop_num_keys and k >= 2000 and k < 2200 then
            day = today                                                                      
        end
        if day and type(v) == 'table' then
            local cur = out[day] or (is_open and {total = 0, boxes = {}} or {})
            if is_open then
                local t = tonumber(v.total) or 0
                if t > cur.total then cur.total = t end
                if type(v.boxes) == 'table' then
                    for bk, c in pairs(v.boxes) do
                        local n = nm(bk); c = tonumber(c) or 0
                        if c > (cur.boxes[n] or 0) then cur.boxes[n] = c end
                    end
                end
            else
                for ik, q in pairs(v) do
                    local n = nm(ik); q = tonumber(q) or 0
                    if q > (cur[n] or 0) then cur[n] = q end
                end
            end
            out[day] = cur
        end
    end
    return out
end
function _G._mh_catch_read(name)
    local path = _G._mh_catch_path(name)
    local f = io.open(path, 'rb')
    if not f then return nil, 'nofile' end
    local raw = f:read('*a'); f:close()
    if type(raw) ~= 'string' or raw:match('^%s*$') then return nil, 'empty' end
    local ok, d = pcall(decodeJson, raw)
    if ok and type(d) == 'table' then
        if d.__enc == 'u8' then
            d.__enc = nil
            d = _G._mh_catch_conv(d, _G._mh_bridge_u8_to_cp or _mh_bridge_u8_to_cp)
        end
        local ok2, r = pcall(_G._mh_catch_unpack, name, d)
        if ok2 and type(r) == 'table' then return r end
        _G._mh_catch_last_err = 'unpack: ' .. tostring(r)
    end
    local bf = io.open(path .. '.bad', 'wb')
    if bf then bf:write(raw); bf:close() end
    return nil, 'decode'
end
function _G._mh_catch_write(name, tbl)
    if type(tbl) ~= 'table' then return false end
    local path = _G._mh_catch_path(name)
    pcall(_mh_ensure_dir, _G._mh_catch_dir())
    local packed = _G._mh_catch_pack(name, tbl)
    local ok, j = pcall(encodeJson, packed)
    if not ok or type(j) ~= 'string' or j == '' then
        local first_err = tostring(j)
        local u = _G._mh_catch_conv(packed, _mh_bridge_cp_to_u8)
        if type(u) == 'table' then
            u.__enc = 'u8'
            local ok2, j2 = pcall(encodeJson, u)
            if ok2 and type(j2) == 'string' and j2 ~= '' then ok, j = true, j2 end
        end
        if not ok then
            _G._mh_catch_last_err = 'encode: ' .. first_err
            return false
        end
    end
    local f, ferr = io.open(path, 'wb')
    if not f then
        _G._mh_catch_last_err = 'open: ' .. tostring(ferr) .. ' | ' .. path
        return false
    end
    local wok, werr = f:write(j)
    f:close()
    if not wok then
        _G._mh_catch_last_err = 'write: ' .. tostring(werr)
        return false
    end
    _G._mh_catch_saves = (_G._mh_catch_saves or 0) + 1
    return true
end
function _G._mh_catch_init()
    local st = {}
    for _, p in ipairs({
        {'catch_loot_log.json', 'catch_loot_log'},
        {'catch_open_log.json', 'catch_open_log'},
    }) do
        local d, why = _G._mh_catch_read(p[1])
        local legacy = {}
        if type(settings[p[2]]) == 'table' then
            local okl, rl = pcall(_G._mh_catch_unpack, p[1], settings[p[2]], true)
            if okl and type(rl) == 'table' then legacy = rl end
        end
        if d then
            settings[p[2]] = _G._mh_catch_merge(d, legacy)
        else
            settings[p[2]] = legacy
            if why == 'decode' then
                _G._mh_catch_last_err = 'decode ' .. p[1] .. ' (kopiya: .bad)'
            end
        end
        st[#st + 1] = p[1] .. '=' .. tostring(why or 'ok')
    end
    _G._mh_catch_ready = true
    _G._mh_catch_init_state = table.concat(st, ', ')
    pcall(_G._mh_save_catch_now)
end
function _G._mh_catch_status()
    local nd, ni, no = 0, 0, 0
    if type(settings.catch_loot_log) == 'table' then
        for _, items in pairs(settings.catch_loot_log) do
            nd = nd + 1
            if type(items) == 'table' then for _ in pairs(items) do ni = ni + 1 end end
        end
    end
    if type(settings.catch_open_log) == 'table' then
        for _, rec in pairs(settings.catch_open_log) do
            if type(rec) == 'table' then no = no + (tonumber(rec.total) or 0) end
        end
    end
    local function fsize(name)
        local f = io.open(_G._mh_catch_path(name), 'rb')
        if not f then return -1 end
        local sz = f:seek('end') or 0; f:close(); return sz
    end
    local _extra = string.format(' | soobsh=%d zapisano=%d | tekst: %s', _G._mh_catch_seen_n or 0, _G._mh_catch_rec_n or 0, tostring(_G._mh_catch_last_text or '-'))
    return _extra .. string.format(' || ready=%s | dney=%d predm.=%d otkryto=%d | fajly: loot=%db open=%db | zapisej=%d | start: %s | oshibka: %s',
        tostring(_G._mh_catch_ready), nd, ni, no,
        fsize('catch_loot_log.json'), fsize('catch_open_log.json'),
        _G._mh_catch_saves or 0, tostring(_G._mh_catch_init_state or '?'),
        (_G._mh_catch_last_err ~= '' and _G._mh_catch_last_err or 'net'))
end
_G._mh_catch_init()
function _mh_catch_loot_query(day_filter)
    local days = type(settings.catch_loot_log) == 'table' and settings.catch_loot_log or {}
    local open_days = type(settings.catch_open_log) == 'table' and settings.catch_open_log or {}
    local now = os.time()
    local out_days = {}
    local total_qty, total_types, total_opened = 0, 0, 0
    local seen_types = {}
    local day_keys = {}
    local merged = {}
    for day, items in pairs(days) do
        if type(day) == 'string' and day:match('^%d%d%d%d%-%d%d%-%d%d$') and type(items) == 'table' then
            merged[day] = merged[day] or {}
            for name, qty in pairs(items) do
                if type(name) == 'string' then
                    merged[day][name] = tonumber(qty) or 0
                end
            end
        end
    end
    for day, rec in pairs(open_days) do
        if type(day) == 'string' and day:match('^%d%d%d%d%-%d%d%-%d%d$') and type(rec) == 'table' then
            merged[day] = merged[day] or {}
        end
    end
    for day in pairs(merged) do
        if type(day) == 'string' then table.insert(day_keys, day) end
    end
    table.sort(day_keys, function(a,b) return a > b end)
    local function include_day(day)
        local y,m,d = day:match('^(%d%d%d%d)%-(%d%d)%-(%d%d)$')
        if not y then return false, nil end
        local ts = os.time({year=tonumber(y),month=tonumber(m),day=tonumber(d),hour=12,min=0,sec=0})
        local age = math.floor((os.time({year=tonumber(os.date('%Y', now)),month=tonumber(os.date('%m', now)),day=tonumber(os.date('%d', now)),hour=12,min=0,sec=0}) - ts) / 86400 + 0.5)
        if day_filter == 1 then return day == os.date('%Y-%m-%d', now), {y=y,m=m,d=d} end
        if day_filter == 2 then return age >= 0 and age < 7, {y=y,m=m,d=d} end
        if day_filter == 3 then return age >= 0 and age < 30, {y=y,m=m,d=d} end
        return true, {y=y,m=m,d=d}
    end
    for _, day in ipairs(day_keys) do
        local include, parts = include_day(day)
        if include and parts then
            local items = days[day] or {}
            local arr, day_qty = {}, 0
            for name, qty in pairs(items) do
                qty = tonumber(qty) or 0
                if qty > 0 then
                    table.insert(arr, {name=_mh_bridge_cp_to_u8(name), qty=qty})
                    day_qty = day_qty + qty
                    total_qty = total_qty + qty
                    if not seen_types[name] then
                        seen_types[name] = true
                        total_types = total_types + 1
                    end
                end
            end
            table.sort(arr, function(a,b) return a.qty > b.qty or (a.qty == b.qty and a.name < b.name) end)
            local op = open_days[day]
            local opened = type(op) == 'table' and (tonumber(op.total) or 0) or 0
            total_opened = total_opened + opened
            local boxes = {}
            if type(op) == 'table' and type(op.boxes) == 'table' then
                for box, count in pairs(op.boxes) do
                    count = tonumber(count) or 0
                    if count > 0 then table.insert(boxes, {name=_mh_bridge_cp_to_u8(box), qty=count}) end
                end
            end
            table.sort(boxes, function(a,b) return a.qty > b.qty or (a.qty == b.qty and a.name < b.name) end)
            if opened > 0 or #arr > 0 then
                table.insert(out_days, {
                    date=day,
                    label=string.format('%02d.%02d.%04d', tonumber(parts.d), tonumber(parts.m), tonumber(parts.y)),
                    opened=opened,
                    total=day_qty,
                    boxes=boxes,
                    items=arr,
                })
            end
        end
    end
    return out_days, total_qty, total_types, total_opened
end
function _mh_catch.build_state()
    local _is_prem = _mh_is_premium()
    _mh_flog('[catch] build_state: premium=' .. tostring(_is_prem))
    local _boxes, _box_count = {}, 0
    for _, it in ipairs(fh_lv_inventory or {}) do
        if _mh_catch_is_box_name(it.name) then
            _box_count = _box_count + 1
            local _slot_idx = -1
            if it.stacks and it.stacks[1] then _slot_idx = it.stacks[1].slot end
            table.insert(_boxes, {
                name  = _mh_catch.cp_to_u8(it.name),
                count = it.count or 0,
                slot  = _slot_idx,
            })
        end
    end
    local _slot_out = nil
    if _G._ao_slots and _G._ao_slots[1] then
        local _s = _G._ao_slots[1]
        _slot_out = {
            name       = _mh_catch.cp_to_u8(_s.name or ''),
            max_count  = _s.max_count or 0,
            interval   = _s.interval or 1.0,
            done       = _s.done or 0,
            running    = _s.running and true or false,
            status     = _mh_catch.cp_to_u8(_s.status or ''),
            delete_on_sold = _s.delete_on_sold and true or false,
        }
    end
    local _tap_out = nil
    if _is_prem then
        local _tap = settings.trade_autoprice or {}
        _tap_out = { enabled = _tap.enabled and true or false, pct = _tap.pct or 65 }
    end
    return {
        kind             = 'state',
        premium          = _is_prem,
        radius_enabled   = cm_radius_enabled and true or false,
        radius_draw_dist = cm_radius_draw_dist or 20,
        render_enabled   = cm_render_enabled and true or false,
        storage_enabled  = (settings.general and settings.general.auto_storage_collect) and true or false,
        inv_scanning     = fh_lv_inv_scanning and true or false,
        boxes            = _boxes,
        box_count        = _box_count,
        slot             = _slot_out,
        autoprice        = _tap_out,
    }
end
function _mh_catch.u8_to_cp(s)
    if type(s) ~= 'string' or s == '' then return s end
    local ok, r = pcall(function()
        return require('encoding').CP1251:encode(require('encoding').UTF8:decode(s))
    end)
    return (ok and r) and r or s
end
function _mh_catch.cp_to_u8(s)
    if type(s) ~= 'string' or s == '' then return s end
    local ok, r = pcall(function()
        return require('encoding').UTF8:encode(require('encoding').CP1251:decode(s))
    end)
    return (ok and r) and r or s
end
function _mh_catch.push_state()
    if not (_mh_web_jar and _mh_catch.state.created) then
        _mh_flog('[catch] push_state: guard fail, jar=' .. tostring(_mh_web_jar ~= nil) .. ' created=' .. tostring(_mh_catch.state.created))
        return
    end
    _mh_catch.state.push_seq = (_mh_catch.state.push_seq or 0) + 1
    local _my_seq = _mh_catch.state.push_seq
    _mh_flog('[catch] push_state: queued seq=' .. tostring(_my_seq))
    lua_thread.create(function()
        wait(0)
        local ok_j, j = pcall(encodeJson, _mh_catch.build_state())
        if not ok_j or type(j) ~= 'string' then
            _mh_flog('[catch] push_state seq=' .. tostring(_my_seq) .. ': encodeJson FAILED, ok=' .. tostring(ok_j) .. ' err=' .. tostring(j))
            return
        end
        local ok_b64, b64 = pcall(function() return require('basexx').to_base64(j) end)
        if not ok_b64 or not b64 then
            _mh_flog('[catch] push_state seq=' .. tostring(_my_seq) .. ': base64 FAILED, ok=' .. tostring(ok_b64))
            return
        end
        if _mh_catch.state.push_seq ~= _my_seq then
            _mh_flog('[catch] push_state seq=' .. tostring(_my_seq) .. ': stale, current=' .. tostring(_mh_catch.state.push_seq) .. ' -- dropped')
            return
        end
        local ok_exec, exec_err = pcall(function()
            _mh_web_jar.executeJS(_mh_catch.bid, "window.mhReceiveState && window.mhReceiveState('" .. b64 .. "');")
        end)
        _mh_flog('[catch] push_state seq=' .. tostring(_my_seq) .. ': executeJS ok=' .. tostring(ok_exec) .. ' err=' .. tostring(exec_err) .. ' json_len=' .. tostring(#j))
    end)
end
function _mh_catch.handle_bridge_payload(data)
    if type(data) ~= 'table' or not data.kind then return end
    _mh_flog('[catch] handle_bridge_payload: kind=' .. tostring(data.kind))
    if data.kind == 'ready' then
        pcall(_mh_catch.push_state)
        return
    end
    if data.kind == 'catch_toggle_radius' then
        cm_radius_enabled = data.value and true or false
    elseif data.kind == 'catch_set_radius_dist' then
        local v = tonumber(data.value) or 20
        if v < 10 then v = 10 end
        if v > 20 then v = 20 end
        cm_radius_draw_dist = v
    elseif data.kind == 'catch_toggle_render' then
        cm_render_enabled = data.value and true or false
    elseif data.kind == 'catch_toggle_storage' then
        if not settings.general then settings.general = {} end
        settings.general.auto_storage_collect = data.value and true or false
    elseif data.kind == 'catch_scan_inventory' then
        if not fh_lv_inv_scanning then
            _vcz9h()
            pcall(_mh_catch.push_state)
            lua_thread.create(function()
                wait(200)
                _yzr1t(52, -1, 2, '{"slot":0,"type":1}')
            end)
        end
    elseif data.kind == 'catch_open_start' then
        if not _mh_is_premium() then return end
        local _nm = _mh_catch.u8_to_cp(data.name or '')
        if _nm == '' then return end
        local _slot_idx = -1
        local _item_id = nil
        for _, it in ipairs(fh_lv_inventory or {}) do
            if it.name == _nm then
                if it.stacks and it.stacks[1] then _slot_idx = it.stacks[1].slot end
                if mh_arz_items_db then
                    for _iid, _inm in pairs(mh_arz_items_db) do
                        if _inm == it.name then _item_id = _iid; break end
                    end
                end
                break
            end
        end
        if _slot_idx < 0 then
            _mh_catch.push_state()
            return
        end
        if not _G._ao_slots then _G._ao_slots = {} end
        local _max = tonumber(data.max_count) or 0
        if _max < 0 then _max = 0 end
        local _interval = tonumber(data.interval) or 1.0
        if _interval < 0.1 then _interval = 0.1 end
        if _interval > 300 then _interval = 300 end
        _G._ao_slots[1] = {
            name      = _nm,
            slot_idx  = _slot_idx,
            item_id   = _item_id,
            interval  = _interval,
            max_count = _max,
            done      = 0,
            running   = true,
            status    = 'Запуск...',
            delete_on_sold = data.delete_on_sold and true or false,
        }
        mh_notify('[MH] {00cc00}Открытие (сайт): ' .. _nm ..
            ' | каждые ' .. _interval .. 'с' ..
            (_max > 0 and (' | макс ' .. _max) or ''), 0xFFFFFF)
        lua_thread.create(function()
            local _s = _G._ao_slots[1]
            while _s.running do
                if _s.max_count > 0 and _s.done >= _s.max_count then
                    _s.running = false
                    _G._ao_session_open = false
                    _s.status = 'Готово! ' .. _s.done .. '/' .. _s.max_count
                    mh_notify('[MH] {00cc00}Открытие готово: ' .. _s.done .. ' шт', 0xFFFFFF)
                    if _s.delete_on_sold then
                        _s.name = ''; _s.slot_idx = -1
                        _s.max_count = 0; _s.done = 0
                        _s.status = ''; _s.delete_on_sold = false
                    end
                    _mh_catch.push_state()
                    break
                end
                local _real_slot = nil
                if _s.item_id and _G._ao_item_to_slot then
                    _real_slot = _G._ao_item_to_slot[_s.item_id]
                end
                if not _real_slot then
                    for _, ie2 in ipairs(fh_lv_inventory) do
                        if ie2.name == _s.name then
                            if ie2.stacks and ie2.stacks[1] then
                                _s.slot_idx = ie2.stacks[1].slot
                                _real_slot  = _s.slot_idx
                            end
                            break
                        end
                    end
                end
                if not _real_slot or _real_slot < 0 then
                    _s.status = 'Нет в инвентаре!'
                    _mh_catch.push_state()
                    wait(2000)
                else
                    if not _G._ao_session_open then
                        _yzr1t(52, -1, 0, '""')
                        wait(300)
                        _G._ao_session_open = true
                    end
                    _G._mh_catch_open_seq = (tonumber(_G._mh_catch_open_seq) or 0) + 1
                    _mh_catch_open_record(_s.name)
                    _G._mh_catch_loot_capture_until = os.time() + 15
                    _yzr1t(52, -1, 2, '{"slot":' .. _real_slot .. ',"type":1}')
                    wait(150)
                    _yzr1t(52, -1, 3, '{"action":1,"id":0,"slot":' .. _real_slot .. ',"type":1}')
                    wait(400)
                    _s.done = _s.done + 1
                    _s.status = 'Открыто: ' .. _s.done .. (_s.max_count > 0 and ('/' .. _s.max_count) or '')
                    _mh_catch.push_state()
                end
                local _ms, _el, _last_rem = math.floor(_s.interval * 1000), 0, nil
                while _el < _ms and _s.running do
                    wait(100); _el = _el + 100
                    local _rem = math.ceil((_ms - _el) / 1000)
                    if _rem > 0 and _rem ~= _last_rem then
                        _last_rem = _rem
                        _s.status = 'След. через ' .. _rem .. 'с | открыто: ' .. _s.done
                        _mh_catch.push_state()
                    end
                end
            end
        end)
    elseif data.kind == 'catch_open_stop' then
        if _G._ao_slots and _G._ao_slots[1] then
            local _s = _G._ao_slots[1]
            _s.running = false
            _s.status  = 'Стоп (' .. (_s.done or 0) .. ')'
            _G._ao_session_open = false
            mh_notify('[MH] {ff8800}Открытие остановлено (сайт). Открыто: ' .. (_s.done or 0), 0xFFFFFF)
        end
    elseif data.kind == 'catch_autoprice_set' then
        if not _mh_is_premium() then
            _mh_catch.push_state()
            return
        end
        if not settings.trade_autoprice then settings.trade_autoprice = {} end
        if data.key == 'enabled' then
            settings.trade_autoprice.enabled = data.value and true or false
        elseif data.key == 'pct' then
            local v = tonumber(data.value) or 65
            if v < 10 then v = 10 end
            if v > 100 then v = 100 end
            settings.trade_autoprice.pct = v
        end
    elseif data.kind == 'set_tag' then
        pcall(_mh_shops_handle_bridge_payload, data)
        return
    else
        return
    end
    pcall(_wfn7p)
    pcall(_mh_catch.push_state)
end
if _mh_web_jar then
    local _mh_catch_onAction_prev = _mh_web_jar.onAction
    function _mh_web_jar.onAction(data)
        if not data then return end                                                               
        if data.browserid == _mh_catch.bid then
            if data.type == "WV_STARTED" then
                _mh_catch.state.crashed = false
                _mh_catch.state.loaded = false
            elseif data.type == "WV_LOADED" then
                _mh_flog('[catch] onAction: WV_LOADED')
                _mh_catch.state.loaded = true
                _mh_catch.apply_zoom()
                _mh_catch.push_state()
                lua_thread.create(function()
                    local _deadline = os.clock() + 12
                    while _mh_catch.state.loaded and _mh_catch.state.created do
                        wait(500)
                        if not (_mh_catch.state.loaded and _mh_catch.state.created) then break end
                        pcall(_mh_catch.push_state)
                        if _mh_is_premium() then break end
                        if os.clock() > _deadline then break end
                    end
                end)
            elseif data.type == "WV_PROGRESS" then
                local p = tonumber(data.msg)
                if p and p > _mh_catch.state.progress then _mh_catch.state.progress = p end
            elseif data.type == "WV_DIE" then
                _mh_flog('[catch] onAction: WV_DIE (crash)')
                _mh_catch.state.crashed = true
                _mh_catch.state.created = false
                pcall(function() _mh_web_jar.deleteBrowser(_mh_catch.bid) end)
            elseif data.type == "WV_ANSWER" then
                local _raw_msg = tostring(data.msg or '')
                local _prefix = 'MH_BRIDGE:'
                local _idx = _raw_msg:find(_prefix, 1, true)
                if _idx then
                    local _json_part = _raw_msg:sub(_idx + #_prefix)
                    local _ok_js, _js_obj = pcall(decodeJson, _json_part)
                    if _ok_js and type(_js_obj) == 'table' and _js_obj.kind then
                        pcall(_mh_catch.handle_bridge_payload, _js_obj)
                    else
                        _mh_flog('[catch] onAction: WV_ANSWER decodeJson FAILED ok=' .. tostring(_ok_js) .. ' raw=' .. _json_part:sub(1, 200))
                    end
                else
                    _mh_flog('[catch] onAction: WV_ANSWER (no MH_BRIDGE prefix) raw=' .. _raw_msg:sub(1, 200))
                end
            end
            return
        end
        if _mh_catch_onAction_prev then _mh_catch_onAction_prev(data) end
    end
end
function _mh_catch_hide()
