function _mh_piar.u8_to_cp(s)
    if type(s) ~= 'string' or s == '' then return s end
    local ok, r = pcall(function()
        return require('encoding').CP1251:encode(require('encoding').UTF8:decode(s))
    end)
    return (ok and r) and r or s
end
function _mh_piar.cp_to_u8(s)
    if type(s) ~= 'string' or s == '' then return s end
