function _mh_piar.build_state()
    local _templates = {}
    for i, t in ipairs(settings.piar_templates or {}) do
        local _lines = {}
        for li, ln in ipairs(t.lines or {}) do
            _lines[li] = _mh_piar.cp_to_u8(ln)
        end
        local _queue_left, _queue_total = nil, nil
        if t.auto then
            local _iv = t.auto_interval or 300
            if (t.auto_interval_max or 0) > _iv then
                _iv = t._next_interval or _iv
            end
            _queue_total = _iv
            _queue_left = math.max(0, _iv - (os.time() - (t.last_time or 0)))
        end
        _templates[i] = {
            name              = _mh_piar.cp_to_u8(t.name) or '',
            enable            = (t.enable ~= false),
            auto              = t.auto and true or false,
            waiting           = t.waiting or 1.5,
            auto_interval     = t.auto_interval or 300,
            auto_interval_max = t.auto_interval_max or 0,
            auto_limit        = t.auto_limit or 0,
            auto_count        = t.auto_count or 0,
            random_line       = t.random_line and true or false,
            lines             = _lines,
            queue_left        = _queue_left,
            queue_total       = _queue_total,
        }
    end
    return {
        kind             = 'state',
        templates        = _templates,
        own_shop_num     = mh_own_shop_num or (settings.general and settings.general.own_shop_num_saved),
        auto_ad_confirm  = settings.general and settings.general.auto_ad_confirm and true or false,
        auto_ad_station  = settings.general and settings.general.auto_ad_station_idx or 2,
        auto_ad_type     = settings.general and settings.general.auto_ad_type or 0,
    }
end
function _mh_piar.push_state()
    if not (_mh_web_jar and _mh_piar.state.created) then return end
    _mh_piar.state.push_seq = (_mh_piar.state.push_seq or 0) + 1
    local _my_seq = _mh_piar.state.push_seq
    lua_thread.create(function()
        wait(0)
        local ok_j, j = pcall(encodeJson, _mh_piar.build_state())
        if not ok_j or type(j) ~= 'string' then return end
        local ok_b64, b64 = pcall(function() return require('basexx').to_base64(j) end)
        if not ok_b64 or not b64 then return end
        if _mh_piar.state.push_seq ~= _my_seq then return end                                          
        pcall(function()
            _mh_web_jar.executeJS(_mh_piar.bid, "window.mhReceiveState && window.mhReceiveState('" .. b64 .. "');")
        end)
    end)
end
function _mh_piar.handle_bridge_payload(data)
    if type(data) ~= 'table' or not data.kind then return end
    if data.kind == 'ready' then
        pcall(_mh_piar.push_state)
        return
    end
    local _changed = true
    if data.kind == 'piar_run' and data.index then
        local _idx = tonumber(data.index)
        if _idx and settings.piar_templates[_idx] then
            _xjg7y(_idx)
        end
        _changed = false
    elseif data.kind == 'piar_auto_toggle' and data.index then
        local _idx = tonumber(data.index)
        local _t = _idx and settings.piar_templates[_idx]
        if _t then
            _t.auto = data.enable and true or false
            if _t.auto then
                _t.auto_count = 0
                _t.last_time = os.time()
                _t._next_interval = nil
            end
        else
            _changed = false
        end
    elseif data.kind == 'piar_enable_toggle' and data.index then
        local _idx = tonumber(data.index)
        local _t = _idx and settings.piar_templates[_idx]
        if _t then
            _t.enable = data.enable and true or false
        else
            _changed = false
        end
    elseif data.kind == 'piar_create' then
        if not settings.piar_templates then settings.piar_templates = {} end
        table.insert(settings.piar_templates, {
            name = '\xcd\xee\xe2\xfb\xe9', enable = true, auto = false,
            auto_interval = 300, auto_interval_max = 0, auto_limit = 0, auto_count = 0,
            waiting = 1.5, last_time = 0, lines = {'/s \xd2\xe5\xea\xf1\xf2'},
        })
    elseif data.kind == 'piar_delete' and data.index then
        local _idx = tonumber(data.index)
        if _idx and settings.piar_templates[_idx] then
            table.remove(settings.piar_templates, _idx)
        else
            _changed = false
        end
    elseif data.kind == 'piar_update' and data.index then
        local _idx = tonumber(data.index)
        local _t = _idx and settings.piar_templates[_idx]
        if _t then
            if data.name ~= nil and data.name ~= '' then _t.name = _mh_piar.u8_to_cp(data.name) end
            if data.waiting ~= nil then
                local _w = tonumber(data.waiting)
                if _w then _t.waiting = math.max(0.5, math.min(10, _w)) end
            end
            if data.auto_interval ~= nil then
                local _v = tonumber(data.auto_interval)
                if _v then
                    _t.auto_interval = math.max(30, math.min(3600, _v))
                    if (_t.auto_interval_max or 0) < _t.auto_interval then _t.auto_interval_max = _t.auto_interval end
                    _t._next_interval = nil
                end
            end
            if data.auto_interval_max ~= nil then
                local _v = tonumber(data.auto_interval_max)
                if _v then _t.auto_interval_max = math.max(0, math.min(3600, _v)); _t._next_interval = nil end
            end
            if data.auto_limit ~= nil then
                local _v = tonumber(data.auto_limit)
                if _v then _t.auto_limit = math.max(0, math.min(100, _v)); _t.auto_count = 0 end
            end
            if data.random_line ~= nil then _t.random_line = data.random_line and true or false end
        else
            _changed = false
        end
    elseif data.kind == 'piar_line_add' and data.index then
        local _idx = tonumber(data.index)
        local _t = _idx and settings.piar_templates[_idx]
        if _t then
            if not _t.lines then _t.lines = {} end
            table.insert(_t.lines, '/s \xd2\xe5\xea\xf1\xf2')
        else
            _changed = false
        end
    elseif data.kind == 'piar_line_update' and data.index and data.line_index and data.text ~= nil then
        local _idx, _li = tonumber(data.index), tonumber(data.line_index)
        local _t = _idx and settings.piar_templates[_idx]
        if _t and _t.lines and _t.lines[_li] then
            _t.lines[_li] = _mh_piar.u8_to_cp(data.text)
        else
            _changed = false
        end
    elseif data.kind == 'piar_line_remove' and data.index and data.line_index then
        local _idx, _li = tonumber(data.index), tonumber(data.line_index)
        local _t = _idx and settings.piar_templates[_idx]
        if _t and _t.lines and _t.lines[_li] then
            table.remove(_t.lines, _li)
        else
            _changed = false
        end
    elseif data.kind == 'piar_line_add_lavka' and data.index then
        local _idx = tonumber(data.index)
        local _t = _idx and settings.piar_templates[_idx]
        if _t then
            if not _t.lines then _t.lines = {} end
            if #_t.lines == 0 then
                table.insert(_t.lines, '/s <lavka>')
            else
                local _last = _t.lines[#_t.lines]
                if not _last:find('<lavka>', 1, true) then
                    _t.lines[#_t.lines] = _last .. ' <lavka>'
                end
            end
        else
            _changed = false
        end
    elseif data.kind == 'piar_ad_confirm_toggle' then
        if settings.general then settings.general.auto_ad_confirm = data.enable and true or false
        else _changed = false end
    elseif data.kind == 'piar_ad_station' and data.idx ~= nil then
        local _v = tonumber(data.idx)
        if settings.general and _v and _v >= 0 and _v <= 2 then settings.general.auto_ad_station_idx = _v
        else _changed = false end
    elseif data.kind == 'piar_ad_type' and data.idx ~= nil then
        local _v = tonumber(data.idx)
        if settings.general and _v and (_v == 0 or _v == 1) then settings.general.auto_ad_type = _v
        else _changed = false end
    elseif data.kind == 'piar_editor_open' then
        _G._mh_piar_editor_expand = false
        _G._mh_piar_editor_restore = false
        _changed = false
    elseif data.kind == 'piar_editor_close' then
        _G._mh_piar_editor_expand = false
        _G._mh_piar_editor_restore = false
        _changed = false
    else
        _changed = false
    end
    if _changed then
        lua_thread.create(function()
            wait(0)
            pcall(_wfn7p)
        end)
        pcall(_mh_piar.push_state)
        lua_thread.create(function()
            wait(250)
            pcall(_mh_piar.push_state)
        end)
    end
end
if _mh_web_jar then
    local _mh_piar_onAction_prev = _mh_web_jar.onAction
    function _mh_web_jar.onAction(data)
        if not data then return end                                                               
        if data.browserid == _mh_piar.bid then
            if data.type == "WV_STARTED" then
                _mh_piar.state.crashed = false
                _mh_piar.state.loaded = false
            elseif data.type == "WV_LOADED" then
                _mh_piar.state.loaded = true
                _mh_piar.apply_zoom()
                _mh_piar.push_state()
            elseif data.type == "WV_PROGRESS" then
                local p = tonumber(data.msg)
                if p and p > _mh_piar.state.progress then _mh_piar.state.progress = p end
            elseif data.type == "WV_DIE" then
                _mh_piar.state.crashed = true
                _mh_piar.state.created = false
                pcall(function() _mh_web_jar.deleteBrowser(_mh_piar.bid) end)
            elseif data.type == "WV_ANSWER" then
                local _raw_msg = tostring(data.msg or '')
                local _prefix = 'MH_BRIDGE:'
                local _idx = _raw_msg:find(_prefix, 1, true)
                if _idx then
                    local _json_part = _raw_msg:sub(_idx + #_prefix)
                    local _ok_js, _js_obj = pcall(decodeJson, _json_part)
                    if _ok_js and type(_js_obj) == 'table' and _js_obj.kind then
                        pcall(_mh_piar.handle_bridge_payload, _js_obj)
                    end
                end
            end
            return
        end
        if _mh_piar_onAction_prev then _mh_piar_onAction_prev(data) end
    end
end
function _mh_piar_hide()
    if _mh_web_jar and _mh_piar.state.created then
        pcall(function()
            _mh_web_jar.setClickable(_mh_piar.bid, false)
            _mh_web_jar.setVisible(_mh_piar.bid, false)
            _mh_web_jar.deleteBrowser(_mh_piar.bid)
        end)
        _mh_piar.state.created         = false
        _mh_piar.state.loaded          = false
        _mh_piar.state.crashed         = false
        _mh_piar.state.progress        = 0
        _mh_piar.state.visible_applied = false
        _mh_piar.state.pos = {x = -99999, y = -99999, w = 0, h = 0}
    end
end
