function _mh_piar_tab_render()
    local d = settings.general.custom_dpi or 1
    if not _mh_web_jar then
        imgui.Spacing()
        imgui.TextColored(imgui.ImVec4(1, 0.35, 0.35, 1), u8'\xc1\xe8\xe1\xeb\xe8\xee\xf2\xe5\xea\xe0\x20\x77\x65\x62\x76\x69\x65\x77\x73\x20\xed\xe5\x20\xed\xe0\xe9\xe4\xe5\xed\xe0\x2e')
        imgui.TextWrapped(u8'\xd3\xf1\xf2\xe0\xed\xee\xe2\xe8\xf2\xe5\x20\xe1\xe8\xe1\xeb\xe8\xee\xf2\xe5\xea\xf3\x20\x77\x65\x62\x76\x69\x65\x77\x73\x20\x28\xf2\xe0\x20\xe6\xe5\x2c\x20\xf7\xf2\xee\x20\xe8\xf1\xef\xee\xeb\xfc\xe7\xf3\xe5\xf2\xf1\xff\x20\xe2\x20\x57\x65\x62\x4d\x6f\x62\x69\x6c\x65\x29\x2c\x20\xf7\xf2\xee\xe1\xfb\x20\xf1\xf2\xf0\xe0\xed\xe8\xf6\xe0\x20\xf1\xe0\xe9\xf2\xe0\x20\xf0\xe0\xe1\xee\xf2\xe0\xeb\xe0\x2e')
        return
    end
    if not _mh_piar.state.created then
        local ok = pcall(function() _mh_web_jar.createBrowser(_mh_piar.bid, _mh_piar.build_url()) end)
        if ok then
            _mh_piar.state.created  = true
            _mh_piar.state.loaded   = false
            _mh_piar.state.crashed  = false
            _mh_piar.state.progress = 0
            _mh_piar.state.visible_applied = false
        end
    end
    if _mh_piar.state.created then
        if not _mh_piar.state.visible_applied then
            pcall(function()
                _mh_web_jar.setClickable(_mh_piar.bid, true)
                _mh_web_jar.setVisible(_mh_piar.bid, true)
            end)
            _mh_piar.state.visible_applied = true
        end
    end
    imgui.Text(fa.TOWER_BROADCAST .. ' ' .. u8'\xcf\xc8\xc0\xd0')
    imgui.SameLine(imgui.GetWindowContentRegionWidth() - 154*d)
    if imgui.Button(fa.MAGNIFYING_GLASS_MINUS .. '##mh_piar_zoom_out', imgui.ImVec2(30*d, 0)) then
        _mh_piar.set_zoom(settings.mh_web.piar_zoom - 0.1)
    end
    imgui.SameLine()
    imgui.Text(math.floor(settings.mh_web.piar_zoom * 100) .. '%%')
    imgui.SameLine()
    if imgui.Button(fa.MAGNIFYING_GLASS_PLUS .. '##mh_piar_zoom_in', imgui.ImVec2(30*d, 0)) then
        _mh_piar.set_zoom(settings.mh_web.piar_zoom + 0.1)
    end
    imgui.SameLine()
    if imgui.Button(fa.ROTATE_RIGHT .. '##mh_piar_reload') and _mh_web_jar then
        _mh_piar.state.loaded = false
        _mh_piar.state.progress = 0
        pcall(function() _mh_web_jar.changeUrl(_mh_piar.bid, _mh_piar.build_url()) end)
    end
    imgui.Separator()
    local _wp, _cp2 = imgui.GetWindowPos(), imgui.GetCursorPos()
    local _avail = imgui.GetContentRegionAvail()
    local _px, _py = _wp.x + _cp2.x, _wp.y + _cp2.y
    local _pw, _ph = _avail.x, _avail.y
    if _mh_piar.state.created and _mh_web_jar then
        local _pos = _mh_piar.state.pos
        if _pos.x ~= _px or _pos.y ~= _py then
            pcall(function() _mh_web_jar.setPos(_mh_piar.bid, _px, _py) end)
        end
        if _pos.w ~= _pw or _pos.h ~= _ph then
            pcall(function() _mh_web_jar.setSize(_mh_piar.bid, _pw, _ph) end)
        end
        _mh_piar.state.pos = {x = _px, y = _py, w = _pw, h = _ph}
    end
    if _mh_piar.state.crashed then
        imgui.SetCursorPos(imgui.ImVec2(_cp2.x, _cp2.y + _ph/2 - 10))
        _mh_web_center_text(u8'\xd1\xf2\xf0\xe0\xed\xe8\xf6\xe0\x20\xef\xf0\xe8\xeb\xee\xe6\xe5\xed\xe8\xff\x20\xef\xe5\xf0\xe5\xf0\xe2\xe0\xeb\xe0\xf1\xfc\x20\x28\x63\x72\x61\x73\x68\x29\x20\x3a\x28')
        imgui.SetCursorPos(imgui.ImVec2(_cp2.x, _cp2.y + _ph/2 + 12))
        if imgui.Button(fa.ROTATE_RIGHT .. ' ' .. u8'\xcf\xe5\xf0\xe5\xe7\xe0\xef\xf3\xf1\xf2\xe8\xf2\xfc\x23\x23\x6d\x68\x5f\x70\x69\x61\x72\x5f\x72\x65\x74\x72\x79', imgui.ImVec2(160*d, 0)) then
            _mh_piar.state.created = false
        end
    elseif not _mh_piar.state.loaded then
        imgui.SetCursorPos(imgui.ImVec2(_cp2.x, _cp2.y + _ph/2 - 10))
        local _pct = _mh_piar.state.progress
        if type(_pct) == "number" and _pct > 0 and _pct < 100 then
            _mh_web_center_text(u8'\xc7\xe0\xe3\xf0\xf3\xe7\xea\xe0\x20\xf1\xe0\xe9\xf2\xe0\x2e\x2e\x2e\x20' .. _pct .. '%%')
        else
            _mh_web_center_text(u8'\xc7\xe0\xe3\xf0\xf3\xe7\xea\xe0\x20\xf1\xe0\xe9\xf2\xe0\x2e\x2e\x2e')
        end
    end
    imgui.Dummy(imgui.ImVec2(_pw, _ph))
end
