function _mh_buy.item_prices(nm)
    local _cur_ver = tostring(_G._mh_db_ver or 0)..'|'..tostring(_G._mh_shop_ver or 0)
        ..'|'..tostring(_G._mh_deals_cache_ver or 0)..'|'..tostring(_G._mh_daily_cache_ver or 0)
    if not _G._mh_buy_ip_cache or _G._mh_buy_ip_cache_ver ~= _cur_ver then
        _G._mh_buy_ip_cache = {}
        _G._mh_buy_ip_cache_ver = _cur_ver
    end
    local _hit = _G._mh_buy_ip_cache[nm]
    if _hit then return _hit end
    local _mp = _mh_get_mkt_price(nm)
    local _avg7, _avg30, _today
    if _mp then
        _avg7  = (_mp.avg7  and _mp.avg7  > 0) and _mp.avg7  or nil
        _avg30 = (_mp.avg30 and _mp.avg30 > 0) and _mp.avg30 or nil
        if _avg7 and _avg30 then _today = math.min(_avg7, _avg30)
        else _today = _avg7 or _avg30 end
    end
    local _today_cp = (_mp and _mp.today and _mp.today > 0) and _mp.today or _today
    local _lvc  = _G._lv_shops_cache or {}
    local _lve  = _lvc[nm:lower()]
    local _sell_lv = _lve and _lve.sell or nil
    local _buy_lv  = _lve and _lve.buy or nil
    local _res = {today_cp = _today_cp, avg_cp = _today, sell_lv = _sell_lv, buy_lv = _buy_lv}
    _G._mh_buy_ip_cache[nm] = _res
    return _res
end
function _mh_buy.snapshot_items(items)
    local out = {}
    for i, it in ipairs(items or {}) do
        local pr = _mh_buy.item_prices(it.name or '')
        local _q1 = it.qty_limit_1 or _mh_is_qty1_item(it.name)
        out[i] = {
            name        = _mh_buy.cp_to_u8(it.name),
            qty         = it.qty or 1,
            target_qty  = it.target_qty or it.qty or 1,
            max_price   = it.max_price or 0,
            enabled     = (it.enabled ~= false),
            qty_limit_1 = _q1 and true or false,
            needs_rebuy = it.needs_rebuy == true,
            today_cp    = pr.today_cp,
            avg_cp      = pr.avg_cp,
            sell_lv     = pr.sell_lv,
            buy_lv      = pr.buy_lv,
        }
    end
    return out
end
function _mh_buy.snapshot_items_light(items)
