            enabled     = (it.enabled ~= false),
            qty_limit_1 = _q1 and true or false,
            needs_rebuy = it.needs_rebuy == true,
        }
    end
    return out
end
function _mh_buy.build_state()
    local _presets = {}
    for pi, pr in ipairs(settings.buy_presets or {}) do
        _presets[pi] = {
            name  = _mh_buy.cp_to_u8(pr.name) or ('Preset ' .. tostring(pi)),
            items = (pi == fh_ab_preset_idx)
                and _mh_buy.snapshot_items(pr.items or {})
                or  _mh_buy.snapshot_items_light(pr.items or {}),
        }
    end
    local _bal = 0
    pcall(function() _bal = getPlayerMoney(PLAYER_PED) end)
    local _servers = {}
    for i, s in ipairs(ARZ_SERVERS) do
        _servers[i] = {id = s.id, name = _mh_buy.cp_to_u8(s.name)}
    end
    return {
        kind          = 'state',
        presets       = _presets,
        active_preset = fh_ab_preset_idx or 1,
        running       = fh_lv_autobuy_running and true or false,
        status        = _mh_buy.cp_to_u8(fh_lv_autobuy_status or ''),
        balance       = _bal,
        has_rebuy     = (function()
            if _G._mh_ab_has_real_sale == true then return true end
            for _, _rb in ipairs(fh_lv_autobuy_preset or {}) do
                if _rb.needs_rebuy == true then return true end
            end
            return false
        end)(),
        cloud_servers = _servers,
    }
end
function _mh_buy.push_state()
    if not (_mh_web_jar and _mh_buy.state.created) then return end
    _mh_buy.state.push_seq = (_mh_buy.state.push_seq or 0) + 1
    local _my_seq = _mh_buy.state.push_seq
    lua_thread.create(function()
        wait(0)
        local ok_j, j = pcall(encodeJson, _mh_buy.build_state())
        if not ok_j or type(j) ~= 'string' then return end
        local ok_b64, b64 = pcall(function() return require('basexx').to_base64(j) end)
        if not ok_b64 or not b64 then return end
        if _mh_buy.state.push_seq ~= _my_seq then return end                                          
        pcall(function()
            _mh_web_jar.executeJS(_mh_buy.bid, "window.mhReceiveState && window.mhReceiveState('" .. b64 .. "');")
        end)
    end)
end
function _mh_buy.push_import_list()
