end
function _mh_buy.push_listing_status()
    if not (_mh_web_jar and _mh_buy.state.created) then return end
    local _pid = 'buy_' .. tostring(fh_ab_preset_idx or 1)
    _mh_listings.post('/api/mh/listings/mine', {}, function(res, err)
        if not res or not res.ok then return end
        local _mine = nil
        for _, l in ipairs(res.listings or {}) do
            if l.preset_id == _pid then _mine = l; break end
        end
        local ok_j, j = pcall(encodeJson, {
            kind          = 'listing_status',
            published     = _mine ~= nil,
            listing_id    = _mine and _mine.id or nil,
            is_premium    = res.is_premium and true or false,
            bump_cooldown = res.bump_cooldown,
            last_bump_at  = _mine and _mine.last_bump_at or 0,
            active_count  = #(res.listings or {}),
            active_limit  = res.limit,
        })
        if not ok_j then return end
        local ok_b64, b64 = pcall(function() return require('basexx').to_base64(j) end)
        if not ok_b64 or not b64 then return end
        pcall(function()
            _mh_web_jar.executeJS(_mh_buy.bid, "window.mhReceiveState && window.mhReceiveState('" .. b64 .. "');")
        end)
    end)
end
function _mh_buy.push_search_results(q_u8, req_id)
    if not (_mh_web_jar and _mh_buy.state.created and _mh_buy.state.loaded) then return end
    local _q = fh_lower(_mh_buy.u8_to_cp(q_u8 or '')):match('^%s*(.-)%s*$') or ''
    local _items = {}
    if #_q >= 2 then
        local _all, _all_lower = fh_get_allitems_list()
        local _already = {}
        for _, p in ipairs(fh_lv_autobuy_preset) do _already[fh_lower(p.name)] = true end
        local _shown = 0
        for i, nm in ipairs(_all) do
            if _shown >= 25 then break end
            local nm_lower = _all_lower[i]
            if nm_lower:find(_q, 1, true) then
                local e = fh_mkt_prices[nm]
                local ph = e and (e.s_avg or e.b_avg) or 0
                _items[#_items + 1] = {
                    name    = _mh_buy.cp_to_u8(nm),
                    price   = ph,
                    already = _already[nm_lower] == true,
                }
                _shown = _shown + 1
            end
        end
    end
    local resp = {kind = 'search_results', req_id = tonumber(req_id) or 0, items = _items}
    local ok_j, j = pcall(encodeJson, resp)
    if not ok_j then return end
    local ok_b64, b64 = pcall(function() return require('basexx').to_base64(j) end)
    if not ok_b64 or not b64 then return end
    pcall(function()
        _mh_web_jar.executeJS(_mh_buy.bid, "window.mhReceiveState && window.mhReceiveState('" .. b64 .. "');")
    end)
end
function _mh_buy.cloud_fetch_list(filters, req_id)
    local page = tonumber(filters and filters.page) or 1
    if page < 1 then page = 1 end
    local _sid = tonumber(filters and filters.server_id) or -1
    local _budget_max = tonumber(filters and filters.budget_max) or 0
    local _sort = (filters and filters.sort) or 'downloads'
    local _url = _vbr7n .. '/cloud-presets/list'
        .. '?server_id=' .. tostring(_sid)
        .. '&budget_max=' .. tostring(_budget_max)
        .. '&sort=' .. tostring(_sort)
        .. '&page=' .. tostring(page)
    local _srch_u8 = (filters and filters.search) or ''
    if _srch_u8 ~= '' then
        _url = _url .. '&search=' .. _mh_url_encode(_srch_u8)
    end
    if filters and filters.mine_only then
        local _mnick = _mh_get_live_nick()
        if not _mh_is_fake_nick(_mnick) then
            _url = _url .. '&mine_nick=' .. _mh_url_encode(_to_utf8(_mnick))
        end
    end
    _fwm2c(_url, '', _mh_get_live_nick(), function(code, body, err)
        local resp = {kind = 'cloud_list', req_id = tonumber(req_id) or 0, page = page}
        if err or code ~= 200 or not body then
            resp.error = tostring(err or code or 'connection failed')
        else
            local ok2, parsed = pcall(decodeJson, body)
            if not ok2 or type(parsed) ~= 'table' or not parsed.ok then
                resp.error = 'bad_response'
            else
                _G._mh_buy_cloud_raw = parsed.presets or {}                                                                 
                local _list = {}
                for i, cp in ipairs(parsed.presets or {}) do
                    _list[i] = {
                        id        = cp.id,
                        title     = _mh_buy.cp_to_u8(cp.title or ''),
                        nick      = _mh_buy.cp_to_u8(cp.nick or ''),
                        server_id = cp.server_id,
                        budget    = cp.budget or 0,
                        item_count = cp.item_count or #(cp.items or {}),
                        downloads = cp.downloads or 0,
                        views     = cp.views or 0,
                        likes     = cp.likes or 0,
                        dislikes  = cp.dislikes or 0,
                        my_vote   = _G._mh_cloud_my_votes[cp.id],
                        is_owner  = (function()
                            local _mn = _mh_get_live_nick()
                            if _mh_is_fake_nick(_mn) then return false end
                            return tostring(cp.nick or ''):lower() == tostring(_mn):lower()
                        end)(),
                    }
                end
                resp.presets = _list
                resp.total   = parsed.total or 0
            end
        end
        local ok_j, j = pcall(encodeJson, resp)
        if not ok_j then return end
        local ok_b64, b64 = pcall(function() return require('basexx').to_base64(j) end)
        if not ok_b64 or not b64 then return end
        pcall(function()
            if _mh_web_jar and _mh_buy.state.created and _mh_buy.state.loaded then
                _mh_web_jar.executeJS(_mh_buy.bid, "window.mhReceiveState && window.mhReceiveState('" .. b64 .. "');")
            end
        end)
    end)
end
function _mh_buy.cloud_push_detail(preset_id, req_id)
    local _pid = tonumber(preset_id)
    local cp = nil
    for _, e in ipairs(_G._mh_buy_cloud_raw or {}) do
        if e.id == _pid then cp = e; break end
    end
    if not cp then
        local resp = {kind = 'cloud_detail', req_id = tonumber(req_id) or 0, error = 'not_found'}
        local ok_j, j = pcall(encodeJson, resp)
        if ok_j then
            local ok_b64, b64 = pcall(function() return require('basexx').to_base64(j) end)
            if ok_b64 and b64 then
                pcall(function() _mh_web_jar.executeJS(_mh_buy.bid, "window.mhReceiveState && window.mhReceiveState('" .. b64 .. "');") end)
            end
        end
        return
    end
    cp.views = (cp.views or 0) + 1
    if cp.id then
        local ok_j0, j0 = pcall(encodeJson, {preset_id = cp.id})
        if ok_j0 then
            _jmx9s(_vbr7n .. '/cloud-presets/view', j0, function() end)
        end
    end
    local _items = {}
    for i, it in ipairs(cp.items or {}) do
        _items[i] = {name = _mh_buy.cp_to_u8(it.name or ''), price = it.price or 0, qty = it.qty or 1}
    end
    local resp = {
        kind      = 'cloud_detail',
        req_id    = tonumber(req_id) or 0,
        id        = cp.id,
        title     = _mh_buy.cp_to_u8(cp.title or ''),
        nick      = _mh_buy.cp_to_u8(cp.nick or ''),
        server_id = cp.server_id,
        downloads = cp.downloads or 0,
        views     = cp.views or 0,
        likes     = cp.likes or 0,
        dislikes  = cp.dislikes or 0,
        items     = _items,
    }
    local ok_j, j = pcall(encodeJson, resp)
    if not ok_j then return end
    local ok_b64, b64 = pcall(function() return require('basexx').to_base64(j) end)
    if not ok_b64 or not b64 then return end
    pcall(function()
        _mh_web_jar.executeJS(_mh_buy.bid, "window.mhReceiveState && window.mhReceiveState('" .. b64 .. "');")
    end)
end
function _mh_buy.handle_bridge_payload(data)
    if type(data) ~= 'table' or not data.kind then return end
    if data.kind == 'ready' then
        pcall(_mh_buy.push_state)
        pcall(_mh_buy.push_listing_status)
        return
    end
    local _changed = true
    if data.kind == 'buy_add' and data.name and data.name ~= '' then
        local _nm = _mh_buy.u8_to_cp(data.name)
        local _already = false
        for _, p in ipairs(fh_lv_autobuy_preset) do
            if fh_lower(p.name) == fh_lower(_nm) then _already = true; break end
        end
        if _already then
            _changed = false
        else
            local _is_q1 = _mh_is_qty1_item(_nm)
            local _pr = _mh_buy.item_prices(_nm)
            local _best = _pr.buy_lv or _pr.today_cp or _pr.avg_cp or 0
            table.insert(fh_lv_autobuy_preset, {
                name = _nm, max_price = _best, qty = 1, target_qty = 1,
                qty_limit_1 = _is_q1 or nil,
            })
        end
    elseif data.kind == 'buy_remove' and data.index then
        local _idx = tonumber(data.index)
        if _idx and fh_lv_autobuy_preset[_idx] then
            table.remove(fh_lv_autobuy_preset, _idx)
        else
            _changed = false
        end
    elseif data.kind == 'buy_update' and data.index then
        local _idx = tonumber(data.index)
        local _it = _idx and fh_lv_autobuy_preset[_idx]
        if _it then
            if data.max_price ~= nil then _it.max_price = tonumber(data.max_price) or _it.max_price end
            if data.qty       ~= nil then
                local _q1 = _it.qty_limit_1 or _mh_is_qty1_item(_it.name)
                _it.qty = _q1 and 1 or (tonumber(data.qty) or _it.qty)
                if not _it.target_qty or _it.target_qty == 0 then _it.target_qty = _it.qty end
            end
            if data.enabled ~= nil then
                _it.enabled = data.enabled and true or false
                if _it.enabled and (_it.qty or 0) <= 0 then
                    _it.qty = 1
                    if not _it.target_qty or _it.target_qty == 0 then _it.target_qty = 1 end
                end
            end
            if (_it.qty or 0) <= 0 then _it.enabled = false end
        else
            _changed = false
        end
    elseif data.kind == 'buy_reorder' and data.index and data.target then
        local _idx, _tgt = tonumber(data.index), tonumber(data.target)
        local _n = #fh_lv_autobuy_preset
        if _idx and _tgt and fh_lv_autobuy_preset[_idx] then
            if _tgt < 1 then _tgt = 1 end
            if _tgt > _n then _tgt = _n end
            if _tgt ~= _idx then
                local _moved = table.remove(fh_lv_autobuy_preset, _idx)
                table.insert(fh_lv_autobuy_preset, _tgt, _moved)
            else
                _changed = false
            end
        else
            _changed = false
        end
    elseif data.kind == 'buy_sort' and data.mode then
        if data.mode == 'price_asc' then
            table.sort(fh_lv_autobuy_preset, function(a,b) return (a.max_price or 0) < (b.max_price or 0) end)
        elseif data.mode == 'price_desc' then
            table.sort(fh_lv_autobuy_preset, function(a,b) return (a.max_price or 0) > (b.max_price or 0) end)
        elseif data.mode == 'sum_desc' then
            table.sort(fh_lv_autobuy_preset, function(a,b)
                return ((a.max_price or 0)*(a.qty or 1)) > ((b.max_price or 0)*(b.qty or 1))
            end)
        else
            table.sort(fh_lv_autobuy_preset, function(a,b) return (a.name or '') < (b.name or '') end)
        end
    elseif data.kind == 'buy_mark_all' then
        local _marked = 0
        for _, _abp in ipairs(fh_lv_autobuy_preset) do
            if (_abp.qty or 0) > 0 and _abp.enabled ~= true then
                _abp.enabled = true
                _marked = _marked + 1
            end
        end
        mh_notify('[MH] {00cc00}' .. '\xce\xf2\xec\xe5\xf2\xe8\xf2\xfc\x20\xe2\xf1\xe5\x3a\x20\xe2\xea\xeb\xfe\xf7\xe5\xed\xee\x20' .. _marked .. '\x20\xf2\xee\xe2\xe0\xf0\xee\xe2\x2e', 0xFFFFFF)
    elseif data.kind == 'buy_preset_switch' and data.index then
        local _pi = tonumber(data.index)
        if _pi and settings.buy_presets and settings.buy_presets[_pi] then
            fh_ab_preset_idx = _pi
            settings.active_buy_preset = _pi
            fh_lv_autobuy_preset = settings.buy_presets[_pi].items or {}
            settings.autobuy_preset = fh_lv_autobuy_preset
            settings._ab_undo_snap = nil
        else
            _changed = false
        end
    elseif data.kind == 'buy_preset_create' then
        if not settings.buy_presets then settings.buy_presets = {} end
        local _nm = (data.name and data.name ~= '') and _mh_buy.u8_to_cp(data.name)
            or ('\xcf\xf0\xe5\xf1\xe5\xf2\x20' .. tostring(#settings.buy_presets + 1))
        table.insert(settings.buy_presets, {name = _nm, items = {}})
        fh_ab_preset_idx = #settings.buy_presets
        settings.active_buy_preset = fh_ab_preset_idx
        fh_lv_autobuy_preset = settings.buy_presets[fh_ab_preset_idx].items
        settings.autobuy_preset = fh_lv_autobuy_preset
    elseif data.kind == 'buy_preset_rename' and data.name and data.name ~= '' then
        local _p = settings.buy_presets and settings.buy_presets[fh_ab_preset_idx]
        if _p then _p.name = _mh_buy.u8_to_cp(data.name) else _changed = false end
    elseif data.kind == 'buy_preset_delete' then
        if settings.buy_presets and #settings.buy_presets > 1 then
            table.remove(settings.buy_presets, fh_ab_preset_idx)
            fh_ab_preset_idx = math.max(1, fh_ab_preset_idx - 1)
            settings.active_buy_preset = fh_ab_preset_idx
            fh_lv_autobuy_preset = settings.buy_presets[fh_ab_preset_idx].items or {}
            settings.autobuy_preset = fh_lv_autobuy_preset
        else
            mh_notify('[MH] {ff4444}' .. '\xcd\xe5\xeb\xfc\xe7\xff\x20\xf3\xe4\xe0\xeb\xe8\xf2\xfc\x20\xe5\xe4\xe8\xed\xf1\xf2\xe2\xe5\xed\xed\xfb\xe9\x20\xef\xf0\xe5\xf1\xe5\xf2\x2e', 0xFFFFFF)
            _changed = false
        end
    elseif data.kind == 'buy_search' then
        pcall(_mh_buy.push_search_results, data.query, data.req_id)
        _changed = false
    elseif data.kind == 'cloud_list' then
        pcall(_mh_buy.cloud_fetch_list, data.filters, data.req_id)
        _changed = false
    elseif data.kind == 'cloud_detail' then
        pcall(_mh_buy.cloud_push_detail, data.id, data.req_id)
        _changed = false
    elseif data.kind == 'cloud_vote' and data.id then
        local _cp = nil
        for _, e in ipairs(_G._mh_buy_cloud_raw or {}) do
            if e.id == tonumber(data.id) then _cp = e; break end
        end
        if _cp then pcall(_mh_cloud_vote_preset, _cp, tonumber(data.vote) == -1 and -1 or 1, data.req_id) end
        _changed = false
    elseif data.kind == 'cloud_add' and data.id then
        local _cp = nil
        for _, e in ipairs(_G._mh_buy_cloud_raw or {}) do
            if e.id == tonumber(data.id) then _cp = e; break end
        end
        if _cp then
            pcall(_mh_cloud_add_preset_to_mine, _cp)
            pcall(_mh_buy.push_state)
        end
        _changed = false
    elseif data.kind == 'cloud_delete' and data.id then
        local _cp = nil
        for _, e in ipairs(_G._mh_buy_cloud_raw or {}) do
            if e.id == tonumber(data.id) then _cp = e; break end
        end
        if _cp then pcall(_mh_cloud_delete_preset, _cp) end
        _changed = false
    elseif data.kind == 'buy_preset_import_list' then
        _mh_buy.push_import_list()
        _changed = false
    elseif data.kind == 'buy_preset_import_pick' and data.fname and data.fname ~= '' then
        local _dir = _mh_preset_dir()
        local _path = _dir .. '/' .. data.fname
        local _ok3, _nm3, _items3 = _mh_import_preset_file(_path)
        if _ok3 then
            if not settings.buy_presets then settings.buy_presets = {} end
            table.insert(settings.buy_presets, {name = _nm3, items = _items3 or {}})
            fh_ab_preset_idx = #settings.buy_presets
            settings.active_buy_preset = fh_ab_preset_idx
            fh_lv_autobuy_preset = settings.buy_presets[fh_ab_preset_idx].items
            settings.autobuy_preset = fh_lv_autobuy_preset
        else
            mh_notify('[MH] {ff6666}' .. '\xcd\xe5\x20\xf3\xe4\xe0\xeb\xee\xf1\xfc\x20\xe8\xec\xef\xee\xf0\xf2\xe8\xf0\xee\xe2\xe0\xf2\xfc\x20\xef\xf0\xe5\xf1\xe5\xf2\x2e', 0xFFFFFF)
            _changed = false
        end
    elseif data.kind == 'buy_export_file' then
        local _pname = (settings.buy_presets and settings.buy_presets[fh_ab_preset_idx] and settings.buy_presets[fh_ab_preset_idx].name)
            or ('\xd1\xea\xf3\xef\xea\xe0\x20' .. tostring(fh_ab_preset_idx))
        local _ok5, _res5 = _mh_export_preset('buy', _pname, fh_lv_autobuy_preset)
        if _ok5 then
            mh_notify('[MH] {aaffaa}' .. '\xcf\xf0\xe5\xf1\xe5\xf2\x20\xf1\xee\xf5\xf0\xe0\xed\xb8\xed\x20\xe2\x20\xf4\xe0\xe9\xeb\x3a\x20' .. tostring(_res5), 0xFFFFFF)
        else
            mh_notify('[MH] {ff6666}' .. '\xcd\xe5\x20\xf3\xe4\xe0\xeb\xee\xf1\xfc\x20\xf1\xee\xf5\xf0\xe0\xed\xe8\xf2\xfc\x20\xef\xf0\xe5\xf1\xe5\xf2\x20\xe2\x20\xf4\xe0\xe9\xeb\x20\x28' .. tostring(_res5) .. ').', 0xFFFFFF)
        end
        _changed = false
    elseif data.kind == 'buy_export_cloud' then
        pcall(_mh_cloud_push_buy_preset)
        _changed = false
    elseif data.kind == 'buy_snapshot_save' then
        settings._ab_undo_snap = _mh_deep_copy_list(fh_lv_autobuy_preset)
        mh_notify('[MH] {aaddff}' .. '\xcf\xf0\xe5\xf1\xe5\xf2\x20\xf1\xee\xf5\xf0\xe0\xed\xb8\xed\x20\x28' .. tostring(#fh_lv_autobuy_preset) .. '\x20\xf2\xee\xe2\x2e\x29\x20\x2d\x2d\x20\xe2\x20\xf4\xe0\xe9\xeb\x20\xed\xe0\xf1\xf2\xf0\xee\xe5\xea\x20\xe8\x20\xe2\x20\xef\xe0\xec\xff\xf2\xfc\x20\xe4\xeb\xff\x20\xe2\xee\xf1\xf1\xf2\xe0\xed\xee\xe2\xeb\xe5\xed\xe8\xff\x2e', 0xFFFFFF)
    elseif data.kind == 'buy_snapshot_restore' then
        if settings._ab_undo_snap then
            fh_lv_autobuy_preset = _mh_deep_copy_list(settings._ab_undo_snap)
            settings.autobuy_preset = fh_lv_autobuy_preset
            if settings.buy_presets and settings.buy_presets[fh_ab_preset_idx] then
                settings.buy_presets[fh_ab_preset_idx].items = fh_lv_autobuy_preset
            end
            mh_notify('[MH] {aaffaa}' .. '\xcf\xf0\xe5\xf1\xe5\xf2\x20\xe2\xee\xf1\xf1\xf2\xe0\xed\xee\xe2\xeb\xe5\xed\x20\xe8\xe7\x20\xf1\xed\xe8\xec\xea\xe0\x20\x28' .. tostring(#fh_lv_autobuy_preset) .. '\x20\xf2\xee\xe2\x2e\x29\x2e', 0xFFFFFF)
        else
            mh_notify('[MH] {ffaa55}' .. '\xd1\xed\xe8\xec\xee\xea\x20\xe5\xf9\xb8\x20\xed\xe5\x20\xf1\xee\xf5\xf0\xe0\xed\xb8\xed\x2e', 0xFFFFFF)
            _changed = false
        end
    elseif data.kind == 'buy_clean_preset' then
        local _removed = 0
        for i = #fh_lv_autobuy_preset, 1, -1 do
            table.remove(fh_lv_autobuy_preset, i)
            _removed = _removed + 1
        end
        mh_notify('[MH] {ffaa55}' .. '\xce\xf7\xe8\xf9\xe5\xed\x20\xef\xf0\xe5\xf1\xe5\xf2\x20\x28\xf3\xe4\xe0\xeb\xe5\xed\xee\x20' .. _removed .. '\x29\x2e', 0xFFFFFF)
    elseif data.kind == 'buy_distribute_budget' and data.budget then
        local _budget = tonumber(data.budget) or 0
        local _n = #fh_lv_autobuy_preset
        if _budget <= 0 or _n == 0 then
            mh_notify('[MH] {ff4444}' .. '\xc2\xe2\xe5\xe4\xe8\xf2\xe5\x20\xf1\xf3\xec\xec\xf3\x20\xe1\xee\xeb\xfc\xf8\xe5\x20\x30', 0xFFFFFF)
            _changed = false
        else
            local _price = {}
            for _abi = 1, _n do
                _price[_abi] = math.max(1, fh_lv_autobuy_preset[_abi].max_price or 1)
            end
            local _MAX_ITEM_SHARE = 0.05
            local _max_qty = {}
            for _abi = 1, _n do
                if fh_lv_autobuy_preset[_abi].enabled == false then
                    _max_qty[_abi] = 0
                elseif fh_lv_autobuy_preset[_abi].qty_limit_1
                   or _mh_is_qty1_item(fh_lv_autobuy_preset[_abi].name) then
                    _max_qty[_abi] = 1
                else
                    local _cap_value = math.max(_price[_abi], _budget * _MAX_ITEM_SHARE)
                    _max_qty[_abi] = math.max(1, math.floor(_cap_value / _price[_abi]))
                end
            end
            local _assigned = {}
            for _abi = 1, _n do _assigned[_abi] = 0 end
            local _remaining = _budget
            local _expensive_idx = {}
            for _abi = 1, _n do table.insert(_expensive_idx, _abi) end
            table.sort(_expensive_idx, function(a, b) return _price[a] > _price[b] end)
            local _cheap_idx = {}
            for _abi = 1, _n do table.insert(_cheap_idx, _abi) end
            table.sort(_cheap_idx, function(a, b) return _price[a] < _price[b] end)
            do
                local _phase1_limit = _budget * 0.4
                local _spent1 = 0
                local _progressed = true
                while _progressed do
                    _progressed = false
                    for _, _abi in ipairs(_expensive_idx) do
                        if _assigned[_abi] < _max_qty[_abi]
                           and (_spent1 + _price[_abi]) <= _phase1_limit
                           and _remaining >= _price[_abi] then
                            _assigned[_abi] = _assigned[_abi] + 1
                            _remaining = _remaining - _price[_abi]
                            _spent1 = _spent1 + _price[_abi]
                            _progressed = true
                        end
                    end
                end
            end
            do
                local _phase2_limit = math.min(_remaining, _budget * 0.4)
                local _share2 = _phase2_limit / _n
                for _abi = 1, _n do
                    local _qty2 = math.floor(_share2 / _price[_abi])
                    _qty2 = math.min(_qty2, _max_qty[_abi] - _assigned[_abi])
                    if _qty2 > 0 then
                        _assigned[_abi] = _assigned[_abi] + _qty2
                        _remaining = _remaining - _qty2 * _price[_abi]
                    end
                end
            end
            do
                local _active = {}
                for _, _abi in ipairs(_cheap_idx) do
                    if _assigned[_abi] < _max_qty[_abi] then table.insert(_active, _abi) end
                end
                while #_active > 0 do
                    if _remaining <= 0 then break end
                    local _min_p = nil
                    for _, _abi in ipairs(_active) do
                        if not _min_p or _price[_abi] < _min_p then _min_p = _price[_abi] end
                    end
                    if _remaining < _min_p then break end
                    local _got_one = false
                    for _, _abi in ipairs(_active) do
                        if _assigned[_abi] < _max_qty[_abi] and _remaining >= _price[_abi] then
                            _assigned[_abi] = _assigned[_abi] + 1
                            _remaining = _remaining - _price[_abi]
                            _got_one = true
                        end
                    end
                    local _next_active = {}
                    for _, _abi in ipairs(_active) do
                        if _assigned[_abi] < _max_qty[_abi] and _price[_abi] <= _remaining then
                            table.insert(_next_active, _abi)
                        end
                    end
                    if not _got_one then break end
                    _active = _next_active
                end
            end
            local _total_qty, _total_spent = 0, 0
            for _abi, _abp in ipairs(fh_lv_autobuy_preset) do
                local _wasEnabled = _abp.enabled ~= false
                local _new_qty = _assigned[_abi] or 0
                _abp.qty = _new_qty
                _abp.target_qty = _new_qty
                if _wasEnabled then
                    _abp.enabled = _new_qty > 0
                end
                _total_qty = _total_qty + _new_qty
                _total_spent = _total_spent + _new_qty * _price[_abi]
            end
            mh_notify('[MH] {aaffaa}' .. '\xc1\xfe\xe4\xe6\xe5\xf2\x20\x24' .. _kcr3y(_budget) .. '\x20\xf0\xe0\xf1\xef\xf0\xe5\xe4\xe5\xeb\xb8\xed\x20\xef\xee\x20' .. _n .. '\x20\xf2\xee\xe2\xe0\xf0\xe0\xec\x20\x28\xe8\xf1\xef\xee\xeb\xfc\xe7\xee\xe2\xe0\xed\xee\x20\x24' .. _kcr3y(_total_spent) .. '\x2c\x20\xe8\xf2\xee\xe3\xee\x20' .. tostring(_total_qty) .. '\x20\xf8\xf2\x29', 0xFFFFFF)
        end
    elseif data.kind == 'buy_rebuy' then
        if #fh_lv_autobuy_preset == 0 then
            mh_notify('[MH] {ffaa44}' .. '\xcf\xf0\xe5\xf1\xe5\xf2\x20\xf1\xea\xf3\xef\xea\xe8\x20\xef\xf3\xf1\xf2', 0xFFFFFF)
        elseif type(_xpk6g) == 'function' then
            _xpk6g(true)
        end
        _changed = false
    elseif data.kind == 'buy_run' then
        if #fh_lv_autobuy_preset > 0 and type(_xpk6g) == 'function' then
            _xpk6g(false)
        else
            mh_notify('[MH] {ff4444}' .. '\xcf\xf0\xe5\xf1\xe5\xf2\x20\xf1\xea\xf3\xef\xea\xe8\x20\xef\xf3\xf1\xf2\x2e', 0xFFFFFF)
        end
        _changed = false
    elseif data.kind == 'buy_stop' then
        fh_lv_autobuy_running = false
        if _mh_buy and _mh_buy.push_state then pcall(_mh_buy.push_state) end
        _changed = false
    elseif data.kind == 'buy_publish_listing' then
        local _contact = data.contact or ''
        local _description = data.description or ''
        local _pid = 'buy_' .. tostring(fh_ab_preset_idx or 1)
        local _buy_out = {}
        for _, it in ipairs(fh_lv_autobuy_preset or {}) do
            if it.enabled ~= false then
                table.insert(_buy_out, {
                    name  = _mh_buy.cp_to_u8(it.name),
                    price = it.max_price or 0,
                    qty   = it.target_qty or it.qty or 0,
                })
            end
        end
        local _srv = _mh_cloud_current_server_id()
        _mh_listings.post('/api/mh/listings/publish', {
            preset_id   = _pid,
            deal_type   = 'buy',
            server_id   = _srv,
            sell_items  = {},
            buy_items   = _buy_out,
            contact     = _contact,
            description = _description,
        }, function(res, err)
            if res and res.ok then
                mh_notify('[MH] {00cc00}' .. (res.action == 'updated'
                    and '\xce\xe1\xfa\xff\xe2\xeb\xe5\xed\xe8\xe5\x20\xee\xe1\xed\xee\xe2\xeb\xe5\xed\xee\x2e'
                    or '\xce\xe1\xfa\xff\xe2\xeb\xe5\xed\xe8\xe5\x20\xf0\xe0\xe7\xec\xe5\xf9\xe5\xed\xee\x2e'), 0xFFFFFF)
            else
