    end
    if _changed then
        local _ap = settings.buy_presets and settings.buy_presets[fh_ab_preset_idx]
        if _ap then _ap.items = fh_lv_autobuy_preset end
        settings.autobuy_preset = fh_lv_autobuy_preset
