function _mh_ads.handle_bridge_payload(data)
    if type(data) ~= 'table' or not data.kind then return end
    if data.kind == 'call' and data.owner and tostring(data.owner) ~= '' then
        local _owner_raw = tostring(data.owner)
        local _owner_cp = _mh_bridge_u8_to_cp(_owner_raw) or _owner_raw
        local _fid = nil
        local _matched_nick = nil
        for _pid = 0, 999 do
            local _ok, _pn = pcall(sampGetPlayerNickname, _pid)
            if _ok and _pn and _pn ~= '' then
                local _pn_s = tostring(_pn)
                if _pn_s:lower() == _owner_raw:lower()
                    or _pn_s:lower() == _owner_cp:lower()
                    or tostring(_mh_bridge_u8_to_cp(_pn_s) or _pn_s):lower() == _owner_raw:lower() then
                    _fid = _pid
                    _matched_nick = _pn_s
                    break
                end
            end
        end
        if _fid then
            _G._mh_call_pending_nick = (_matched_nick or _owner_raw):lower()
            sampSendChat('/number ' .. _fid)
            mh_notify('[MH] {aaffaa}Звонок: ' .. (_matched_nick or _owner_raw), 0xFFFFFF)
        else
            mh_notify('[MH] {ffaa00}' .. _owner_raw .. ' не в сети', 0xFFFFFF)
        end
        return
    end
    if data.kind == 'ads_my_listings_req' then
        _mh_listings.post('/api/mh/listings/mine', {}, function(res, err)
            local ok_j, j = pcall(encodeJson, {
                kind          = 'my_listings',
                listings      = (res and res.listings) or {},
                is_premium    = (res and res.is_premium) and true or false,
                bump_cooldown = res and res.bump_cooldown,
                limit         = res and res.limit,
                error         = (not res or not res.ok) and tostring(err or 'unknown') or nil,
            })
            if ok_j then
                local ok_b64, b64 = pcall(function() return require('basexx').to_base64(j) end)
                if ok_b64 and b64 then
                    pcall(function() _mh_web_jar.executeJS(_mh_ads.bid, "window.mhReceiveState && window.mhReceiveState('" .. b64 .. "');") end)
                end
            end
        end)
        return
    end
    if data.kind == 'ads_bump' and data.id then
        _mh_listings.post('/api/mh/listings/bump', {id = tonumber(data.id)}, function(res, err)
            if res and res.ok then
                mh_notify('[MH] {00cc00}' .. '\xce\xe1\xfa\xff\xe2\xeb\xe5\xed\xe8\xe5\x20\xef\xee\xe4\xed\xff\xf2\xee\x2e', 0xFFFFFF)
            else
                mh_notify('[MH] {ff6666}' .. _mh_listings.error_message(err), 0xFFFFFF)
            end
            local ok_j, j = pcall(encodeJson, {kind = 'bump_result', ok = (res and res.ok) and true or false, error = err})
            if ok_j then
                local ok_b64, b64 = pcall(function() return require('basexx').to_base64(j) end)
                if ok_b64 and b64 then
                    pcall(function() _mh_web_jar.executeJS(_mh_ads.bid, "window.mhReceiveState && window.mhReceiveState('" .. b64 .. "');") end)
                end
            end
        end)
    elseif data.kind == 'ads_edit' and data.id then
        local _description = data.description or ''
        local _contact = data.contact or ''
        local _prices = {}
        for _, p in ipairs(data.prices or {}) do
            table.insert(_prices, tonumber(p) or 0)
        end
        _mh_listings.post('/api/mh/listings/edit', {
            id          = tonumber(data.id),
            description = _description,
            contact     = _contact,
            prices      = _prices,
        }, function(res, err)
            if res and res.ok then
                mh_notify('[MH] {00cc00}' .. '\xce\xe1\xfa\xff\xe2\xeb\xe5\xed\xe8\xe5\x20\xee\xe1\xed\xee\xe2\xeb\xe5\xed\xee\x2e', 0xFFFFFF)
            else
                mh_notify('[MH] {ff6666}' .. _mh_listings.error_message(err), 0xFFFFFF)
            end
            local ok_j, j = pcall(encodeJson, {kind = 'edit_result', ok = (res and res.ok) and true or false, error = err})
            if ok_j then
                local ok_b64, b64 = pcall(function() return require('basexx').to_base64(j) end)
                if ok_b64 and b64 then
                    pcall(function() _mh_web_jar.executeJS(_mh_ads.bid, "window.mhReceiveState && window.mhReceiveState('" .. b64 .. "');") end)
                end
            end
        end)
    elseif data.kind == 'ads_delete' and data.id then
        local _nck  = _mh_listings.my_nick()
        local _sess = _G._mh_session_tok or ''
        local thread = effil.thread(_mh_ads_delete_req)(_vbr7n .. '/mh/listings/' .. tostring(tonumber(data.id) or 0), _nck, _sess)
        lua_thread.create(function()
            local _w = 0
            while _w < 200 do
                wait(30); _w = _w + 1
                local status, err = thread:status()
                if not status or err then return end
                if status == 'completed' or status == 'canceled' then
                    local ok2, resp = thread:get()
                    local _ok = ok2 and resp and resp.status_code == 200
                    if _ok then
                        mh_notify('[MH] {aaffaa}' .. '\xce\xe1\xfa\xff\xe2\xeb\xe5\xed\xe8\xe5\x20\xf3\xe4\xe0\xeb\xe5\xed\xee\x2e', 0xFFFFFF)
                    else
                        mh_notify('[MH] {ff6666}' .. '\xcd\xe5\x20\xf3\xe4\xe0\xeb\xee\xf1\xfc\x20\xf3\xe4\xe0\xeb\xe8\xf2\xfc\x20\xee\xe1\xfa\xff\xe2\xeb\xe5\xed\xe8\xe5\x2e', 0xFFFFFF)
                    end
                    local ok_j, j = pcall(encodeJson, {kind = 'delete_result', ok = _ok and true or false, id = data.id})
                    if ok_j then
                        local ok_b64, b64 = pcall(function() return require('basexx').to_base64(j) end)
                        if ok_b64 and b64 then
                            pcall(function() _mh_web_jar.executeJS(_mh_ads.bid, "window.mhReceiveState && window.mhReceiveState('" .. b64 .. "');") end)
                        end
                    end
                    return
                end
            end
        end)
    elseif data.kind == 'ads_create_manual' then
        local _srv = _mh_cloud_current_server_id()
        if data.server_id and tonumber(data.server_id) then _srv = tonumber(data.server_id) end
        local _items = {}
        for _, it in ipairs(data.items or {}) do
            table.insert(_items, {
                name  = it.name,
                price = tonumber(it.price) or 0,
                qty   = tonumber(it.qty) or 0,
            })
        end
        _mh_listings.post('/api/mh/listings/publish', {
            preset_id   = '',
            deal_type   = (data.deal_type == 'buy') and 'buy' or 'sale',
            server_id   = _srv,
            sell_items  = (data.deal_type == 'buy') and {} or _items,
            buy_items   = (data.deal_type == 'buy') and _items or {},
            contact     = data.contact or '',
            description = data.description or '',
        }, function(res, err)
            if res and res.ok then
                mh_notify('[MH] {00cc00}' .. '\xce\xe1\xfa\xff\xe2\xeb\xe5\xed\xe8\xe5\x20\xf0\xe0\xe7\xec\xe5\xf9\xe5\xed\xee\x2e', 0xFFFFFF)
            else
                mh_notify('[MH] {ff6666}' .. _mh_listings.error_message(err), 0xFFFFFF)
            end
            local ok_j, j = pcall(encodeJson, {kind = 'create_result', ok = (res and res.ok) and true or false, error = err})
            if ok_j then
                local ok_b64, b64 = pcall(function() return require('basexx').to_base64(j) end)
                if ok_b64 and b64 then
                    pcall(function() _mh_web_jar.executeJS(_mh_ads.bid, "window.mhReceiveState && window.mhReceiveState('" .. b64 .. "');") end)
                end
            end
        end)
    elseif data.kind == 'ads_search' and data.query then
        if type(_mh_buy) == 'table' and _mh_buy.push_search_results then
            local _q_cp = _mh_buy.u8_to_cp(data.query)
            local _req_id = tonumber(data.req_id) or 0
            local _results = {}
            local _q_lo = fh_lower(_q_cp)
            local _count = 0
            for nm, _ in pairs(fh_mkt_prices or {}) do
                if _count >= 30 then break end
                if _q_lo == '' or fh_lower(nm):find(_q_lo, 1, true) then
                    local _pr = fh_mkt_prices[nm]
                    table.insert(_results, {
                        name  = _mh_buy.cp_to_u8(nm),
                        price = (_pr and _pr.cp_sp) or 0,
                    })
                    _count = _count + 1
                end
            end
            local ok_j, j = pcall(encodeJson, {kind = 'search_results', req_id = _req_id, items = _results})
            if ok_j then
                local ok_b64, b64 = pcall(function() return require('basexx').to_base64(j) end)
                if ok_b64 and b64 then
                    pcall(function() _mh_web_jar.executeJS(_mh_ads.bid, "window.mhReceiveState && window.mhReceiveState('" .. b64 .. "');") end)
                end
            end
        end
    end
end
if _mh_web_jar then
    local _mh_ads_onAction_prev = _mh_web_jar.onAction
    function _mh_web_jar.onAction(data)
        if not data then return end                                                               
        if data.browserid == _mh_ads.bid then
            if data.type == "WV_STARTED" then
                _mh_ads.state.crashed = false
                _mh_ads.state.loaded = false
            elseif data.type == "WV_LOADED" then
                _mh_ads.state.loaded = true
                _mh_ads.apply_zoom()
            elseif data.type == "WV_PROGRESS" then
                local p = tonumber(data.msg)
                if p and p > _mh_ads.state.progress then _mh_ads.state.progress = p end
            elseif data.type == "WV_DIE" then
                _mh_ads.state.crashed = true
                _mh_ads.state.created = false
                pcall(function() _mh_web_jar.deleteBrowser(_mh_ads.bid) end)
            elseif data.type == "WV_ANSWER" then
                local _raw_msg = tostring(data.msg or '')
                local _prefix = 'MH_BRIDGE:'
                local _idx = _raw_msg:find(_prefix, 1, true)
                if _idx then
                    local _json_part = _raw_msg:sub(_idx + #_prefix)
                    local _ok_js, _js_obj = pcall(decodeJson, _json_part)
                    if _ok_js and type(_js_obj) == 'table' and _js_obj.kind then
                        pcall(_mh_ads.handle_bridge_payload, _js_obj)
                    end
                end
            end
            return
        end
        if _mh_ads_onAction_prev then _mh_ads_onAction_prev(data) end
    end
end
function _mh_ads_hide()
