            _mh_web_jar.setClickable(_mh_ads.bid, false)
            _mh_web_jar.setVisible(_mh_ads.bid, false)
            _mh_web_jar.deleteBrowser(_mh_ads.bid)
        end)
        _mh_ads.state.created         = false
        _mh_ads.state.loaded          = false
        _mh_ads.state.crashed         = false
        _mh_ads.state.progress        = 0
        _mh_ads.state.visible_applied = false
        _mh_ads.state.pos = {x = -99999, y = -99999, w = 0, h = 0}
    end
end
