function _MH_LOG.send(payload)
    if mh_debug_enabled then
        mh_notify('[MH Дебаг] {aaaaaa}_MH_LOG.send kind='..tostring(payload and payload.kind)..
            ' created='..tostring(_MH_LOG.state.created)..' loaded='..tostring(_MH_LOG.state.loaded), 0xFFFFFF)
    end
    if not (_mh_web_jar and _MH_LOG.state.created) then return end
    local ok_j, j = pcall(encodeJson, payload)
    if not ok_j then
        if mh_debug_enabled then mh_notify('[MH Дебаг] {ff5555}_MH_LOG.send: encodeJson FAILED', 0xFF5555) end
        return
    end
    local ok_b64, b64 = pcall(function() return require('basexx').to_base64(j) end)
    if not ok_b64 or not b64 then
        if mh_debug_enabled then mh_notify('[MH Дебаг] {ff5555}_MH_LOG.send: base64 FAILED', 0xFF5555) end
        return
    end
    local ok_exec, err_exec = pcall(function()
        _mh_web_jar.executeJS(_MH_LOG.bid, "window.mhReceiveLogData && window.mhReceiveLogData('" .. b64 .. "');")
    end)
    if mh_debug_enabled then
        if ok_exec then
            mh_notify('[MH Дебаг] {55ff55}_MH_LOG.send: executeJS OK, len='..tostring(#b64), 0x55FF55)
        else
            mh_notify('[MH Дебаг] {ff5555}_MH_LOG.send: executeJS THREW '..tostring(err_exec), 0xFF5555)
        end
    end
end
function _MH_LOG.day_ok(le_dt, day_filter, sel_date)
    if day_filter == 0 or not day_filter then return true end
    if not le_dt or le_dt == '' then return false end
    local now = os.time()
    local t = os.date('*t', now)
    local d_day = string.format('%02d.%02d', t.day, t.month)
    local e_day = le_dt:sub(1, 5)
    if day_filter == 1 then
        return e_day == d_day
    elseif day_filter == 2 or day_filter == 3 then
        local e_d = tonumber(le_dt:sub(1, 2)) or 0
        local e_m = tonumber(le_dt:sub(4, 5)) or 0
        local e_ts = os.time({year = t.year, month = e_m, day = e_d, hour = 0, min = 0, sec = 0})
        if e_ts > now then e_ts = os.time({year = t.year - 1, month = e_m, day = e_d, hour = 0, min = 0, sec = 0}) end
        local span = (day_filter == 2) and (7 * 86400) or (30 * 86400)
        return (now - e_ts) <= span
    elseif day_filter == 4 then
        return e_day == (sel_date or '')
    end
    return true
end
function _MH_LOG.query_deals(req_id, page, search, day_filter, sel_date)
    if mh_debug_enabled then
        mh_notify('[MH Дебаг] {aaaaaa}query_deals: fh_mkt_log total='..tostring(#fh_mkt_log)..
            ' day_filter='..tostring(day_filter)..' first_dt='..tostring(fh_mkt_log[1] and fh_mkt_log[1].dt), 0xFFFFFF)
    end
    local srch = (search or ''):lower()
    local filt = {}
    for i = #fh_mkt_log, 1, -1 do
        local le = fh_mkt_log[i]
        if le and le.item and _MH_LOG.day_ok(le.dt, day_filter, sel_date) then
            local item_lo = le.item:lower()
            if srch == '' or item_lo:find(srch, 1, true) then
                table.insert(filt, le)
            end
        end
    end
    if mh_debug_enabled then
        mh_notify('[MH Дебаг] {aaaaaa}query_deals: filt count='..tostring(#filt), 0xFFFFFF)
    end
    local total_sell_sum, total_buy_sum, total_sell_cnt, total_buy_cnt = 0, 0, 0, 0
    for _, le2 in ipairs(filt) do
        local is_s = fh_is_my_sell(le2)
        local q = le2.qty or 1
        if is_s then total_sell_sum = total_sell_sum + (le2.price or 0) * q; total_sell_cnt = total_sell_cnt + q
        else total_buy_sum = total_buy_sum + (le2.price or 0) * q; total_buy_cnt = total_buy_cnt + q end
    end
    local total_count = #filt
    local total_pages = math.max(1, math.ceil(total_count / _MH_LOG.page_size))
    if page < 1 then page = 1 end
    if page > total_pages then page = total_pages end
    local from_i = (page - 1) * _MH_LOG.page_size + 1
    local to_i = math.min(page * _MH_LOG.page_size, total_count)
    local items = {}
    for i = from_i, to_i do
        local le = filt[i]
        table.insert(items, {
            dt    = le.dt,
            item  = _mh_bridge_cp_to_u8(le.item),
            price = le.price,
            qty   = le.qty or 1,
            op    = fh_is_my_sell(le) and 'sell' or 'buy',
            status = le.status,
        })
    end
    _MH_LOG.send({
        kind = 'deals_page', req_id = req_id, page = page,
        total_pages = total_pages, total_count = total_count,
        items = items,
        totals = { sell_sum = total_sell_sum, sell_cnt = total_sell_cnt, buy_sum = total_buy_sum, buy_cnt = total_buy_cnt },
    })
end
function _MH_LOG.parse_chat_colors(raw)
    local segments = {}
    local cur_r, cur_g, cur_b = 0.85, 0.85, 0.85
    local pos = 1
    while pos <= #raw do
        local ts8, te8, rh8, gh8, bh8 = raw:find('{(%x%x)(%x%x)(%x%x)%x%x}', pos)
        local ts6, te6, rh6, gh6, bh6 = raw:find('{(%x%x)(%x%x)(%x%x)}', pos)
        local ts, te, rh, gh, bh
        if ts8 and ts6 then
            if ts8 <= ts6 then ts, te, rh, gh, bh = ts8, te8, rh8, gh8, bh8
            else ts, te, rh, gh, bh = ts6, te6, rh6, gh6, bh6 end
        elseif ts8 then ts, te, rh, gh, bh = ts8, te8, rh8, gh8, bh8
        elseif ts6 then ts, te, rh, gh, bh = ts6, te6, rh6, gh6, bh6
        end
        if ts then
            if ts > pos then
                table.insert(segments, { r = cur_r, g = cur_g, b = cur_b, t = raw:sub(pos, ts - 1) })
            end
            cur_r = tonumber(rh, 16) / 255
            cur_g = tonumber(gh, 16) / 255
            cur_b = tonumber(bh, 16) / 255
            pos = te + 1
        else
            table.insert(segments, { r = cur_r, g = cur_g, b = cur_b, t = raw:sub(pos) })
            break
        end
    end
    return segments
end
local _MH_LOG_TRADE_WORDS = {
    '\xcf\xf0\xee\xe4\xe0\xec', '\xcf\xf0\xee\xe4\xe0\xfd\xf8\xfc', '\xca\xf3\xef\xeb\xfe',
    '\xd1\xe4\xe0\xec', '\xd1\xe4\xe0\xb8\xf8\xfc', '\xce\xe1\xec\xe5\xed', '\xee\xe1\xec\xe5\xed\xff\xfe',
    '\xd1\xe5\xeb\xeb', 'sell', 'buy', '/sell', '/buy', '/findilavka', '/findibiz',
    '\xef\xf0\xee\xe4\xe0\xfc', '\xef\xf0\xee\xe4\xe0\xeb', '\xea\xf3\xef\xeb\xfe', '\xea\xf3\xef\xe8\xec',
    '\xf2\xee\xf0\xe3', 'trade', '\xf1\xe4\xe5\xeb\xea\xe0', '\xc2\xfb\xe3\xee\xe4\xed\xee',
}
function _MH_LOG.query_chat(req_id, page, filter, search)
    local srch = (search or ''):lower()
    local out = {}                                                  
    local out_ts = {}                                                   
    for i = 1, #fh_session_chat do
        local raw = fh_session_chat[i]
        local plain = raw:gsub('{%x%x%x%x%x%x%x?%x?}', ''):lower()
        local srch_ok = srch == '' or plain:find(srch, 1, true)
        local filt_ok = false
        if not filter or filter == 0 then
            filt_ok = true
        elseif filter == 1 then
            filt_ok = plain:find('vip adv', 1, true) ~= nil
        elseif filter == 2 then
            for _, w in ipairs(_MH_LOG_TRADE_WORDS) do
                if plain:find(w:lower(), 1, true) then filt_ok = true; break end
            end
        elseif filter == 3 then
            filt_ok = raw:find('[\xc0\xeb\xfc\xff\xed\xf1]', 1, true) ~= nil
        elseif filter == 4 then
            filt_ok = raw:find('[\xd1\xe5\xec\xfc\xff]', 1, true) ~= nil
        end
        if filt_ok and srch_ok then
            table.insert(out, raw)
            table.insert(out_ts, fh_session_chat_ts and fh_session_chat_ts[i] or nil)
        end
    end
    local total_count = #out
    local total_pages = math.max(1, math.ceil(total_count / _MH_LOG.chat_page_size))
    if page < 1 then page = 1 end
    if page > total_pages then page = total_pages end
    local from_i = (page - 1) * _MH_LOG.chat_page_size + 1
    local to_i = math.min(page * _MH_LOG.chat_page_size, total_count)
    local items = {}
    for i = from_i, to_i do
        local segs = _MH_LOG.parse_chat_colors(out[i])
        for _, s in ipairs(segs) do s.t = _mh_bridge_cp_to_u8(s.t) end
        local ts = out_ts[i]
        table.insert(items, { segs = segs, dt = ts and os.date('%H:%M:%S', ts) or '' })
    end
    _MH_LOG.send({
        kind = 'chat_page', req_id = req_id, page = page,
        total_pages = total_pages, total_count = total_count, items = items,
        last_count = #fh_session_chat,
    })
end
function _MH_LOG.query_chat_dates(req_id)
    local ok, dates = pcall(MH_util.cby5m)
    local out = {}
    if ok and dates then
        for _, d in ipairs(dates) do
            table.insert(out, { label = _mh_bridge_cp_to_u8(d.label), day = d.day, month = d.month, year = d.year })
        end
    end
    _MH_LOG.send({ kind = 'chat_dates', req_id = req_id, dates = out })
end
function _MH_LOG.query_chat_history(req_id, day, month, year, page, search)
    local ok, raw = pcall(_rqh9z, day, month, year)
    local lines = {}
    if ok and raw then
        for i = #raw, 1, -1 do table.insert(lines, raw[i]) end
    end
    local srch = (search or ''):lower()
    local filt = {}
    for _, hline in ipairs(lines) do
        if hline ~= '' then
            local plain = hline:gsub('{%x%x%x%x%x%x%x?%x?}', ''):lower()
            if srch == '' or plain:find(srch, 1, true) then
                table.insert(filt, hline)
            end
        end
    end
    local total_count = #filt
    local total_pages = math.max(1, math.ceil(total_count / _MH_LOG.hist_page_size))
    if page < 1 then page = 1 end
    if page > total_pages then page = total_pages end
    local from_i = (page - 1) * _MH_LOG.hist_page_size + 1
    local to_i = math.min(page * _MH_LOG.hist_page_size, total_count)
    local items = {}
    for i = from_i, to_i do
        local segs = _MH_LOG.parse_chat_colors(filt[i])
        for _, s in ipairs(segs) do s.t = _mh_bridge_cp_to_u8(s.t) end
        table.insert(items, segs)
    end
    _MH_LOG.send({
        kind = 'chat_history_page', req_id = req_id, page = page,
        total_pages = total_pages, total_count = total_count, items = items,
    })
end
function _MH_LOG.query_catch_loot(req_id, day_filter)
    local ok, a, b, c, d = pcall(_mh_catch_loot_query, tonumber(day_filter) or 0)
    local days, total_qty, total_types, total_opened
    if ok then
        days, total_qty, total_types, total_opened = a, b, c, d
    else
        days, total_qty, total_types, total_opened = {}, 0, 0, 0
        if mh_debug_enabled then
            mh_notify('[MH DEBUG] catch_loot_query ERROR: '..tostring(a), 0xFF5555)
        end
    end
    _MH_LOG.send({
        kind = 'catch_loot_page', req_id = req_id,
        days = type(days) == 'table' and days or {},
        total_qty = tonumber(total_qty) or 0, total_types = tonumber(total_types) or 0,
        total_opened = tonumber(total_opened) or 0,
    })
end
