function _MH_LOG.query_trades(req_id, page, day_filter, sel_date)
    local filt = {}
    for i = 1, #fh_trade_log do
        local fe = fh_trade_log[i]
        if fe and _MH_LOG.day_ok(fe.dt, day_filter, sel_date) then
            table.insert(filt, fe)
        end
    end
    local sgm, sget = 0, 0
    for _, tr in ipairs(filt) do
        sgm = sgm + (tr.give_money or 0)
        sget = sget + (tr.get_money or 0)
    end
    local total_count = #filt
    local total_pages = math.max(1, math.ceil(total_count / _MH_LOG.trade_page_size))
    if page < 1 then page = 1 end
    if page > total_pages then page = total_pages end
    local from_i = (page - 1) * _MH_LOG.trade_page_size + 1
    local to_i = math.min(page * _MH_LOG.trade_page_size, total_count)
    local items = {}
    local function conv_items(list)
        local out = {}
        for _, gi in ipairs(list or {}) do
            table.insert(out, { name = _mh_bridge_cp_to_u8(gi.name), qty = gi.qty })
        end
        return out
    end
    for i = from_i, to_i do
        local tr = filt[i]
        table.insert(items, {
            dt = tr.dt,
            partner = _mh_bridge_cp_to_u8(tr.partner or ''),
            give_money = tr.give_money, get_money = tr.get_money,
            give_items = conv_items(tr.give_items), get_items = conv_items(tr.get_items),
        })
    end
    _MH_LOG.send({
        kind = 'trades_page', req_id = req_id, page = page,
        total_pages = total_pages, total_count = total_count, items = items,
        totals = { given = sgm, received = sget },
    })
end
