function _MH_LOG.set_tg_setting(key, value)
    if not settings.telegram then settings.telegram = {} end
    local tg = settings.telegram
    local bool_keys = { enabled=true, notify_trades=true, notify_watch=true, notify_payday=true,
        notify_heartbeat=true, use_proxy=true, notify_arb=true, notify_fav=true }
    local str_keys = { bot_token=true, chat_id=true }
    if bool_keys[key] then
        tg[key] = value == true
        pcall(_wfn7p)
    elseif str_keys[key] then
        local ok, r = pcall(function() return require('encoding').CP1251:encode(value) end)
        tg[key] = ok and r or value
        pcall(_wfn7p)
    elseif key == 'arb_threshold' then
        tg.arb_threshold = tonumber(value) or 0
        pcall(_wfn7p)
    end
end
function _mh_notify_timer_next_id()
    local mx = 0
    for _, t in ipairs(settings.notify_timers or {}) do
        local id = tonumber(t.id) or 0
        if id > mx then mx = id end
    end
    return mx + 1
end
function _mh_notify_timer_normalize(t)
    if type(t) ~= 'table' then return nil end
    t.id = tonumber(t.id) or _mh_notify_timer_next_id()
    t.title = tostring(t.title or '')
    t.interval_sec = math.max(60, math.floor(tonumber(t.interval_sec) or 1800))
    t.repeats = math.max(0, math.floor(tonumber(t.repeats) or 0))
    t.fired = math.max(0, math.floor(tonumber(t.fired) or 0))
    t.enabled = t.enabled ~= false
    t.warn_enabled = t.warn_enabled == true
    t.warn_sec = math.max(60, math.floor(tonumber(t.warn_sec) or 300))
    t.next_at = tonumber(t.next_at) or 0
    t.warned = t.warned == true
    if t.enabled and t.next_at <= 0 then
        t.next_at = os.time() + t.interval_sec
        t.warned = false
    end
    return t
end
function _mh_notify_timer_emit(t, prefix)
    local title = tostring(t.title or 'Напоминание')
    local text = '[MH TIMER] {ffffff}' .. title
    if prefix and prefix ~= '' then
        text = '[MH TIMER] {ffaa00}' .. prefix .. ': {ffffff}' .. title
    end
    mh_notify_local(text, 0xFFCC66, 'reminder')
end
function _mh_notify_timer_tick()
    local now = os.time()
    for _, t in ipairs(settings.notify_timers or {}) do
        _mh_notify_timer_normalize(t)
        if t.enabled and t.next_at > 0 then
            if t.warn_enabled and not t.warned and t.interval_sec > t.warn_sec
                and now >= (t.next_at - t.warn_sec) and now < t.next_at then
                local mins = math.max(1, math.ceil(t.warn_sec / 60))
                _mh_notify_timer_emit(t, 'через ' .. tostring(mins) .. ' мин.')
                t.warned = true
            end
            if now >= t.next_at then
                _mh_notify_timer_emit(t, 'Время')
                t.fired = t.fired + 1
                if t.repeats > 0 and t.fired >= t.repeats then
                    t.enabled = false
                    t.next_at = 0
                    t.warned = false
                else
                    repeat t.next_at = t.next_at + t.interval_sec until t.next_at > now
                    t.warned = false
                end
                pcall(_wfn7p)
            end
        end
    end
end
lua_thread.create(function()
    wait(3000)
    while true do
        pcall(_mh_notify_timer_tick)
        wait(1000)
    end
end)
