function _MH_LOG.query_notify_timers(req_id)
    local out = {}
    for _, t in ipairs(settings.notify_timers or {}) do
        _mh_notify_timer_normalize(t)
        table.insert(out, {
            id=t.id, title=_mh_bridge_cp_to_u8(t.title or ''),
            interval_sec=t.interval_sec, repeats=t.repeats,
            fired=t.fired or 0, enabled=t.enabled ~= false,
            warn_enabled=t.warn_enabled == true, warn_sec=t.warn_sec or 300,
            next_at=t.next_at or 0,
        })
    end
    _MH_LOG.send({kind='notify_timers', req_id=req_id, items=out})
end
function _MH_LOG.upsert_notify_timer(data)
    if type(settings.notify_timers) ~= 'table' then settings.notify_timers = {} end
    local id = tonumber(data.id) or 0
    local found
    for _, t in ipairs(settings.notify_timers) do
        if tonumber(t.id) == id and id > 0 then found=t break end
    end
    if not found then
        found={id=_mh_notify_timer_next_id(), fired=0}
        table.insert(settings.notify_timers, found)
    end
    local title=tostring(data.title or ''):gsub('^%s+',''):gsub('%s+$','')
    if title=='' then title='Напоминание' end
    local is_new = (found.fired == 0 and found.interval_sec == nil)
    found.title=_mh_bridge_u8_to_cp(title)
    found.interval_sec=math.max(60, math.floor(tonumber(data.interval_sec) or 1800))
    found.repeats=math.max(0, math.floor(tonumber(data.repeats) or 0))
    if is_new then found.enabled=true end
    if found.enabled == nil then found.enabled=true end
    found.warn_enabled=data.warn_enabled == true
    found.warn_sec=math.max(60, math.floor(tonumber(data.warn_sec) or 300))
    found.fired=tonumber(data.reset_count)==1 and 0 or math.max(0, math.floor(tonumber(found.fired) or 0))
    if found.enabled then
        found.next_at=os.time()+found.interval_sec
        found.warned=false
    else
        found.next_at=0
        found.warned=false
    end
    pcall(_wfn7p)
    _MH_LOG.query_notify_timers(tonumber(data.req_id) or 0)
end
function _MH_LOG.toggle_notify_timer(id, enabled)
    id=tonumber(id) or 0
    for _, t in ipairs(settings.notify_timers or {}) do
        if tonumber(t.id)==id then
            t.enabled=enabled==true
            if t.enabled then
                t.fired=0
                t.next_at=os.time()+(tonumber(t.interval_sec) or 1800)
                t.warned=false
            else
                t.next_at=0
                t.warned=false
            end
            pcall(_wfn7p)
            return
        end
    end
end
function _MH_LOG.delete_notify_timer(id)
    id=tonumber(id) or 0
    for i=#settings.notify_timers,1,-1 do
        if tonumber(settings.notify_timers[i].id)==id then
            table.remove(settings.notify_timers,i)
            pcall(_wfn7p)
            return
        end
    end
end
function _MH_LOG.query_notify_history(req_id, page)
    local hist = _G.mh_notify_log or {}
    local total_count = #hist
    local total_pages = math.max(1, math.ceil(total_count / _MH_LOG.page_size))
    if page < 1 then page = 1 end
    if page > total_pages then page = total_pages end
    local from_i = total_count - (page - 1) * _MH_LOG.page_size
    local to_i = math.max(1, total_count - page * _MH_LOG.page_size + 1)
    local items = {}
    for i = from_i, to_i, -1 do
        local he = hist[i]
        if he then
            table.insert(items, {
                time = he.time, category = he.category,
                text = he.text or '',
            })
        end
    end
    _MH_LOG.send({
        kind = 'notify_history_page', req_id = req_id, page = page,
        total_pages = total_pages, total_count = total_count, items = items,
    })
end
