function _MH_LOG.on_query(data)
    if not _MH_LOG.last_query_by_kind then _MH_LOG.last_query_by_kind = {} end
    do
        local _rk = tostring(data.kind)
        if not (_rk:find('^clear_') or _rk:find('clear_history', 1, true) or _rk == 'tg_test') then
            _MH_LOG.last_query_by_kind[_rk] = data
        end
    end
    _MH_LOG.last_query = data                                        
    local kind = data.kind
    local req_id = tonumber(data.req_id) or 0
    if kind == 'deals_query' then
        local search = data.search
        if type(search) == 'string' and search ~= '' then search = _mh_bridge_u8_to_cp(search) else search = '' end
        _MH_LOG.query_deals(req_id, tonumber(data.page) or 1, search, tonumber(data.day_filter) or 0, data.date and _mh_bridge_u8_to_cp(data.date) or '')
    elseif kind == 'chat_query' then
        local search = data.search
        if type(search) == 'string' and search ~= '' then search = _mh_bridge_u8_to_cp(search) else search = '' end
        _MH_LOG.query_chat(req_id, tonumber(data.page) or 1, tonumber(data.filter) or 0, search)
    elseif kind == 'chat_dates_query' then
        _MH_LOG.query_chat_dates(req_id)
    elseif kind == 'chat_history_query' then
        local search = data.search
        if type(search) == 'string' and search ~= '' then search = _mh_bridge_u8_to_cp(search) else search = '' end
        _MH_LOG.query_chat_history(req_id, tonumber(data.day), tonumber(data.month), tonumber(data.year), tonumber(data.page) or 1, search)
    elseif kind == 'trades_query' then
        _MH_LOG.query_trades(req_id, tonumber(data.page) or 1, tonumber(data.day_filter) or 0, data.date and _mh_bridge_u8_to_cp(data.date) or '')
    elseif kind == 'catch_loot_query' then
        _MH_LOG.last_catch_q = {req_id = req_id, day_filter = tonumber(data.day_filter) or 0}
        _MH_LOG.query_catch_loot(req_id, tonumber(data.day_filter) or 0)
    elseif kind == 'clear_catch_loot' then
        _MH_LOG.clear_catch_loot()
    elseif kind == 'tg_get_settings' then
        _MH_LOG.query_tg_settings(req_id)
    elseif kind == 'tg_set_setting' then
        local v = data.value
        if type(v) == 'string' and v ~= '' then v = _mh_bridge_u8_to_cp(v) end
        _MH_LOG.set_tg_setting(data.key, v)
    elseif kind == 'tg_test' then
        _MH_LOG.tg_test()
    elseif kind == 'notify_get_settings' then
        _MH_LOG.query_notify_settings(req_id)
    elseif kind == 'notify_set_setting' then
        _MH_LOG.set_notify_setting(data.key, data.value)
    elseif kind == 'notify_timers_query' then
        _MH_LOG.query_notify_timers(req_id)
    elseif kind == 'notify_timer_upsert' then
        _MH_LOG.upsert_notify_timer(data)
    elseif kind == 'notify_timer_toggle' then
        _MH_LOG.toggle_notify_timer(data.id, data.enabled)
        _MH_LOG.query_notify_timers(req_id)
    elseif kind == 'notify_timer_delete' then
        _MH_LOG.delete_notify_timer(data.id)
        _MH_LOG.query_notify_timers(req_id)
    elseif kind == 'notify_history_query' then
        _MH_LOG.query_notify_history(req_id, tonumber(data.page) or 1)
    elseif kind == 'notify_clear_history' then
        _MH_LOG.clear_notify_history()
    elseif kind == 'overlay_get_settings' then
        _MH_LOG.query_overlay_settings(req_id)
    elseif kind == 'overlay_set_setting' then
        _MH_LOG.set_overlay_setting(data.key, data.value)
    elseif kind == 'chat_log_get_setting' then
        _MH_LOG.query_chat_log_setting(req_id)
    elseif kind == 'chat_log_set_setting' then
        _MH_LOG.set_chat_log_setting(data.value)
    elseif kind == 'clear_deals' then
        _MH_LOG.clear_deals()
    elseif kind == 'clear_trades' then
        _MH_LOG.clear_trades()
    elseif kind == 'clear_chat' then
        _MH_LOG.clear_chat()
    elseif kind == 'set_tag' then
        pcall(_mh_shops_handle_bridge_payload, data)
    end
end
if _mh_web_jar then
    _MH_LOG.onaction_prev = _mh_web_jar.onAction
    function _mh_web_jar.onAction(data)
        if not data then return end                                                               
        if data.browserid == _MH_LOG.bid then
            if data.type == "WV_STARTED" then
                _MH_LOG.state.crashed = false
                _MH_LOG.state.loaded = false
                _MH_LOG.last_query = nil
                _MH_LOG.last_query_by_kind = {}
            elseif data.type == "WV_LOADED" then
                _MH_LOG.state.loaded = true
                _MH_LOG.apply_zoom()
                if _MH_LOG.last_query_by_kind then
                    for _replay_kind, _replay_data in pairs(_MH_LOG.last_query_by_kind) do
                        local ok_lq, err_lq = pcall(_MH_LOG.on_query, _replay_data)
                        if not ok_lq and mh_debug_enabled then
                            mh_notify('[MH Дебаг] {ff5555}_MH_LOG replay ERROR ('.._replay_kind..'): '..tostring(err_lq), 0xFF5555)
                        end
                    end
                elseif _MH_LOG.last_query then
                    local ok_lq, err_lq = pcall(_MH_LOG.on_query, _MH_LOG.last_query)
                    if not ok_lq and mh_debug_enabled then
                        mh_notify('[MH Дебаг] {ff5555}_MH_LOG last_query replay ERROR: '..tostring(err_lq), 0xFF5555)
                    end
                end
            elseif data.type == "WV_PROGRESS" then
                local p = tonumber(data.msg)
                if p and p > _MH_LOG.state.progress then _MH_LOG.state.progress = p end
            elseif data.type == "WV_DIE" then
                _MH_LOG.state.crashed = true
                _MH_LOG.state.created = false
                pcall(function() _mh_web_jar.deleteBrowser(_MH_LOG.bid) end)
            elseif data.type == "WV_ANSWER" then
                local raw_msg = tostring(data.msg or '')
                local prefix = 'MH_BRIDGE:'
                local idx = raw_msg:find(prefix, 1, true)
                if mh_debug_enabled then
                    mh_notify('[MH Дебаг] {aaaaaa}_MH_LOG WV_ANSWER raw='..raw_msg:sub(1,80), 0xFFFFFF)
                end
                if idx then
                    local json_part = raw_msg:sub(idx + #prefix)
                    local ok_js, js_obj = pcall(decodeJson, json_part)
                    if ok_js and type(js_obj) == 'table' and js_obj.kind then
                        if mh_debug_enabled then
                            mh_notify('[MH Дебаг] {55ff55}_MH_LOG on_query kind='..tostring(js_obj.kind), 0x55FF55)
                        end
                        local ok_oq, err_oq = pcall(_MH_LOG.on_query, js_obj)
                        if not ok_oq and mh_debug_enabled then
                            mh_notify('[MH Дебаг] {ff5555}_MH_LOG on_query ERROR: '..tostring(err_oq), 0xFF5555)
                        end
                    elseif mh_debug_enabled then
                        mh_notify('[MH Дебаг] {ff5555}_MH_LOG decodeJson FAILED ok='..tostring(ok_js), 0xFF5555)
                    end
                end
            end
            return
        end
        if _MH_LOG.onaction_prev then _MH_LOG.onaction_prev(data) end
    end
end
function _mh_log_hide()
