            _MH_LOG.state.created  = true
            _MH_LOG.state.loaded   = false
            _MH_LOG.state.crashed  = false
            _MH_LOG.state.progress = 0
            _MH_LOG.state.visible_applied = false
        end
    end
    if _MH_LOG.state.created then
        if not _MH_LOG.state.visible_applied then
            pcall(function()
                _mh_web_jar.setClickable(_MH_LOG.bid, true)
                _mh_web_jar.setVisible(_MH_LOG.bid, true)
