    if imgui.Button(fa.MAGNIFYING_GLASS_PLUS .. '##mh_log_zoom_in', imgui.ImVec2(30*d, 0)) then
        _MH_LOG.set_zoom(settings.mh_web.log_zoom + 0.1)
    end
