    if imgui.Button(fa.ROTATE_RIGHT .. '##mh_log_reload') and _mh_web_jar then
        _MH_LOG.state.loaded = false
        _MH_LOG.state.progress = 0
        pcall(function() _mh_web_jar.changeUrl(_MH_LOG.bid, _MH_LOG.build_url()) end)
    end
    imgui.Separator()
    local cp = imgui.GetCursorPos()
    local screen_pos = imgui.GetCursorScreenPos()
    local avail = imgui.GetContentRegionAvail()
    local px, py = screen_pos.x, screen_pos.y
    local pw, ph = avail.x, avail.y
    if _MH_LOG.state.created and _mh_web_jar then
        local pos = _MH_LOG.state.pos
        if pos.x ~= px or pos.y ~= py then
            pcall(function() _mh_web_jar.setPos(_MH_LOG.bid, px, py) end)
        end
        if pos.w ~= pw or pos.h ~= ph then
            pcall(function() _mh_web_jar.setSize(_MH_LOG.bid, pw, ph) end)
        end
        _MH_LOG.state.pos = {x = px, y = py, w = pw, h = ph}
    end
    if _MH_LOG.state.crashed then
        imgui.SetCursorPos(imgui.ImVec2(cp.x, cp.y + ph/2 - 10))
        _mh_web_center_text(u8'\xd1\xf2\xf0\xe0\xed\xe8\xf6\xe0 \xef\xf0\xe8\xeb\xee\xe6\xe5\xed\xe8\xff \xef\xf0\xe5\xf0\xe2\xe0\xeb\xe0\xf1\xfc (crash) :(')
        imgui.SetCursorPos(imgui.ImVec2(cp.x, cp.y + ph/2 + 12))
        if imgui.Button(fa.ROTATE_RIGHT .. ' ' .. u8'\xcf\xe5\xf0\xe5\xe7\xe0\xef\xf3\xf1\xf2\xe8\xf2\xfc##mh_log_retry', imgui.ImVec2(160*d, 0)) then
            _MH_LOG.state.created = false
        end
    elseif not _MH_LOG.state.loaded then
        imgui.SetCursorPos(imgui.ImVec2(cp.x, cp.y + ph/2 - 10))
        local pct = _MH_LOG.state.progress
        if type(pct) == "number" and pct > 0 and pct < 100 then
            _mh_web_center_text(u8'\xc7\xe0\xe3\xf0\xf3\xe7\xea\xe0 \xf1\xe0\xe9\xf2\xe0... ' .. pct .. '%%')
        else
            _mh_web_center_text(u8'\xc7\xe0\xe3\xf0\xf3\xe7\xea\xe0 \xf1\xe0\xe9\xf2\xe0...')
        end
    end
    imgui.Dummy(imgui.ImVec2(pw, ph))
end
