    return {
        enabled       = s.enabled ~= false,
        pos_h         = s.pos_h or 'right',
        pos_v         = s.pos_v or 'bottom',
        width         = s.width or 320,
        corner_radius = s.corner_radius or 8,
        accent_width  = s.accent_width or 4,
        padding_x     = s.padding_x or 14,
        padding_y     = s.padding_y or 10,
        spacing       = s.spacing or 8,
        margin_x      = s.margin_x or 18,
        margin_y      = s.margin_y or 18,
        duration      = s.duration or 6.0,
        anim_speed    = s.anim_speed or 10.0,
        max_visible   = s.max_visible or 5,
        font_scale    = s.font_scale or 1.0,
        bg_r = s.bg_r or 0.08, bg_g = s.bg_g or 0.08, bg_b = s.bg_b or 0.10, bg_a = s.bg_a or 0.90,
        text_r = s.text_r or 0.94, text_g = s.text_g or 0.94, text_b = s.text_b or 0.96,
        border_enabled = s.border_enabled == true,
        border_r = s.border_r or 1.0, border_g = s.border_g or 1.0, border_b = s.border_b or 1.0,
        border_a = s.border_a or 0.25, border_size = s.border_size or 1.0,
