            buy_status  = nf.buy_status  ~= false,
            watch       = nf.watch       ~= false,
            fav         = nf.fav         ~= false,
            arb         = nf.arb         ~= false,
            reminder    = nf.reminder    ~= false,
            other       = nf.other       ~= false,
        },
        history_max = settings.notify_history_max or 500,
    }
end
function _mh_theme.build_window_state()
    local d = tonumber(settings.general and settings.general.custom_dpi) or 1
    local sw = settings.mh_win
    local w = (sw and sw.w and sw.w / d) or 900
    local h = (sw and sw.h and sw.h / d) or 520
    if w < 760 then w = 900 end
    if h < 480 then h = 520 end
    return { w = w, h = h }
end
