            accent      = settings.mh_theme.accent,
            accent2     = settings.mh_theme.accent2,
            bg          = settings.mh_theme.bg,
            panel       = settings.mh_theme.panel,
            panel2      = settings.mh_theme.panel2,
            text        = settings.mh_theme.text,
            text_dim    = settings.mh_theme.text_dim,
            line        = settings.mh_theme.line,
            font_scale  = settings.mh_theme.font_scale,
            panel_alpha = settings.mh_theme.panel_alpha,
