function _mh_theme.apply_all()
    _mh_theme.sync_imgui_accent()
    _mh_apply_toast_settings()
    _mh_theme.push_state()
end
function _mh_theme.handle_bridge_payload(data)
    if type(data) ~= 'table' or not data.kind then return end
    if data.kind == 'ready' then
        pcall(_mh_theme.push_state)
        return
    end
    if data.kind == 'theme_update' and type(data.theme) == 'table' then
        for k, v in pairs(data.theme) do
            if settings.mh_theme[k] ~= nil then settings.mh_theme[k] = v end
        end
        pcall(_wfn7p)
        _mh_theme.apply_all()
    elseif data.kind == 'theme_preset' and data.name and _mh_theme_presets[data.name] then
        local p = _mh_theme_presets[data.name]
        settings.mh_theme.preset   = data.name
        settings.mh_theme.accent   = p.accent
        settings.mh_theme.accent2  = p.accent2
        settings.mh_theme.bg       = p.bg
        settings.mh_theme.panel   = p.panel
        settings.mh_theme.panel2  = p.panel2
        settings.mh_theme.text    = p.text
        settings.mh_theme.text_dim = p.text_dim
        settings.mh_theme.line    = p.line
        pcall(_wfn7p)
        _mh_theme.apply_all()
    elseif data.kind == 'toast_update' and type(data.toast) == 'table' then
        if not settings.toast then settings.toast = {} end
        for k, v in pairs(data.toast) do
            settings.toast[k] = v
        end
        pcall(_wfn7p)
        _mh_apply_toast_settings()
        _mh_theme.push_state()
    elseif data.kind == 'toast_filter_update' and data.key then
        if not settings.notify_filters then settings.notify_filters = {} end
        settings.notify_filters[data.key] = data.value == true
        pcall(_wfn7p)
        _mh_theme.push_state()
    elseif data.kind == 'toast_history_max' and data.value then
        settings.notify_history_max = math.floor(tonumber(data.value) or 500)
        pcall(_wfn7p)
    elseif data.kind == 'toast_test' then
        mh_notify('[MH] {aaffaa}Тестовое уведомление — так будут выглядеть плашки', 0xFFFFFF)
    elseif data.kind == 'window_size_update' then
        local d = tonumber(settings.general and settings.general.custom_dpi) or 1
        local sw = settings.mh_win or {}
        if data.w then
            local w = math.max(760, math.min(1600, tonumber(data.w) or 900))
            sw.w = w * d
        end
        if data.h then
            local h = math.max(480, math.min(1200, tonumber(data.h) or 520))
            sw.h = h * d
        end
        if not sw.w then sw.w = 900 * d end
        if not sw.h then sw.h = 520 * d end
        if not sw.x then sw.x = sizeX/2 - sw.w/2 end
        if not sw.y then sw.y = sizeY/2 - sw.h/2 end
        settings.mh_win = sw
        _G._mh_win_reset = true
        pcall(_wfn7p)
        _mh_theme.push_state()
    end
end
