function _mh_premium.build_state()
    return {
        kind          = 'state',
        activated     = settings.premium and settings.premium.activated == true,
        user          = settings.premium and settings.premium.user or '',
        nick          = settings.premium and settings.premium.nick or '',
        key           = settings.premium and settings.premium.key or '',
        expires       = settings.premium and settings.premium.expires or '',
        server        = _mh_premium_current_server_name(),
        server_id     = (function()
            local ok, idx = pcall(_mpf7d)
            if ok and tonumber(idx or 0) and idx > 0 then
                return (ARZ_SERVERS[idx + 1] or {}).id or -1
            end
            local boot = tonumber(_G.mh_boot_srv_idx or 0) or 0
            if boot > 0 then return (ARZ_SERVERS[boot + 1] or {}).id or -1 end
            if _G.arz_srv_sel then
                local sel = tonumber(_G.arz_srv_sel[0] or 0) or 0
                return (ARZ_SERVERS[sel + 1] or {}).id or -1
            end
            return -1
        end)(),
        checking      = _prem_checking == true,
        check_status  = _prem_check_status or '',
    }
end
function _mh_premium.push_state()
    if not (_mh_web_jar and _mh_premium.state.created and _mh_premium.state.loaded) then return end
    lua_thread.create(function()
        wait(0)
        local ok_j, j = pcall(encodeJson, _mh_premium.build_state())
        if not ok_j or type(j) ~= 'string' then return end
        local ok_b64, b64 = pcall(function() return require('basexx').to_base64(j) end)
        if not ok_b64 or not b64 then return end
        pcall(function()
            _mh_web_jar.executeJS(_mh_premium.bid, "window.mhReceiveState && window.mhReceiveState('" .. b64 .. "');")
        end)
    end)
end
_mh_premium_ticker_active = false
function _mh_premium_start_ticker()
    if _mh_premium_ticker_active then return end
    _mh_premium_ticker_active = true
    lua_thread.create(function()
        while _mh_premium.state.created do
            wait(500)
            _mh_premium.push_state()
            if not _prem_checking then break end
        end
        _mh_premium_ticker_active = false
    end)
end
function _mh_premium.handle_bridge_payload(data)
    if type(data) ~= 'table' or not data.kind then return end
    if data.kind == 'premium_activate' and data.key and tostring(data.key) ~= '' then
        local key_entered = tostring(data.key):gsub('^%s+',''):gsub('%s+$','')
        _fpc2t(key_entered, function(ok2, user2)
            if ok2 then
                local _exp2 = settings.premium.expires or ''
                local _nick2 = settings.premium.nick or ''
                local _msg = '[MH] {FFD700}Premium Активирован!'
                if _nick2 ~= '' then _msg = _msg .. ' {ffffff}Ник: {FFD700}' .. _nick2 end
                if _exp2 ~= '' then
                    _msg = _msg .. ' {aaaaaa}| {ffffff}До: ' .. _exp2
                else
                    _msg = _msg .. ' {aaaaaa}| {ff8800}Срок: не задан'
                end
                mh_notify(_msg, 0xFFFFFF)
            end
            _mh_premium.push_state()
        end)
        _mh_premium_start_ticker()
        _mh_premium.push_state()
    elseif data.kind == 'premium_deactivate' then
        settings.premium.activated = false
        settings.premium.key       = ''
        settings.premium.user      = ''
        _mh_reset_prem()
        _wfn7p()
        _mh_premium.push_state()
    elseif data.kind == 'premium_open_link' and data.url then
        local _known = { tg_buy = 'https://t.me/MHARIZONAbot' }
        local _url = _known[data.url]
        if _url then
            if _cvh6z() then
                pcall(gta._Z12AND_OpenLinkPKc, _url)
            else
                os.execute('start ' .. _url)
            end
        end
    end
end
if _mh_web_jar then
    _mh_premium._onAction_prev = _mh_web_jar.onAction
    function _mh_web_jar.onAction(data)
        if not data then return end                                                               
        if data.browserid == _mh_premium.bid then
            if data.type == "WV_STARTED" then
                _mh_premium.state.crashed = false
                _mh_premium.state.loaded = false
            elseif data.type == "WV_LOADED" then
                _mh_premium.state.loaded = true
                _mh_premium.push_state()
            elseif data.type == "WV_PROGRESS" then
                local p = tonumber(data.msg)
                if p and p > _mh_premium.state.progress then _mh_premium.state.progress = p end
            elseif data.type == "WV_DIE" then
                _mh_premium.state.crashed = true
                _mh_premium.state.created = false
                pcall(function() _mh_web_jar.deleteBrowser(_mh_premium.bid) end)
            elseif data.type == "WV_ANSWER" then
                local _raw_msg = tostring(data.msg or '')
                local _prefix = 'MH_BRIDGE:'
                local _idx = _raw_msg:find(_prefix, 1, true)
                if _idx then
                    local _json_part = _raw_msg:sub(_idx + #_prefix)
                    local _ok_js, _js_obj = pcall(decodeJson, _json_part)
                    if _ok_js and type(_js_obj) == 'table' and _js_obj.kind then
                        pcall(_mh_premium.handle_bridge_payload, _js_obj)
                    end
                end
            end
            return
        end
        if _mh_premium._onAction_prev then _mh_premium._onAction_prev(data) end
    end
end
