                for _, lv in ipairs(mh_arz_data or {}) do
                    if type(lv) == 'table' and lv.items_sell and lv.price_sell then
                        for ii, iid in ipairs(lv.items_sell) do
                            local raw_id = tostring(iid or ''):match('^(%d+)')
                            local item_nm = raw_id and mh_arz_items_db and mh_arz_items_db[tonumber(raw_id)]
                            local shop_price = tonumber(lv.price_sell[ii])
                            if item_nm and item_nm ~= '' and shop_price and shop_price > 0 then
                                table.insert(built, {
                                    name       = item_nm,
                                    shop_price = shop_price,
                                    uid        = lv.LavkaUid or 0,
                                    owner      = lv.username or '',
                                })
                                if not price_idx[item_nm] then price_idx[item_nm] = {} end
