            local function _mh_pick_shop_anchor(item_name)
                local arr = _G._mh_pick_price_idx and _G._mh_pick_price_idx[item_name]
                if not arr or #arr == 0 then return nil end
                if #arr <= 2 then return arr[math.ceil(#arr / 2)] end
                local q1 = arr[math.max(1, math.ceil(#arr * 0.25))]
                local q3 = arr[math.min(#arr, math.ceil(#arr * 0.75))]
                local iqr = q3 - q1
                local med = arr[math.ceil(#arr / 2)]
                local fence = math.max(iqr * 3, med * 0.7)
                local lo, hi = med - fence, med + fence
                local clean = {}
                for _, v in ipairs(arr) do
                    if v >= lo and v <= hi then table.insert(clean, v) end
                end
                if #clean == 0 then return med end
                return clean[math.ceil(#clean / 2)]
            end
            local function _mh_pick_avg_price(item_name)
                if not item_name or item_name == '' then return nil end
                local anchor = _mh_pick_shop_anchor(item_name)
                local function _within_anchor(v)
                    if not v or v <= 0 then return false end
                    if not anchor or anchor <= 0 then return true end
                    local r = v > anchor and (v / anchor) or (anchor / v)
                    return r < 2.5
                end
                local best = nil
                local function _consider(v)
                    if _within_anchor(v) and (not best or v < best) then best = v end
                end
                local ok, mp = pcall(_mh_get_mkt_price, item_name)
                if ok and mp then
                    _consider(mp.today)
                    _consider(mp.avg7)
                    _consider(mp.avg30)
