                        local ok3, s1  = pcall(_mjg5t, hist, 1,  _today_anchor)
                        local ok4, s7  = pcall(_mjg5t, hist, 7,  _today_anchor)
                        local ok5, s30 = pcall(_mjg5t, hist, 30, _today_anchor)
                        if ok3 and s1  and s1.avg  then _consider(s1.avg)  end
                        if ok4 and s7  and s7.avg  then _consider(s7.avg)  end
                        if ok5 and s30 and s30.avg then _consider(s30.avg) end
                    end
                end
                if anchor and anchor > 0 then _consider(anchor) end
                if not best and anchor and anchor > 0 then best = anchor end
                if best then return best end
                local base = _G.mh_pick_basedb[item_name]
                if base and base > 0 then return base end
