function _mh_price_dbg(msg)
    if not (mh_debug_enabled or mh_pktdbg_enabled) then return end
    pcall(function()
        local _pth = getWorkingDirectory():gsub('\\','/') .. '/mrkfdbg.log'
        local _fh = io.open(_pth, 'a')
        if _fh then
            _fh:write('[' .. os.date('%H:%M:%S') .. '] ' .. tostring(msg) .. '\n')
            _fh:close()
        end
    end)
end
function _mh_price_line_for_text(text)
    local _price_line = nil
    local _ok_price, _err_price = pcall(function()
        if not text or text == '' then return end
        local _clean = text:gsub('{%x%x%x%x%x%x}', '')
        local _first_line = nil
        for _line in (_clean .. '\n'):gmatch('([^\n]*)\n') do
            local _trimmed = _line:match('^%s*(.-)%s*$')
            if _trimmed and _trimmed ~= '' then
                _first_line = _trimmed
                break
            end
        end
        if not _first_line then return end
        local _after_colon = _first_line:match('^[^:]+:%s*(.+)$')
        local _candidates = {}
        if _after_colon and _after_colon ~= '' then
            table.insert(_candidates, _after_colon)
        end
        table.insert(_candidates, _first_line)
        local _resolved_nm = nil
        for _, _cand in ipairs(_candidates) do
            local _canon, _found = _mh_norm_nm and _mh_norm_nm(_cand)
            if _found then
                _resolved_nm = _canon
                break
            end
        end
        if not _resolved_nm then
            for _, _cand in ipairs(_candidates) do
                if (fh_mkt_prices and fh_mkt_prices[_cand]) or (fh_mkt_lavka and fh_mkt_lavka[_cand]) then
                    _resolved_nm = _cand
                    break
                end
            end
        end
        if not _resolved_nm then
            local _cand_lo = {}
            for _, _cand in ipairs(_candidates) do _cand_lo[#_cand_lo+1] = _cand:lower() end
            if fh_mkt_prices then
                for _k in pairs(fh_mkt_prices) do
                    local _k_lo = _k:lower()
                    for _, _cl in ipairs(_cand_lo) do
                        if _k_lo == _cl then _resolved_nm = _k; break end
                    end
                    if _resolved_nm then break end
                end
            end
            if not _resolved_nm and fh_mkt_lavka then
                for _k in pairs(fh_mkt_lavka) do
                    local _k_lo = _k:lower()
                    for _, _cl in ipairs(_cand_lo) do
                        if _k_lo == _cl then _resolved_nm = _k; break end
                    end
                    if _resolved_nm then break end
                end
            end
        end
        if not _resolved_nm then
            local _idx_size = 0
            if _mh_items_rev_idx then
                for _ in pairs(_mh_items_rev_idx) do _idx_size = _idx_size + 1 end
            end
            _mh_price_dbg('PRICE INJECT: имя НЕ распознано, candidates=[' .. table.concat(_candidates, ' | ')
                .. '] | items_loaded=' .. tostring(mh_arz_items_loaded)
                .. ' items_loading=' .. tostring(mh_arz_items_loading)
                .. ' rev_idx_size=' .. tostring(_idx_size))
            return
        end
        local function _mh_fmt_dots(n)
            if not n then return nil end
            n = math.floor(n)
            if n <= 0 then return nil end
            local _s = tostring(n)
            local _out = ''
            local _cnt = 0
            for i = #_s, 1, -1 do
                _out = _s:sub(i,i) .. _out
                _cnt = _cnt + 1
                if _cnt % 3 == 0 and i > 1 then _out = '.' .. _out end
            end
            return _out
        end
        local _mp = _mh_get_mkt_price and _mh_get_mkt_price(_resolved_nm)
        local _avg_val = _mp and (_mp.avg7 or _mp.today or _mp.avg30) or nil
        local _sell_val, _buy_val = nil, nil
        local _dtl_srv_for_key = (type(_mh_cloud_current_server_id) == 'function') and _mh_cloud_current_server_id() or -1
        local _dtl_key_now = _resolved_nm .. '|' .. tostring(_dtl_srv_for_key)
        if _G._dtl_cache_nm == _dtl_key_now then
            local _sr_live = _G._dtl_sell_rows
            local _br_live = _G._dtl_buy_rows
            if _sr_live and #_sr_live > 0 and _sr_live[1].price and _sr_live[1].price > 0 then
                _sell_val = _sr_live[1].price
            end
            if _br_live and #_br_live > 0 and _br_live[1].price and _br_live[1].price > 0 then
                _buy_val = _br_live[1].price
            end
        end
        local _fe = fh_mkt_prices and fh_mkt_prices[_resolved_nm]
        if not _sell_val and _fe and _fe.s_min and _fe.s_min > 0 then _sell_val = _fe.s_min end
        if not _buy_val  and _fe and _fe.b_max and _fe.b_max > 0 then _buy_val  = _fe.b_max end
        local _le = fh_mkt_lavka and fh_mkt_lavka[_resolved_nm]
        if not _sell_val and _le and _le.s_min and _le.s_min > 0 then _sell_val = _le.s_min end
        if not _buy_val  and _le and _le.b_max and _le.b_max > 0 then _buy_val  = _le.b_max end
        if not _avg_val and not _sell_val and not _buy_val then
            _mh_price_dbg('PRICE INJECT: имя распознано как "' .. _resolved_nm
                .. '", НО данных о цене нет (avg=' .. tostring(_avg_val)
                .. ' sell=' .. tostring(_sell_val) .. ' buy=' .. tostring(_buy_val)
                .. ' fh_mkt_prices_has_entry=' .. tostring(_fe ~= nil)
                .. ' fh_mkt_lavka_has_entry=' .. tostring(_le ~= nil) .. ')')
            return
        end
        local _parts = {}
        if _avg_val then
            table.insert(_parts, '\xd1\xf0\xe5\xe4\xed\xff\xff: $' .. (_mh_fmt_dots(_avg_val) or '0'))
        end
        if _sell_val then
            table.insert(_parts, '\xcf\xf0\xee\xe4\xe0\xfe\xf2: $' .. (_mh_fmt_dots(_sell_val) or '0'))
        end
        if _buy_val then
            table.insert(_parts, '\xd1\xea\xf3\xef\xe0\xfe\xf2: $' .. (_mh_fmt_dots(_buy_val) or '0'))
        end
        if #_parts == 0 then return end
        _price_line = '\n\n{66CCFF}[MH] ' .. table.concat(_parts, '{FFFFFF}, {66CCFF}') .. '{FFFFFF}'
        _mh_price_dbg('PRICE INJECT: успех, имя="' .. _resolved_nm .. '" line=' .. _price_line)
    end)
    if not _ok_price then
        pcall(function()
            local _pth = getWorkingDirectory():gsub('\\','/') .. '/mrkfdbg.log'
            local _fh = io.open(_pth, 'a')
            if _fh then
                _fh:write('PRICE INJECT ERROR: ' .. tostring(_err_price) .. '\n')
                _fh:close()
            end
        end)
    end
    return _price_line
end
function _mh_inject_price_line(text, style, _price_line)
    local _real_text = (text or ''):gsub('%z+$', '')
    if style == 1 then
        local _trimmed_end = _real_text:gsub('%s+$', '')
        local _last_line = _trimmed_end:match('([^\n]*)$') or ''
        if _last_line:match(':%s*$') then
            local _head, _tail = _trimmed_end:match('^(.-)\n([^\n]*)$')
            if _head and _tail then
                return _head .. _price_line .. '\n\n' .. _tail
            end
        end
    end
    return _real_text .. _price_line
end
function sampev.onShowDialog(dialogId, style, title, button1, button2, text)
