                    local new_text = string.gsub(text, '(\xcf\xee\xe8\xf1\xea \xef\xee \xed\xe0\xe7\xe2\xe0\xed\xe8\xfe\t%s)\n', '%1\n{00FF00}' .. scan_label .. '\t \n{FFAA00}' .. deep_label .. '\t \n', 1)
