        is_mkt = (fh_last_dlg_title or ''):find('Средняя цена товаров при продаже') ~= nil
    end
    if is_mkt then
    end
    if is_mkt and fh_mkt_cp_deep_scanning then
        return { dialogId, button, listItem, inputText }
