            mh_notify('[MH Market] {ffaa00}Углублённый скан запущен!', 0xFFFFFF)
            local _was_main_open_outer = MainWindow[0]
            MainWindow[0] = false
            local txt0 = mh_dlg_text() or ''
            local dlg0 = dialogId
            lua_thread.create(function()
                local _was_main_open = _was_main_open_outer
                local function deep_idx_offset(text)
                    if text and (
                        text:find('\xd1\xea\xe0\xed\xe8\xf0\xee\xe2\xe0\xf2\xfc \xe2\xf1\xe5 \xf6\xe5\xed\xfb [MH]', 1, true)
                        or text:find('\xd3\xe3\xeb\xf3\xe1\xeb\xb8\xed\xed\xfb\xe9 \xf1\xea\xe0\xed [MH]', 1, true)
                    ) then return 2 end
                    return 0
                end
                local stats = _mh_deep_engine({
                    tag = '[MH Market]', list_id = 15073, dlg0 = dlg0, txt0 = txt0,
                    rtt0 = 1200, to_min = 3000, to_k = 5, to_add = 1500, to_max = 20000,
                    lost_ms = 25000,
                    is_active  = function() return fh_mkt_cp_deep_scanning end,
                    parse_list = function(tx) return _G._nqh8s(tx, 5) end,
                    idx_offset = deep_idx_offset,
                    is_detail  = function(title) return (title or ''):find('Продажа товара') ~= nil end,
                    parse_detail = function(tx, title) return MH_util.jfw5v(tx, title) end,
                    on_detail = function(detail)
                        fh_mkt_save_cp_detail(detail.name, detail.history)
                        lua_thread.create(function() wait(200); _G._mh_upload_deals() end)
                    end,
                    on_progress = function(n)
