                        printStyledString('~w~MH deep: ~y~'..n, 1000, 6)
                    end,
                })
                fh_mkt_cp_deep_scanning = false
                _ryb5t()
                if sampIsDialogActive() then
                    sampSendDialogResponse(sampGetCurrentDialogId(), 0, 0, '')
                end
                MainWindow[0] = _was_main_open
                local _skip_s = (stats.skipped > 0) and (' (пропущено: ' .. stats.skipped .. ')') or ''
                if stats.aborted then
                    mh_notify('[MH Market] {ffaa00}Скан остановлен: ' .. _mh_deep_abort_text(stats.aborted) .. '. Снято: ' .. fh_mkt_cp_deep_done .. _skip_s, 0xFFFFFF)
                else
