                wait(400)
                printStyledString('~w~MH DONE: ~g~'..fh_mkt_cp_deep_done, 3000, 6)
            end)
            return false
        end
        if button == 1 and listItem > fh_mkt_cp_deep_go_idx then
            fh_mkt_cp_deep_go_idx = nil
            return { dialogId, button, listItem - 2, inputText }
        end
