    local is_auto_resp = (dialogId == 15376)
    if is_auto_resp and fh_mkt_auto_deep_scanning then
        return { dialogId, button, listItem, inputText }
    end
    if is_auto_resp and not fh_mkt_auto_deep_scanning and fh_mkt_auto_deep_go_idx ~= nil then
        if button == 1 and listItem == fh_mkt_auto_deep_go_idx then
            fh_mkt_auto_deep_go_idx = nil
            fh_mkt_auto_deep_scanning = true
            fh_mkt_auto_deep_done = 0
            mh_notify('[MH Auto] {ffaa00}Углублённый скан авторынка запущен!', 0xFFFFFF)
            local txt0 = mh_dlg_text() or ''
            local dlg0 = dialogId
            lua_thread.create(function()
                local function auto_idx_offset(text)
                    if text and (
                        text:find('Сканировать все авто [MH]', 1, true)
                        or text:find('Углублённый скан авто [MH]', 1, true)
                    ) then return 2 end
                    return 0
                end
                local stats = _mh_deep_engine({
                    tag = '[MH Auto]', list_id = 15376, dlg0 = dlg0, txt0 = txt0,
                    rtt0 = 500, to_min = 800, to_k = 4, to_add = 500, to_max = 15000,
                    lost_ms = 25000,
                    is_active  = function() return fh_mkt_auto_deep_scanning end,
                    parse_list = function(tx) return fh_mkt_parse_auto_list(tx) end,
                    idx_offset = auto_idx_offset,
                    is_detail  = function(title) return true end,
                    parse_detail = function(tx, title) return fh_mkt_parse_auto_detail(tx, title) end,
                    on_detail = function(detail)
                        fh_mkt_save_auto_detail(detail.name, detail.history)
                        if _mh_auto_invalidate_cache then pcall(_mh_auto_invalidate_cache) end
                    end,
                    on_progress = function(n)
                        fh_mkt_auto_deep_done = n
                        printStyledString('~w~MH Auto deep: ~y~'..n, 1000, 6)
                    end,
                })
                fh_mkt_auto_deep_scanning = false
                _ryb5t()
                lua_thread.create(function() wait(1000); _G._mh_auto_prices_push() end)
                if sampIsDialogActive() then sampSendDialogResponse(sampGetCurrentDialogId(), 0, 0, '') end
                local _skip_s = (stats.skipped > 0) and (' (пропущено: ' .. stats.skipped .. ')') or ''
                if stats.aborted then
                    mh_notify('[MH Auto] {ffaa00}Скан остановлен: ' .. _mh_deep_abort_text(stats.aborted) .. '. Снято: ' .. fh_mkt_auto_deep_done .. _skip_s, 0xFFFFFF)
                else
                    mh_notify('[MH Auto] {00cc00}Углублённый скан завершён! Авто: '..fh_mkt_auto_deep_done .. _skip_s, 0xFFFFFF)
                end
                printStyledString('~w~MH Auto DONE: ~g~'..fh_mkt_auto_deep_done, 3000, 6)
            end)
            return false
        end
        if button == 1 and fh_mkt_auto_deep_go_idx and listItem > fh_mkt_auto_deep_go_idx then
            fh_mkt_auto_deep_go_idx = nil
            return { dialogId, button, listItem - 2, inputText }
        end
        fh_mkt_auto_deep_go_idx = nil
    end
    if is_auto_resp and not fh_mkt_auto_scanning and fh_mkt_auto_go_idx ~= nil then
        if button == 1 and listItem == fh_mkt_auto_go_idx then
            local txt = mh_dlg_text() or ''
            local nxt = fh_find_listitem(txt, 'Следующая страница')
            if nxt == nil then
                mh_notify('[MH Auto] {ff4444}Ошибка: нет след. страницы!', 0xFFFFFF)
                fh_mkt_auto_go_idx = nil
                return { dialogId, 0, listItem, inputText }
            end
            fh_mkt_auto_scanning  = true
            fh_mkt_auto_prev_text = txt
            fh_mkt_auto_page      = 1
            mh_notify('[MH Auto] {ffaa00}Скан авторынка запущен. Не открывайте другие диалоги!', 0xFFFFFF)
            _gyc9t(txt)
            local tot = 0; for _ in pairs(fh_mkt_auto) do tot = tot + 1 end
            printStyledString('~w~MH Auto p.1: ~r~' .. tot, 2000, 6)
            local fixed_a = nxt - 2
            fh_mkt_auto_go_idx = nil
            return { dialogId, 1, fixed_a, inputText }
        end
        fh_mkt_auto_go_idx = nil
        return { dialogId, button, listItem - 2, inputText }
    end
end
