        end
        _G._lvn7s()
    end
end
addEventHandler("onShowDialog", function(dialogId, style, title, button1, button2, text)
    if not mh_pktdbg_enabled then return end
    local _ok_dbg, _err_dbg = pcall(function()
        local _title = tostring(title or '')
        local _text  = tostring(text or '')
        local _path = getWorkingDirectory():gsub('\\','/') .. '/mrkfdbg.log'
        local _f = io.open(_path, 'a')
        if _f then
            _f:write(string.rep('-',60) .. '\n')
            _f:write(string.format('DLG     id=%-6s  style=%s\n',
                tostring(dialogId), tostring(style)))
            _f:write('  title  : ' .. _title:sub(1,80) .. '\n')
            _f:write('  btn1   : ' .. tostring(button1 or ''):sub(1,40) .. '\n')
            _f:write('  btn2   : ' .. tostring(button2 or ''):sub(1,40) .. '\n')
            _f:write(string.format('  text   : (%d chars)\n', #_text))
            local _ln = 0
            for _line in (_text:sub(1,1200) .. '\n'):gmatch('([^\n]*)\n') do
                _f:write('    ' .. _line .. '\n')
                _ln = _ln + 1; if _ln >= 24 then _f:write('    ...(truncated)\n'); break end
            end
            local _sid = _text:match('server_id[=:%s]+(%d+)') or _text:match('serverId[=:%s]+(%d+)')
            if _sid then _f:write('  [server_id found in text]: ' .. _sid .. '\n') end
            _f:write('\n')
            _f:close()
        end
    end)
    if not _ok_dbg then
        pcall(function()
            local _path2 = getWorkingDirectory():gsub('\\','/') .. '/mrkfdbg.log'
            local _f2 = io.open(_path2, 'a')
            if _f2 then
                _f2:write(string.rep('-',60) .. '\n')
                _f2:write('DLG HANDLER ERROR id=' .. tostring(dialogId)
                    .. ' err=' .. tostring(_err_dbg) .. '\n\n')
                _f2:close()
            end
        end)
    end
end)
local _mh_dbg_orig_onshowdialog = sampev.onShowDialog
