addEventHandler("onSendPacket", function(packet_id, bs)
    if packet_id ~= 220 then return end
    if not mh_filelog_enabled then return end
    local ok, res = pcall(function()
        local pos = raknetBitStreamGetNumberOfBitsUsed(bs)
        raknetBitStreamIgnoreBits(bs, 8)
        local marker = raknetBitStreamReadInt8(bs)
        local iface  = raknetBitStreamReadInt8(bs)
        local id     = raknetBitStreamReadInt32(bs)
        local subid  = raknetBitStreamReadInt32(bs)
        local len    = raknetBitStreamReadInt16(bs)
        local json_s = (len and len > 0) and raknetBitStreamReadString(bs, len) or ''
        _mh_flog('SEND PKT220 iface='..tostring(iface)..' id='..tostring(id)..' sub='..tostring(subid)..' json='..json_s:sub(1,300))
        if mh_pktdbg_enabled then
            local _ok_sj, _sjt = pcall(decodeJson, json_s)
            local _send_iface_names = {
                [4]='MARKET_ACTION',[6]='SHOP_BROWSE',[7]='SHOP_ITEM_REQ',
                [8]='SHOP_ACTION',[57]='TRADE',[60]='SLOT_CLICK',[255]='CLOSE_MENU',
            }
            local _path = getWorkingDirectory():gsub('\\','/') .. '/mrkfdbg.log'
            local _f2 = io.open(_path, 'a')
            if _f2 then
                _f2:write(string.rep('-',60) .. '\n')
                _f2:write(string.format('SEND >>> PKT220  iface=%-3d  sub=%-4d  id=%s\n',
                    iface, subid, tostring(id)))
                _f2:write('  iface_name: ' .. (_send_iface_names[iface] or '?') .. '\n')
                if iface == 60 and subid == 2 and _ok_sj and type(_sjt)=='table' then
                    _f2:write('  [SLOT CLICK — запрос предмета]\n')
                    _f2:write(string.format('  slot   : %s\n', tostring(_sjt.slot or '?')))
                    _f2:write(string.format('  id     : %s\n', tostring(_sjt.id or '?')))
                    _f2:write(string.format('  type   : %s  (13=продажа, 28=скупка)\n', tostring(_sjt.type or '?')))
                    _f2:write(string.format('  amount : %s  (цена в лавке)\n', tostring(_sjt.amount or '?')))
                    local _bid = _sjt.id and _G._bqs3v and _G._bqs3v(tonumber(_sjt.id))
                    local _bnm = _bid and mh_arz_items_db and mh_arz_items_db[_bid]
                    if _bnm then _f2:write('  item   : "' .. _bnm .. '"\n') end
                elseif json_s ~= '' then
                    _f2:write('  json: ' .. json_s:sub(1,400) .. '\n')
                end
                _f2:write('\n')
                _f2:close()
            end
        end
        if iface == 255 then
            local _age = _G._mh_qpop_pending_time and (os.clock() - _G._mh_qpop_pending_time) or 99
            if _age > 3.0 then
                _G._mh_qpop_pending_id    = nil
                _G._mh_qpop_pending_nm    = nil
                _G._mh_qpop_pending_time  = nil
                _G._mh_qpop_pending_price = nil
            end
            if _G._ao_session_open then
                _G._ao_session_open = false
            end
        end
        if iface == 60 and subid == 2 and json_s ~= '' then
            local _click_id  = tonumber(json_s:match('"id"%s*:%s*(%d+)'))
            local _click_type = tonumber(json_s:match('"type"%s*:%s*(%d+)'))
            if _click_id and (_click_type == 13 or _click_type == 28) then
                local _click_nm = mh_arz_items_db and mh_arz_items_db[_click_id] or nil
                if not _click_nm or _click_nm == '' then
                    local _click_slot = tonumber(json_s:match('"slot"%s*:%s*(%d+)'))
                    if fh_other_shop_cur and _click_slot then
                        local _lst = _click_type == 13 and fh_other_shop_cur.sell_items or fh_other_shop_cur.buy_items
                        for _, _si in ipairs(_lst or {}) do
                            if _si.slot == _click_slot and type(_si.name) == 'string' and _si.name ~= '' then
                                _click_nm = _si.name; break
                            end
                        end
                    end
                end
                _G._mh_qpop_pending_id    = _click_id
                _G._mh_qpop_pending_nm    = _click_nm or ''
                _G._mh_qpop_pending_time  = os.clock()
            end
        end
        raknetBitStreamResetReadPointer(bs)
    end)
    if not ok then _mh_flog('SEND PKT220 err: '..tostring(res)) end
end)
addEventHandler("onReceivePacket", function(packet_id, bs)
    if mh_pktdbg_enabled and packet_id ~= 220 then
        _G._mh_rawpkt_freq = _G._mh_rawpkt_freq or {}
        _G._mh_rawpkt_freq[packet_id] = (_G._mh_rawpkt_freq[packet_id] or 0) + 1
    end
    if packet_id ~= 220 then return end
    raknetBitStreamIgnoreBits(bs, 8)
    local marker = raknetBitStreamReadInt8(bs)
    if marker ~= 84 then return end
    local iface  = raknetBitStreamReadInt8(bs)
    local subid  = raknetBitStreamReadInt8(bs)
    local json_s = _dkn5v(bs)
    if not json_s then return end
    _mh_flog('PKT220 iface=' .. iface .. ' sub=' .. subid .. ' json=' .. json_s:sub(1,200))
    if mh_pktdbg_enabled then
        local _dbg_lines = {}
        function _dbl(s) table.insert(_dbg_lines, s) end
        _dbl(string.rep('-', 60))
        _dbl(string.format('RECV <<< PKT220  iface=%-3d  sub=%-3d', iface, subid))
        local _iface_names = {
            [4]  = 'MARKET (ЦР)',
            [6]  = 'SHOP_LIST (список лавок)',
            [7]  = 'SHOP_ITEMS (товары лавки)',
            [8]  = 'SHOP_ACTION (действие)',
            [57] = 'TRADE (трейд)',
            [60] = 'SLOT_CLICK (клик слота)',
        }
        local _iname = _iface_names[iface] or '?'
        _dbl('  iface_name : ' .. _iname)
        local _sub_names = {
            [0]  = 'open/reset',
            [1]  = 'update/info',
            [2]  = 'items/click',
            [3]  = 'confirm',
            [15] = 'menu_overlay',
        }
        _dbl('  sub_name   : ' .. (_sub_names[subid] or '?'))
        local _ok_j, _jt = pcall(decodeJson, json_s)
        if _ok_j and type(_jt) == 'table' then
            local _fields = {
                'id','type','slot','amount','count','price',
                'name','owner','username','server_id','serverId',
                'LavkaUid','shop_num','title','text','items',
                'sell','buy','server','server_name',
            }
            _dbl('  --- Ключевые поля ---')
            for _, _fk in ipairs(_fields) do
